"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import { Slot } from "@radix-ui/react-slot";
import { cn } from "@/lib/utils";

export interface PrimaryButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  asChild?: boolean;
}

/**
 * Framer University-inspired shine sweep on hover.
 * Uses logo gradient streak colors for the sweep overlay.
 */
const PrimaryButton = React.forwardRef<HTMLButtonElement, PrimaryButtonProps>(
  ({ className, children, asChild = false, ...props }, ref) => {
    const prefersReducedMotion = useReducedMotion();
    const Comp = asChild ? Slot : motion.button;

    const sharedClassName = cn(
      "relative inline-flex h-11 items-center justify-center overflow-hidden rounded-sm px-6 text-sm font-medium text-text-on-dark",
      "bg-primary transition-colors duration-300 hover:bg-accent",
      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
      "disabled:pointer-events-none disabled:opacity-50",
      className,
    );

    if (asChild) {
      return (
        <Comp className={sharedClassName} ref={ref} {...props}>
          {children}
        </Comp>
      );
    }

    return (
      <Comp
        ref={ref}
        className={sharedClassName}
        whileHover={prefersReducedMotion ? undefined : { scale: 1.02 }}
        whileTap={prefersReducedMotion ? undefined : { scale: 0.98 }}
        {...props}
      >
        <span className="relative z-10 flex items-center gap-2">{children}</span>
        {!prefersReducedMotion && (
          <motion.span
            aria-hidden
            className="pointer-events-none absolute inset-0 opacity-0"
            style={{
              background:
                "linear-gradient(105deg, transparent 20%, rgba(72,202,228,0.35) 40%, rgba(247,127,0,0.4) 55%, rgba(252,191,73,0.35) 70%, transparent 85%)",
            }}
            initial={{ x: "-100%" }}
            whileHover={{ x: "100%", opacity: 1 }}
            transition={{ duration: 0.6, ease: "easeInOut" }}
          />
        )}
      </Comp>
    );
  },
);
PrimaryButton.displayName = "PrimaryButton";

export { PrimaryButton };

"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { Search } from "lucide-react";
import { designSystem } from "@/lib/design-tokens";
import { cn } from "@/lib/utils";

interface TableRow {
  label: string;
  value: string;
  change: string;
  positive?: boolean;
}

interface BrowserTab {
  id: string;
  label: string;
  url: string;
  stats: { label: string; value: string; color: string }[];
  table: TableRow[];
}

const tabs: BrowserTab[] = [
  {
    id: "ppc",
    label: "PPC Dashboard",
    url: "sellercentral.amazon.com/ppc/campaigns",
    stats: [
      { label: "ACOS", value: "18.2%", color: "var(--color-brandCyan)" },
      { label: "Ad Sales", value: "$84.2K", color: "var(--color-brandYellow)" },
      { label: "ROAS", value: "5.4x", color: "var(--color-brandMint)" },
    ],
    table: [
      { label: "Brand Defense", value: "$12,400", change: "+24%", positive: true },
      { label: "Auto Campaign", value: "$8,920", change: "+18%", positive: true },
      { label: "Exact Match", value: "$6,150", change: "-4%", positive: false },
      { label: "Product Targeting", value: "$4,280", change: "+31%", positive: true },
    ],
  },
  {
    id: "seo",
    label: "Listing SEO",
    url: "sellercentral.amazon.com/listing/optimizer",
    stats: [
      { label: "Listing Score", value: "92/100", color: "var(--color-brandYellow)" },
      { label: "Indexed Keywords", value: "148", color: "var(--color-brandCyan)" },
      { label: "Organic Rank", value: "#3", color: "var(--color-brandMint)" },
    ],
    table: [
      { label: "amazon ppc agency", value: "Position 3", change: "+2", positive: true },
      { label: "amazon account management", value: "Position 5", change: "+4", positive: true },
      { label: "full service amazon", value: "Position 8", change: "+1", positive: true },
      { label: "amazon seller services", value: "Position 12", change: "-1", positive: false },
    ],
  },
  {
    id: "analytics",
    label: "Account Analytics",
    url: "sellercentral.amazon.com/analytics/overview",
    stats: [
      { label: "Revenue", value: "$312K", color: "var(--color-brandYellow)" },
      { label: "Units Sold", value: "4,820", color: "var(--color-brandCyan)" },
      { label: "Buy Box %", value: "97%", color: "var(--color-brandMint)" },
    ],
    table: [
      { label: "Top ASIN — B09XYZ", value: "$48,200", change: "+42%", positive: true },
      { label: "Category Rank", value: "#14", change: "+6", positive: true },
      { label: "Return Rate", value: "2.1%", change: "-0.3%", positive: true },
      { label: "Inventory Health", value: "Good", change: "Stable", positive: true },
    ],
  },
];

interface BrowserMockupProps {
  className?: string;
  autoRotate?: boolean;
}

export function BrowserMockup({
  className,
  autoRotate = true,
}: BrowserMockupProps) {
  const [activeTab, setActiveTab] = React.useState(tabs[0].id);
  const prefersReducedMotion = useReducedMotion();
  const interval =
    typeof designSystem.components.browserMockup === "object" &&
    designSystem.components.browserMockup !== null &&
    "autoRotateInterval" in designSystem.components.browserMockup
      ? Number(
          (designSystem.components.browserMockup as { autoRotateInterval: number })
            .autoRotateInterval,
        )
      : 8000;

  React.useEffect(() => {
    if (!autoRotate || prefersReducedMotion) return;

    const timer = window.setInterval(() => {
      setActiveTab((current) => {
        const index = tabs.findIndex((t) => t.id === current);
        return tabs[(index + 1) % tabs.length].id;
      });
    }, interval);

    return () => window.clearInterval(timer);
  }, [autoRotate, interval, prefersReducedMotion]);

  const current = tabs.find((t) => t.id === activeTab) ?? tabs[0];

  return (
    <div
      className={cn(
        "overflow-hidden rounded-lg border border-border shadow-lg",
        className,
      )}
    >
      <div className="flex h-10 items-center gap-2 border-b border-border bg-surface px-4">
        <div className="flex gap-1.5">
          <span className="h-3 w-3 rounded-full bg-border-strong" />
          <span className="h-3 w-3 rounded-full bg-border" />
          <span className="h-3 w-3 rounded-full bg-border" />
        </div>
        <div className="ml-2 flex flex-1 gap-1 overflow-x-auto">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              type="button"
              onClick={() => setActiveTab(tab.id)}
              className={cn(
                "rounded-sm px-3 py-1 text-xs font-medium transition-colors",
                activeTab === tab.id
                  ? "bg-background text-text-primary shadow-sm"
                  : "text-text-secondary hover:text-text-primary",
              )}
              aria-selected={activeTab === tab.id}
              role="tab"
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      <div className="bg-background p-6">
        <div className="flex items-center gap-2 rounded-md border border-border px-3 py-2 text-small text-text-secondary">
          <Search className="h-4 w-4 shrink-0" />
          <AnimatePresence mode="wait">
            <motion.span
              key={current.url}
              initial={prefersReducedMotion ? false : { opacity: 0, y: 4 }}
              animate={{ opacity: 1, y: 0 }}
              exit={prefersReducedMotion ? undefined : { opacity: 0, y: -4 }}
              transition={{ duration: 0.2 }}
              className="truncate"
            >
              {current.url}
            </motion.span>
          </AnimatePresence>
        </div>

        <AnimatePresence mode="wait">
          <motion.div
            key={current.id}
            initial={prefersReducedMotion ? false : { opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            exit={prefersReducedMotion ? undefined : { opacity: 0, y: -12 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="mt-6"
          >
            <div className="grid gap-4 sm:grid-cols-3">
              {current.stats.map((stat, i) => (
                <motion.div
                  key={stat.label}
                  initial={prefersReducedMotion ? false : { opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: prefersReducedMotion ? 0 : i * 0.08 }}
                  className="rounded-md border border-border bg-surface p-4"
                >
                  <p
                    className="text-stat"
                    style={{ color: stat.color }}
                  >
                    {stat.value}
                  </p>
                  <p className="text-small text-text-secondary">{stat.label}</p>
                </motion.div>
              ))}
            </div>

            <div className="mt-6 overflow-hidden rounded-md border border-border">
              <table className="w-full text-left text-small">
                <thead>
                  <tr className="border-b border-border bg-surface-muted">
                    <th className="px-4 py-3 font-medium">Metric</th>
                    <th className="px-4 py-3 font-medium">Value</th>
                    <th className="px-4 py-3 font-medium text-right">Change</th>
                  </tr>
                </thead>
                <tbody>
                  {current.table.map((row, i) => (
                    <motion.tr
                      key={row.label}
                      initial={prefersReducedMotion ? false : { opacity: 0, x: -8 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{
                        delay: prefersReducedMotion ? 0 : 0.15 + i * 0.06,
                        duration: 0.35,
                      }}
                      className="border-b border-border last:border-0"
                    >
                      <td className="px-4 py-3">{row.label}</td>
                      <td className="px-4 py-3 font-medium">{row.value}</td>
                      <td
                        className={cn(
                          "px-4 py-3 text-right font-medium",
                          row.positive ? "text-success" : "text-error",
                        )}
                      >
                        {row.change}
                      </td>
                    </motion.tr>
                  ))}
                </tbody>
              </table>
            </div>
          </motion.div>
        </AnimatePresence>
      </div>
    </div>
  );
}

