  const [activeTab, setActiveTab] = React.useState(tabs[0].id);
  const [expandedRow, setExpandedRow] = React.useState<string | null>(null);
  const [isPaused, setIsPaused] = React.useState(false);
  const prefersReducedMotion = useReducedMotion();
  const tabListRef = React.useRef<HTMLDivElement>(null);

  const interval =
    typeof designSystem.components.browserMockup === "object" &&
    designSystem.components.browserMockup !== null &&
    "autoRotateInterval" in designSystem.components.browserMockup
      ? Number(
          (designSystem.components.browserMockup as { autoRotateInterval: number })
            .autoRotateInterval,
        )
      : 8000;

  React.useEffect(() => {
    if (!autoRotate || prefersReducedMotion || isPaused) return;

    const timer = window.setInterval(() => {
      setActiveTab((current) => {
        const index = tabs.findIndex((t) => t.id === current);
        return tabs[(index + 1) % tabs.length].id;
      });
      setExpandedRow(null);
    }, interval);

    return () => window.clearInterval(timer);
  }, [autoRotate, interval, prefersReducedMotion, isPaused]);

  const selectTab = (id: string) => {
    setActiveTab(id);
    setExpandedRow(null);
    setIsPaused(true);
  };

  const handleTabKeyDown = (e: React.KeyboardEvent, index: number) => {
    let nextIndex = index;
    if (e.key === "ArrowRight") nextIndex = (index + 1) % tabs.length;
    else if (e.key === "ArrowLeft") nextIndex = (index - 1 + tabs.length) % tabs.length;
    else return;

    e.preventDefault();
    selectTab(tabs[nextIndex].id);
    const buttons = tabListRef.current?.querySelectorAll<HTMLButtonElement>('[role="tab"]');
    buttons?.[nextIndex]?.focus();
  };

  const current = tabs.find((t) => t.id === activeTab) ?? tabs[0];

  return (
    <div
      className={cn(
        "overflow-hidden rounded-lg border border-border shadow-lg",
        className,
      )}
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
    >
      <div className="flex h-10 items-center gap-2 border-b border-border bg-surface px-4">
        <div className="flex gap-1.5" aria-hidden="true">
          <span className="h-3 w-3 rounded-full bg-border-strong" />
          <span className="h-3 w-3 rounded-full bg-border" />
          <span className="h-3 w-3 rounded-full bg-border" />
        </div>
        <div
          ref={tabListRef}
          className="ml-2 flex flex-1 gap-1 overflow-x-auto"
          role="tablist"
          aria-label="Dashboard views"
        >
          {tabs.map((tab, index) => (
            <button
              key={tab.id}
              type="button"
              id={`tab-${tab.id}`}
              onClick={() => selectTab(tab.id)}
              onKeyDown={(e) => handleTabKeyDown(e, index)}
              className={cn(
                "rounded-sm px-3 py-1 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent",
                activeTab === tab.id
                  ? "bg-background text-text-primary shadow-sm"
                  : "text-text-secondary hover:text-text-primary",
              )}
              aria-selected={activeTab === tab.id}
              role="tab"
              tabIndex={activeTab === tab.id ? 0 : -1}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      <div
        className="bg-background p-6"
        role="tabpanel"
        id={`panel-${current.id}`}
        aria-labelledby={`tab-${current.id}`}
      >
        <div className="flex items-center gap-2 rounded-md border border-border px-3 py-2 text-small text-text-secondary">
          <Search className="h-4 w-4 shrink-0" aria-hidden="true" />
          <AnimatePresence mode="wait">
            <motion.span
              key={current.url}
              initial={prefersReducedMotion ? false : { opacity: 0, y: 4 }}
              animate={{ opacity: 1, y: 0 }}
              exit={prefersReducedMotion ? undefined : { opacity: 0, y: -4 }}
              transition={{ duration: 0.2 }}
              className="truncate"
            >
              {current.url}
            </motion.span>
          </AnimatePresence>
        </div>

        <AnimatePresence mode="wait">
          <motion.div
            key={current.id}
            initial={prefersReducedMotion ? false : { opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            exit={prefersReducedMotion ? undefined : { opacity: 0, y: -12 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="mt-6"
          >
            <div className="mb-6 flex h-16 items-end gap-1 rounded-md border border-border bg-surface p-4">
              {current.chart.map((height, i) => (
                <motion.div
                  key={`${current.id}-bar-${i}`}
                  className="flex-1 rounded-sm bg-primary/20"
                  initial={prefersReducedMotion ? false : { height: 0 }}
                  animate={{ height: `${height}%` }}
                  transition={{
                    delay: prefersReducedMotion ? 0 : i * 0.04,
                    duration: 0.4,
                    ease: "easeOut",
                  }}
                  style={{ maxHeight: "100%" }}
                >
                  <div
                    className="h-full w-full rounded-sm"
                    style={{
                      background: `linear-gradient(180deg, var(--color-brandCyan) 0%, var(--color-brandYellow) 100%)`,
                      opacity: 0.7 + height / 300,
                    }}
                  />
                </motion.div>
              ))}
            </div>

            <div className="grid gap-4 sm:grid-cols-3">
              {current.stats.map((stat, i) => (
                <motion.div
                  key={stat.label}
                  initial={prefersReducedMotion ? false : { opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: prefersReducedMotion ? 0 : i * 0.08 }}
                  className="rounded-md border border-border bg-surface p-4"
                >
                  <p className="text-stat" style={{ color: stat.color }}>
                    {stat.value}
                  </p>
                  <p className="text-small text-text-secondary">{stat.label}</p>
                  <div className="mt-3 h-1.5 overflow-hidden rounded-full bg-border">
                    <motion.div
                      className="h-full rounded-full"
                      style={{ backgroundColor: stat.color }}
                      initial={prefersReducedMotion ? false : { width: 0 }}
                      animate={{ width: `${stat.progress}%` }}
                      transition={{ delay: 0.2 + i * 0.1, duration: 0.6 }}
                    />
                  </div>
                </motion.div>
              ))}
            </div>

            <div className="mt-6 overflow-hidden rounded-md border border-border">
              <table className="w-full text-left text-small">
                <thead>
                  <tr className="border-b border-border bg-surface">
                    <th className="px-4 py-3 font-medium" scope="col">Metric</th>
                    <th className="px-4 py-3 font-medium" scope="col">Value</th>
                    <th className="px-4 py-3 text-right font-medium" scope="col">Change</th>
                    <th className="w-8 px-2" scope="col"><span className="sr-only">Expand</span></th>
                  </tr>
                </thead>
                <tbody>
                  {current.table.map((row, i) => (
                    <React.Fragment key={row.label}>
                      <motion.tr
                        initial={prefersReducedMotion ? false : { opacity: 0, x: -8 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{
                          delay: prefersReducedMotion ? 0 : 0.15 + i * 0.06,
                          duration: 0.35,
                        }}
                        className={cn(
                          "cursor-pointer border-b border-border transition-colors last:border-0 hover:bg-surface",
                          expandedRow === row.label && "bg-surface",
                        )}
                        onClick={() =>
                          setExpandedRow(expandedRow === row.label ? null : row.label)
                        }
                      >
                        <td className="px-4 py-3">{row.label}</td>
                        <td className="px-4 py-3 font-medium">{row.value}</td>
                        <td
                          className={cn(
                            "px-4 py-3 text-right font-medium",
                            row.positive ? "text-success" : "text-error",
                          )}
                        >
                          {row.change}
                        </td>
                        <td className="px-2 py-3 text-text-secondary">
                          {expandedRow === row.label ? (
                            <ChevronDown className="h-4 w-4" aria-hidden="true" />
                          ) : (
                            <ChevronRight className="h-4 w-4" aria-hidden="true" />
                          )}
                        </td>
                      </motion.tr>
                      <AnimatePresence>
                        {expandedRow === row.label && row.detail && (
                          <motion.tr
                            initial={prefersReducedMotion ? false : { opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={prefersReducedMotion ? undefined : { opacity: 0 }}
                          >
                            <td colSpan={4} className="bg-surface px-4 py-2 text-small text-text-secondary">
                              {row.detail}
                            </td>
                          </motion.tr>
                        )}
                      </AnimatePresence>
                    </React.Fragment>
                  ))}
                </tbody>
              </table>
            </div>
            <p className="text-small mt-3 text-text-secondary">
              Click any row to expand details. Tabs auto-rotate every 8s (pauses on hover).
            </p>
          </motion.div>
        </AnimatePresence>
      </div>
    </div>
  );
}

