"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Lock,
  Share,
} from "lucide-react";
import { designSystem } from "@/lib/design-tokens";
import { cn } from "@/lib/utils";

interface TableRow {
  label: string;
  value: string;
  change: string;
  positive?: boolean;
  detail?: string;
}

interface BrowserTab {
  id: string;
  label: string;
  shortLabel: string;
  url: string;
  stats: { label: string; value: string; progress: number }[];
  chart: number[];
  table: TableRow[];
}

const tabs: BrowserTab[] = [
  {
    id: "ppc",
    label: "PPC Dashboard",
    shortLabel: "PPC",
    url: "sellercentral.amazon.com/ppc/campaigns",
    stats: [
      { label: "ACOS", value: "18.2%", progress: 72 },
      { label: "Ad Sales", value: "$84.2K", progress: 85 },
      { label: "ROAS", value: "5.4x", progress: 91 },
    ],
    chart: [42, 58, 45, 72, 68, 84, 79, 92, 88, 95],
    table: [
      { label: "Brand Defense", value: "$12,400", change: "+24%", positive: true, detail: "12 keywords · 8.2% ACOS" },
      { label: "Auto Campaign", value: "$8,920", change: "+18%", positive: true, detail: "847 targets · 14.1% ACOS" },
      { label: "Exact Match", value: "$6,150", change: "-4%", positive: false, detail: "34 keywords · 22.8% ACOS" },
      { label: "Product Targeting", value: "$4,280", change: "+31%", positive: true, detail: "156 ASINs · 11.5% ACOS" },
    ],
  },
  {
    id: "seo",
    label: "Listing SEO",
    shortLabel: "SEO",
    url: "sellercentral.amazon.com/listing/optimizer",
    stats: [
      { label: "Listing Score", value: "92/100", progress: 92 },
      { label: "Indexed Keywords", value: "148", progress: 74 },
      { label: "Organic Rank", value: "#3", progress: 88 },
    ],
    chart: [28, 35, 42, 55, 61, 68, 74, 82, 88, 92],
    table: [
      { label: "amazon ppc agency", value: "Position 3", change: "+2", positive: true, detail: "1,240 monthly searches" },
      { label: "amazon account management", value: "Position 5", change: "+4", positive: true, detail: "890 monthly searches" },
      { label: "full service amazon", value: "Position 8", change: "+1", positive: true, detail: "620 monthly searches" },
      { label: "amazon seller services", value: "Position 12", change: "-1", positive: false, detail: "410 monthly searches" },
    ],
  },
  {
    id: "analytics",
    label: "Account Analytics",
    shortLabel: "Analytics",
    url: "sellercentral.amazon.com/analytics/overview",
    stats: [
      { label: "Revenue", value: "$312K", progress: 94 },
      { label: "Units Sold", value: "4,820", progress: 78 },
      { label: "Buy Box %", value: "97%", progress: 97 },
    ],
    chart: [55, 62, 58, 71, 76, 82, 88, 91, 94, 97],
    table: [
      { label: "Top ASIN — B09XYZ", value: "$48,200", change: "+42%", positive: true, detail: "1,240 units · 4.8 rating" },
      { label: "Category Rank", value: "#14", change: "+6", positive: true, detail: "Sports & Outdoors" },
      { label: "Return Rate", value: "2.1%", change: "-0.3%", positive: true, detail: "Below category avg 3.8%" },
      { label: "Inventory Health", value: "Good", change: "Stable", positive: true, detail: "42 days cover · FBA" },
    ],
  },
];

interface BrowserMockupProps {
  className?: string;
  autoRotate?: boolean;
}

export function BrowserMockup({
  className,
  autoRotate = true,
}: BrowserMockupProps) {
  const [activeTab, setActiveTab] = React.useState(tabs[0].id);
  const [expandedRow, setExpandedRow] = React.useState<string | null>(null);
  const [isPaused, setIsPaused] = React.useState(false);
  const prefersReducedMotion = useReducedMotion();
  const tabListRef = React.useRef<HTMLDivElement>(null);

  const interval =
    typeof designSystem.components.browserMockup === "object" &&
    designSystem.components.browserMockup !== null &&
    "autoRotateInterval" in designSystem.components.browserMockup
      ? Number(
          (designSystem.components.browserMockup as { autoRotateInterval: number })
            .autoRotateInterval,
        )
      : 8000;

  React.useEffect(() => {
    if (!autoRotate || prefersReducedMotion || isPaused) return;

    const timer = window.setInterval(() => {
      setActiveTab((current) => {
        const index = tabs.findIndex((t) => t.id === current);
        return tabs[(index + 1) % tabs.length].id;
      });
      setExpandedRow(null);
    }, interval);

    return () => window.clearInterval(timer);
  }, [autoRotate, interval, prefersReducedMotion, isPaused]);

  const selectTab = (id: string) => {
    setActiveTab(id);
    setExpandedRow(null);
    setIsPaused(true);
  };

  const handleTabKeyDown = (e: React.KeyboardEvent, index: number) => {
    let nextIndex = index;
    if (e.key === "ArrowRight") nextIndex = (index + 1) % tabs.length;
    else if (e.key === "ArrowLeft") nextIndex = (index - 1 + tabs.length) % tabs.length;
    else return;

    e.preventDefault();
    selectTab(tabs[nextIndex].id);
    const buttons = tabListRef.current?.querySelectorAll<HTMLButtonElement>(
      '[role="tab"]',
    );
    buttons?.[nextIndex]?.focus();
  };

  const current = tabs.find((t) => t.id === activeTab) ?? tabs[0];
  const maxChart = Math.max(...current.chart);

  return (
    <div
      className={cn("mx-auto max-w-2xl", className)}
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
    >
      {/* iOS device frame */}
      <div className="overflow-hidden rounded-[2rem] border border-border bg-[#F2F2F7] shadow-lg">
        {/* Status bar */}
        <div className="flex items-center justify-between px-6 pt-3 pb-1">
          <span className="text-[11px] font-semibold text-text-primary">9:41</span>
          <div className="h-5 w-24 rounded-full bg-primary" aria-hidden="true" />
          <div className="flex items-center gap-1" aria-hidden="true">
            <span className="text-[10px] font-medium text-text-primary">5G</span>
            <span className="h-2.5 w-5 rounded-sm border border-text-primary" />
          </div>
        </div>

        {/* Safari toolbar */}
        <div className="flex items-center gap-2 px-4 pb-2">
          <button
            type="button"
            className="flex h-8 w-8 items-center justify-center rounded-full bg-white/60 text-text-secondary"
            aria-hidden="true"
            tabIndex={-1}
          >
            <ChevronLeft className="h-4 w-4" />
          </button>
          <div className="flex flex-1 items-center gap-2 rounded-full bg-white px-3 py-2 shadow-sm">
            <Lock className="h-3 w-3 shrink-0 text-text-secondary" aria-hidden="true" />
            <AnimatePresence mode="wait">
              <motion.span
                key={current.url}
                initial={prefersReducedMotion ? false : { opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={prefersReducedMotion ? undefined : { opacity: 0 }}
                transition={{ duration: 0.15 }}
                className="truncate text-[11px] text-text-primary"
              >
                {current.url}
              </motion.span>
            </AnimatePresence>
          </div>
          <button
            type="button"
            className="flex h-8 w-8 items-center justify-center rounded-full bg-white/60 text-text-secondary"
            aria-hidden="true"
            tabIndex={-1}
          >
            <Share className="h-3.5 w-3.5" />
          </button>
        </div>

        {/* iOS segmented control */}
        <div className="px-4 pb-3">
          <div
            ref={tabListRef}
            className="flex rounded-lg bg-[#E5E5EA] p-0.5"
            role="tablist"
            aria-label="Dashboard views"
          >
            {tabs.map((tab, index) => (
              <button
                key={tab.id}
                type="button"
                id={`tab-${tab.id}`}
                onClick={() => selectTab(tab.id)}
                onKeyDown={(e) => handleTabKeyDown(e, index)}
                className={cn(
                  "flex-1 rounded-md px-2 py-1.5 text-[11px] font-medium transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent",
                  activeTab === tab.id
                    ? "bg-white text-text-primary shadow-sm"
                    : "text-text-secondary",
                )}
                aria-selected={activeTab === tab.id}
                role="tab"
                tabIndex={activeTab === tab.id ? 0 : -1}
              >
                <span className="hidden sm:inline">{tab.label}</span>
                <span className="sm:hidden">{tab.shortLabel}</span>
              </button>
            ))}
          </div>
        </div>

        {/* Content panel */}
        <div
          className="bg-background px-4 pb-5"
          role="tabpanel"
          id={`panel-${current.id}`}
          aria-labelledby={`tab-${current.id}`}
        >
          <AnimatePresence mode="wait">
            <motion.div
              key={current.id}
              initial={prefersReducedMotion ? false : { opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={prefersReducedMotion ? undefined : { opacity: 0, y: -8 }}
              transition={{ duration: 0.25, ease: "easeOut" }}
            >
              {/* Chart — single navy tone, accent on peak bar only */}
              <div className="mb-4 flex h-14 items-end gap-1 rounded-xl border border-border bg-surface p-3">
                {current.chart.map((height, i) => {
                  const isPeak = height === maxChart;
                  return (
                    <motion.div
                      key={`${current.id}-bar-${i}`}
                      className="flex-1 rounded-sm"
                      initial={prefersReducedMotion ? false : { height: 0 }}
                      animate={{ height: `${height}%` }}
                      transition={{
                        delay: prefersReducedMotion ? 0 : i * 0.03,
                        duration: 0.35,
                        ease: "easeOut",
                      }}
                      style={{
                        maxHeight: "100%",
                        backgroundColor: isPeak
                          ? "var(--color-accent)"
                          : "var(--color-primary)",
                        opacity: isPeak ? 1 : 0.15 + (height / maxChart) * 0.55,
                      }}
                    />
                  );
                })}
              </div>

              {/* Stats — navy text, neutral progress bars */}
              <div className="grid grid-cols-3 gap-2">
                {current.stats.map((stat, i) => (
                  <motion.div
                    key={stat.label}
                    initial={prefersReducedMotion ? false : { opacity: 0, y: 6 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: prefersReducedMotion ? 0 : i * 0.06 }}
                    className="rounded-xl border border-border bg-surface p-3"
                  >
                    <p className="text-base font-semibold text-text-primary">
                      {stat.value}
                    </p>
                    <p className="mt-0.5 text-[10px] text-text-secondary">
                      {stat.label}
                    </p>
                    <div className="mt-2 h-1 overflow-hidden rounded-full bg-border">
                      <motion.div
                        className="h-full rounded-full bg-primary"
                        initial={prefersReducedMotion ? false : { width: 0 }}
                        animate={{ width: `${stat.progress}%` }}
                        transition={{ delay: 0.15 + i * 0.08, duration: 0.5 }}
                      />
                    </div>
                  </motion.div>
                ))}
              </div>

              {/* Table */}
              <div className="mt-4 overflow-hidden rounded-xl border border-border">
                <table className="w-full text-left text-[11px]">
                  <thead>
                    <tr className="border-b border-border bg-surface">
                      <th className="px-3 py-2 font-medium text-text-secondary" scope="col">
                        Metric
                      </th>
                      <th className="px-3 py-2 font-medium text-text-secondary" scope="col">
                        Value
                      </th>
                      <th className="px-3 py-2 text-right font-medium text-text-secondary" scope="col">
                        Change
                      </th>
                      <th className="w-6" scope="col">
                        <span className="sr-only">Expand</span>
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    {current.table.map((row, i) => (
                      <React.Fragment key={row.label}>
                        <motion.tr
                          initial={prefersReducedMotion ? false : { opacity: 0 }}
                          animate={{ opacity: 1 }}
                          transition={{
                            delay: prefersReducedMotion ? 0 : 0.1 + i * 0.05,
                          }}
                          className={cn(
                            "cursor-pointer border-b border-border transition-colors last:border-0 active:bg-surface",
                            expandedRow === row.label && "bg-surface",
                          )}
                          onClick={() =>
                            setExpandedRow(
                              expandedRow === row.label ? null : row.label,
                            )
                          }
                        >
                          <td className="px-3 py-2.5 text-text-primary">
                            {row.label}
                          </td>
                          <td className="px-3 py-2.5 font-medium text-text-primary">
                            {row.value}
                          </td>
                          <td
                            className={cn(
                              "px-3 py-2.5 text-right font-medium",
                              row.positive ? "text-success" : "text-error",
                            )}
                          >
                            {row.change}
                          </td>
                          <td className="px-1 text-text-secondary">
                            {expandedRow === row.label ? (
                              <ChevronDown className="h-3 w-3" aria-hidden="true" />
                            ) : (
                              <ChevronRight className="h-3 w-3" aria-hidden="true" />
                            )}
                          </td>
                        </motion.tr>
                        <AnimatePresence>
                          {expandedRow === row.label && row.detail && (
                            <motion.tr
                              initial={prefersReducedMotion ? false : { opacity: 0 }}
                              animate={{ opacity: 1 }}
                              exit={prefersReducedMotion ? undefined : { opacity: 0 }}
                            >
                              <td
                                colSpan={4}
                                className="bg-surface px-3 py-2 text-[10px] text-text-secondary"
                              >
                                {row.detail}
                              </td>
                            </motion.tr>
                          )}
                        </AnimatePresence>
                      </React.Fragment>
                    ))}
                  </tbody>
                </table>
              </div>

              <p className="mt-3 text-center text-[10px] text-text-secondary">
                Tap a row for details · Segments auto-switch every 8s
              </p>
            </motion.div>
          </AnimatePresence>
        </div>

        {/* iOS home indicator */}
        <div className="flex justify-center pb-2 pt-1">
          <div className="h-1 w-28 rounded-full bg-primary/20" aria-hidden="true" />
        </div>
      </div>
    </div>
  );
}

