import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import { Slot } from "@radix-ui/react-slot";
import { cn } from "@/lib/utils";

export interface PrimaryButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  asChild?: boolean;
}

/**
 * Custom minimal motion — sleek lift + soft shadow + gold fill.
 * No heavy Framer effects (no shine, 3D flip, shader, or stagger).
 */
const PrimaryButton = React.forwardRef<HTMLButtonElement, PrimaryButtonProps>(
  ({ className, children, asChild = false, ...props }, ref) => {
    const prefersReducedMotion = useReducedMotion();

    const sharedClassName = cn(
      "relative inline-flex h-11 items-center justify-center rounded-sm px-6 text-sm font-medium text-text-on-dark",
      "bg-primary shadow-sm transition-colors duration-300 ease-out hover:bg-accent",
      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
      "disabled:pointer-events-none disabled:opacity-50",
      className,
    );

    if (asChild) {
      return (
        <Slot className={sharedClassName} ref={ref} {...props}>
          {children}
        </Slot>
      );
    }

    return (
      <motion.button
        ref={ref}
        type={props.type ?? "button"}
        disabled={props.disabled}
        onClick={props.onClick}
        className={sharedClassName}
        whileHover={
          prefersReducedMotion
            ? undefined
            : { y: -1, boxShadow: "0 6px 20px rgba(11, 27, 58, 0.15)" }
        }
        whileTap={prefersReducedMotion ? undefined : { y: 0, scale: 0.99 }}
        transition={{ duration: 0.25, ease: [0.25, 0.1, 0.25, 1] }}
      >
        {children}
      </motion.button>
    );
  },
);
PrimaryButton.displayName = "PrimaryButton";

export { PrimaryButton };

