import { cn } from "@/lib/utils";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "./card";

interface ElegantCardProps extends React.HTMLAttributes<HTMLDivElement> {
  title?: string;
  description?: string;
  children?: React.ReactNode;
}

/**
 * Minimal card hover — 2px lift, soft shadow, subtle border brighten.
 * Custom in-house. Rejected: X-Ray, 3D flip, heavy parallax.
 */
export function ElegantCard({
  className,
  title,
  description,
  children,
  ...props
}: ElegantCardProps) {
  const prefersReducedMotion = useReducedMotion();

  return (
    <motion.div
      whileHover={
        prefersReducedMotion
          ? undefined
          : { y: -2, boxShadow: "0 8px 24px rgba(11, 27, 58, 0.08)" }
      }
      transition={{ duration: 0.3, ease: [0.25, 0.1, 0.25, 1] }}
      className={cn(
        "rounded-md border border-border transition-colors duration-300 hover:border-primary/15",
        className,
      )}
      {...props}
    >
      <Card className="border-0 shadow-none">
        {(title || description) && (
          <CardHeader>
            {title && <CardTitle>{title}</CardTitle>}
            {description && <CardDescription>{description}</CardDescription>}
          </CardHeader>
        )}
        {children && <CardContent>{children}</CardContent>}
      </Card>
    </motion.div>
  );
}

