"use client";

import * as React from "react";
import { AnimatePresence, motion } from "motion/react";
import { ChevronDown, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import type { BrowserTab } from "./browser-mockup-data";

interface BrowserMockupContentProps {
  current: BrowserTab;
  expandedRow: string | null;
  onToggleRow: (label: string) => void;
  prefersReducedMotion: boolean | null;
  compact?: boolean;
  hint?: string;
}

export function BrowserMockupContent({
  current,
  expandedRow,
  onToggleRow,
  prefersReducedMotion,
  compact = false,
  hint,
}: BrowserMockupContentProps) {
  const maxChart = Math.max(...current.chart);
  const textSize = compact ? "text-[11px]" : "text-small";
  const statSize = compact ? "text-base" : "text-stat";
  const chartHeight = compact ? "h-14" : "h-20";

  return (
    <AnimatePresence mode="wait">
      <motion.div
        key={current.id}
        initial={prefersReducedMotion ? false : { opacity: 0, y: 8 }}
        animate={{ opacity: 1, y: 0 }}
        exit={prefersReducedMotion ? undefined : { opacity: 0, y: -8 }}
        transition={{ duration: 0.25, ease: "easeOut" }}
      >
        <div
          className={cn(
            "mb-4 flex items-end gap-1 rounded-xl border border-border bg-surface p-3",
            chartHeight,
          )}
        >
          {current.chart.map((height, i) => {
            const isPeak = height === maxChart;
            return (
              <motion.div
                key={`${current.id}-bar-${i}`}
                className="flex-1 rounded-sm"
                initial={prefersReducedMotion ? false : { height: 0 }}
                animate={{ height: `${height}%` }}
                transition={{
                  delay: prefersReducedMotion ? 0 : i * 0.03,
                  duration: 0.35,
                  ease: "easeOut",
                }}
                style={{
                  maxHeight: "100%",
                  backgroundColor: isPeak
                    ? "var(--color-accent)"
                    : "var(--color-primary)",
                  opacity: isPeak ? 1 : 0.15 + (height / maxChart) * 0.55,
                }}
              />
            );
          })}
        </div>

        <div className="grid grid-cols-3 gap-2 sm:gap-4">
          {current.stats.map((stat, i) => (
            <motion.div
              key={stat.label}
              initial={prefersReducedMotion ? false : { opacity: 0, y: 6 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: prefersReducedMotion ? 0 : i * 0.06 }}
              className="rounded-xl border border-border bg-surface p-3 sm:p-4"
            >
              <p className={cn(statSize, "font-semibold text-text-primary")}>
                {stat.value}
              </p>
              <p
                className={cn(
                  "mt-0.5 text-text-secondary",
                  compact ? "text-[10px]" : "text-small",
                )}
              >
                {stat.label}
              </p>
              <div className="mt-2 h-1 overflow-hidden rounded-full bg-border">
                <motion.div
                  className="h-full rounded-full bg-primary"
                  initial={prefersReducedMotion ? false : { width: 0 }}
                  animate={{ width: `${stat.progress}%` }}
                  transition={{ delay: 0.15 + i * 0.08, duration: 0.5 }}
                />
              </div>
            </motion.div>
          ))}
        </div>

        <div className="mt-4 overflow-hidden rounded-xl border border-border sm:mt-6">
          <table className={cn("w-full text-left", textSize)}>
            <thead>
              <tr className="border-b border-border bg-surface">
                <th className="px-3 py-2 font-medium text-text-secondary sm:px-4 sm:py-3" scope="col">
                  Metric
                </th>
                <th className="px-3 py-2 font-medium text-text-secondary sm:px-4 sm:py-3" scope="col">
                  Value
                </th>
                <th className="px-3 py-2 text-right font-medium text-text-secondary sm:px-4 sm:py-3" scope="col">
                  Change
                </th>
                <th className="w-6" scope="col">
                  <span className="sr-only">Expand</span>
                </th>
              </tr>
            </thead>
            <tbody>
              {current.table.map((row, i) => (
                <React.Fragment key={row.label}>
                  <motion.tr
                    initial={prefersReducedMotion ? false : { opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{
                      delay: prefersReducedMotion ? 0 : 0.1 + i * 0.05,
                    }}
                    className={cn(
                      "cursor-pointer border-b border-border transition-colors last:border-0 hover:bg-surface",
                      expandedRow === row.label && "bg-surface",
                    )}
                    onClick={() => onToggleRow(row.label)}
                  >
                    <td className="px-3 py-2.5 text-text-primary sm:px-4 sm:py-3">
                      {row.label}
                    </td>
                    <td className="px-3 py-2.5 font-medium text-text-primary sm:px-4 sm:py-3">
                      {row.value}
                    </td>
                    <td
                      className={cn(
                        "px-3 py-2.5 text-right font-medium sm:px-4 sm:py-3",
                        row.positive ? "text-success" : "text-error",
                      )}
                    >
                      {row.change}
                    </td>
                    <td className="px-1 text-text-secondary">
                      {expandedRow === row.label ? (
                        <ChevronDown className="h-3 w-3 sm:h-4 sm:w-4" aria-hidden="true" />
                      ) : (
                        <ChevronRight className="h-3 w-3 sm:h-4 sm:w-4" aria-hidden="true" />
                      )}
                    </td>
                  </motion.tr>
                  <AnimatePresence>
                    {expandedRow === row.label && row.detail && (
                      <motion.tr
                        initial={prefersReducedMotion ? false : { opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={prefersReducedMotion ? undefined : { opacity: 0 }}
                      >
                        <td
                          colSpan={4}
                          className="bg-surface px-3 py-2 text-[10px] text-text-secondary sm:px-4 sm:text-small"
                        >
                          {row.detail}
                        </td>
                      </motion.tr>
                    )}
                  </AnimatePresence>
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>

        {hint && (
          <p className="mt-3 text-center text-[10px] text-text-secondary sm:text-small">
            {hint}
          </p>
        )}
      </motion.div>
    </AnimatePresence>
  );
}

"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ChevronLeft, Lock, Search, Share } from "lucide-react";
import { designSystem } from "@/lib/design-tokens";
import { cn } from "@/lib/utils";
import { browserTabs, type BrowserTab, type BrowserVariant } from "./browser-mockup-data";
import { BrowserMockupContent } from "./browser-mockup-content";

interface BrowserMockupProps {
  className?: string;
  autoRotate?: boolean;
  variant?: BrowserVariant;
  label?: string;
}

function useBrowserState(autoRotate: boolean) {
  const [activeTab, setActiveTab] = React.useState(browserTabs[0].id);
  const [expandedRow, setExpandedRow] = React.useState<string | null>(null);
  const [isPaused, setIsPaused] = React.useState(false);
  const prefersReducedMotion = useReducedMotion();
  const tabListRef = React.useRef<HTMLDivElement>(null);

  const interval =
    typeof designSystem.components.browserMockup === "object" &&
    designSystem.components.browserMockup !== null &&
    "autoRotateInterval" in designSystem.components.browserMockup
      ? Number(
          (designSystem.components.browserMockup as { autoRotateInterval: number })
            .autoRotateInterval,
        )
      : 8000;

  React.useEffect(() => {
    if (!autoRotate || prefersReducedMotion || isPaused) return;

    const timer = window.setInterval(() => {
      setActiveTab((current) => {
        const index = browserTabs.findIndex((t) => t.id === current);
        return browserTabs[(index + 1) % browserTabs.length].id;
      });
      setExpandedRow(null);
    }, interval);

    return () => window.clearInterval(timer);
  }, [autoRotate, interval, prefersReducedMotion, isPaused]);

  const selectTab = (id: string) => {
    setActiveTab(id);
    setExpandedRow(null);
    setIsPaused(true);
  };

  const handleTabKeyDown = (e: React.KeyboardEvent, index: number) => {
    let nextIndex = index;
    if (e.key === "ArrowRight") nextIndex = (index + 1) % browserTabs.length;
    else if (e.key === "ArrowLeft")
      nextIndex = (index - 1 + browserTabs.length) % browserTabs.length;
    else return;

    e.preventDefault();
    selectTab(browserTabs[nextIndex].id);
    const buttons = tabListRef.current?.querySelectorAll<HTMLButtonElement>(
      '[role="tab"]',
    );
    buttons?.[nextIndex]?.focus();
  };

  const current = browserTabs.find((t) => t.id === activeTab) ?? browserTabs[0];

  return {
    activeTab,
    current,
    expandedRow,
    prefersReducedMotion,
    tabListRef,
    selectTab,
    handleTabKeyDown,
    setExpandedRow,
    setIsPaused,
  };
}

interface TabBarProps {
  tabs: BrowserTab[];
  activeTab: string;
  tabListRef: React.RefObject<HTMLDivElement | null>;
  onSelect: (id: string) => void;
  onKeyDown: (e: React.KeyboardEvent, index: number) => void;
  variant: BrowserVariant;
}

function TabBar({
  tabs,
  activeTab,
  tabListRef,
  onSelect,
  onKeyDown,
  variant,
}: TabBarProps) {
  if (variant === "ios") {
    return (
      <div className="px-4 pb-3">
        <div
          ref={tabListRef}
          className="flex rounded-lg bg-[#E5E5EA] p-0.5"
          role="tablist"
          aria-label="Dashboard views"
        >
          {tabs.map((tab, index) => (
            <button
              key={tab.id}
              type="button"
              id={`tab-${tab.id}`}
              onClick={() => onSelect(tab.id)}
              onKeyDown={(e) => onKeyDown(e, index)}
              className={cn(
                "flex-1 rounded-md px-2 py-1.5 text-[11px] font-medium transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent",
                activeTab === tab.id
                  ? "bg-white text-text-primary shadow-sm"
                  : "text-text-secondary",
              )}
              aria-selected={activeTab === tab.id}
              role="tab"
              tabIndex={activeTab === tab.id ? 0 : -1}
            >
              <span className="hidden sm:inline">{tab.label}</span>
              <span className="sm:hidden">{tab.shortLabel}</span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div
      ref={tabListRef}
      className="ml-2 flex flex-1 gap-1 overflow-x-auto"
      role="tablist"
      aria-label="Dashboard views"
    >
      {tabs.map((tab, index) => (
        <button
          key={tab.id}
          type="button"
          id={`tab-${tab.id}`}
          onClick={() => onSelect(tab.id)}
          onKeyDown={(e) => onKeyDown(e, index)}
          className={cn(
            "rounded-sm px-3 py-1 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent",
            activeTab === tab.id
              ? "bg-background text-text-primary shadow-sm"
              : "text-text-secondary hover:text-text-primary",
          )}
          aria-selected={activeTab === tab.id}
          role="tab"
          tabIndex={activeTab === tab.id ? 0 : -1}
        >
          {tab.label}
        </button>
      ))}
    </div>
  );
}

function UrlBar({
  url,
  prefersReducedMotion,
  variant,
}: {
  url: string;
  prefersReducedMotion: boolean | null;
  variant: BrowserVariant;
}) {
  if (variant === "ios") {
    return (
      <div className="flex items-center gap-2 px-4 pb-2">
        <button
          type="button"
          className="flex h-8 w-8 items-center justify-center rounded-full bg-white/60 text-text-secondary"
          aria-hidden="true"
          tabIndex={-1}
        >
          <ChevronLeft className="h-4 w-4" />
        </button>
        <div className="flex flex-1 items-center gap-2 rounded-full bg-white px-3 py-2 shadow-sm">
          <Lock className="h-3 w-3 shrink-0 text-text-secondary" aria-hidden="true" />
          <AnimatePresence mode="wait">
            <motion.span
              key={url}
              initial={prefersReducedMotion ? false : { opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={prefersReducedMotion ? undefined : { opacity: 0 }}
              transition={{ duration: 0.15 }}
              className="truncate text-[11px] text-text-primary"
            >
              {url}
            </motion.span>
          </AnimatePresence>
        </div>
        <button
          type="button"
          className="flex h-8 w-8 items-center justify-center rounded-full bg-white/60 text-text-secondary"
          aria-hidden="true"
          tabIndex={-1}
        >
          <Share className="h-3.5 w-3.5" />
        </button>
      </div>
    );
  }

  return (
    <div className="border-b border-border bg-background px-6 py-4">
      <div className="flex items-center gap-2 rounded-md border border-border px-3 py-2 text-small text-text-secondary">
        <Search className="h-4 w-4 shrink-0" aria-hidden="true" />
        <AnimatePresence mode="wait">
          <motion.span
            key={url}
            initial={prefersReducedMotion ? false : { opacity: 0, y: 4 }}
            animate={{ opacity: 1, y: 0 }}
            exit={prefersReducedMotion ? undefined : { opacity: 0, y: -4 }}
            transition={{ duration: 0.2 }}
            className="truncate"
          >
            {url}
          </motion.span>
        </AnimatePresence>
      </div>
    </div>
  );
}

export function BrowserMockup({
  className,
  autoRotate = true,
  variant = "macos",
  label,
}: BrowserMockupProps) {
  const state = useBrowserState(autoRotate);
  const { current } = state;

  const frameClass =
    variant === "ios"
      ? "overflow-hidden rounded-[2rem] border border-border bg-[#F2F2F7] shadow-lg"
      : "overflow-hidden rounded-lg border border-border bg-surface shadow-lg";

  const hint =
    variant === "ios"
      ? "Tap a row for details · Segments auto-switch every 8s"
      : "Click any row to expand details · Tabs auto-rotate every 8s";

  return (
    <div
      className={cn(variant === "ios" ? "mx-auto max-w-md" : "w-full", className)}
      onMouseEnter={() => state.setIsPaused(true)}
      onMouseLeave={() => state.setIsPaused(false)}
    >
      {label && (
        <p className="text-small mb-3 font-medium text-text-secondary">{label}</p>
      )}
      <div className={frameClass}>
        {variant === "ios" ? (
          <>
            <div className="flex items-center justify-between px-6 pt-3 pb-1">
              <span className="text-[11px] font-semibold text-text-primary">9:41</span>
              <div className="h-5 w-24 rounded-full bg-primary" aria-hidden="true" />
              <div className="flex items-center gap-1" aria-hidden="true">
                <span className="text-[10px] font-medium text-text-primary">5G</span>
                <span className="h-2.5 w-5 rounded-sm border border-text-primary" />
              </div>
            </div>
            <UrlBar
              url={current.url}
              prefersReducedMotion={state.prefersReducedMotion}
              variant="ios"
            />
            <TabBar
              tabs={browserTabs}
              activeTab={state.activeTab}
              tabListRef={state.tabListRef}
              onSelect={state.selectTab}
              onKeyDown={state.handleTabKeyDown}
              variant="ios"
            />
          </>
        ) : (
          <>
            <div className="flex h-10 items-center gap-2 border-b border-border px-4">
              <div className="flex gap-1.5" aria-hidden="true">
