"use client";

import { motion, useReducedMotion } from "motion/react";
import { cn } from "@/lib/utils";

interface BrowserMockupChartProps {
  data: number[];
  compact?: boolean;
  className?: string;
}

function buildAreaPath(
  data: number[],
  width: number,
  height: number,
  padding: { top: number; right: number; bottom: number; left: number },
): { line: string; area: string; points: { x: number; y: number }[] } {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;
  const innerWidth = width - padding.left - padding.right;
  const innerHeight = height - padding.top - padding.bottom;

  const points = data.map((value, index) => ({
    x: padding.left + (index / (data.length - 1)) * innerWidth,
    y: padding.top + (1 - (value - min) / range) * innerHeight,
  }));

  const line = points.map((point, index) => `${index === 0 ? "M" : "L"} ${point.x} ${point.y}`).join(" ");
  const area = `${line} L ${points[points.length - 1].x} ${height - padding.bottom} L ${points[0].x} ${height - padding.bottom} Z`;

  return { line, area, points };
}

export function BrowserMockupChart({
  data,
  compact = false,
  className,
}: BrowserMockupChartProps) {
  const prefersReducedMotion = useReducedMotion();
  const width = compact ? 280 : 520;
  const height = compact ? 72 : 96;
  const padding = compact
    ? { top: 8, right: 8, bottom: 16, left: 8 }
    : { top: 10, right: 12, bottom: 20, left: 12 };

  const { line, area, points } = buildAreaPath(data, width, height, padding);
  const lastPoint = points[points.length - 1];
  const gridLines = [0.25, 0.5, 0.75].map((ratio) => height * ratio);

  return (
    <div
      className={cn(
        "rounded-lg border border-border bg-background",
        compact ? "p-2" : "p-4",
        className,
      )}
      role="img"
      aria-label="Revenue trend line chart"
    >
      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="w-full"
        preserveAspectRatio="none"
        aria-hidden="true"
      >
        {gridLines.map((y) => (
          <line
            key={y}
            x1={padding.left}
            y1={y}
            x2={width - padding.right}
            y2={y}
            stroke="var(--color-border)"
            strokeWidth="0.5"
            strokeDasharray="3 4"
            opacity="0.6"
          />
        ))}

        <motion.path
          d={area}
          fill="var(--color-primary)"
          fillOpacity="0.08"
          initial={prefersReducedMotion ? false : { opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.4 }}
        />

        <motion.path
          d={line}
          fill="none"
          stroke="var(--color-primary)"
          strokeWidth={compact ? 1.5 : 2}
          strokeLinecap="round"
          strokeLinejoin="round"
          initial={prefersReducedMotion ? false : { pathLength: 0, opacity: 0 }}
          animate={{ pathLength: 1, opacity: 1 }}
          transition={{ duration: 0.6, ease: "easeOut" }}
        />

        <motion.circle
          cx={lastPoint.x}
          cy={lastPoint.y}
          r={compact ? 3 : 4}
          fill="var(--color-accent)"
          stroke="var(--color-background)"
          strokeWidth="1.5"
          initial={prefersReducedMotion ? false : { scale: 0 }}
          animate={{ scale: 1 }}
          transition={{ delay: 0.45, duration: 0.2 }}
        />
      </svg>

      <div
        className={cn(
          "flex justify-between text-text-secondary",
          compact ? "mt-1 px-1 text-[9px]" : "mt-2 px-1 text-[10px]",
        )}
      >
        <span>30d ago</span>
        <span>Today</span>
      </div>
    </div>
  );
}

export function A11yTestingGuide() {
  const steps = [
    {
      title: "Keyboard navigation",
      detail:
        "Reload the page, press Tab once — Skip link should appear. Tab through buttons, tabs, and table rows. Arrow keys switch browser mockup tabs.",
    },
    {
      title: "Chrome Lighthouse",
      detail:
        "DevTools (F12) → Lighthouse tab → select Accessibility → Analyze page load. Target score 90+.",
    },
    {
      title: "axe DevTools",
      detail:
        "Install the axe Accessibility Linter extension → open DevTools → axe tab → Scan ALL of my page.",
    },
    {
      title: "Contrast check",
      detail:
        "Use WebAIM Contrast Checker (webaim.org/resources/contrastchecker) on navy #0B1B3A and gold #EAAB1D against white.",
    },
    {
      title: "Reduced motion",
      detail:
        "Windows: Settings → Accessibility → Visual effects → Animation effects Off. macOS: System Settings → Accessibility → Display → Reduce motion.",
    },
    {
      title: "Responsive preview",
      detail:
        "DevTools → Toggle device toolbar (Ctrl+Shift+M). Test 375px (iPhone), 768px (iPad), 1280px (desktop).",
    },
    {
      title: "Dark mode (Phase 1)",
      detail:
        "Not built yet. DevTools → Rendering → Emulate prefers-color-scheme: dark will not change colors until dark tokens ship in Phase 1.",
    },
    {
      title: "Screen reader",
      detail:
        "Windows Narrator (Win+Ctrl+Enter) or NVDA (free). macOS VoiceOver (Cmd+F5). Verify headings and table labels are announced.",
    },
  ];

  return (
    <div className="mt-6 rounded-lg border border-border bg-surface p-6">
      <p className="text-h4 mb-2">How to test accessibility yourself</p>
      <p className="text-small mb-4 text-text-secondary">
        Run these checks on <code className="rounded bg-background px-1">/design-system</code>{" "}
        before Phase 0 approval.
      </p>
      <ol className="space-y-4">
        {steps.map((step, index) => (
          <li key={step.title} className="flex gap-3">
            <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-primary text-xs font-medium text-text-on-dark">
              {index + 1}
            </span>
            <div>
              <p className="text-small font-medium text-text-primary">{step.title}</p>
              <p className="text-small mt-0.5 text-text-secondary">{step.detail}</p>
            </div>
          </li>
        ))}
      </ol>
    </div>
  );
}

