"use client";

import { useId } from "react";
import { motion, useReducedMotion } from "motion/react";
import { cn } from "@/lib/utils";

interface BrowserMockupChartProps {
  data: number[];
  compact?: boolean;
  className?: string;
}

function buildAreaPath(
  data: number[],
  width: number,
  height: number,
  padding: { top: number; right: number; bottom: number; left: number },
): { line: string; area: string; points: { x: number; y: number }[] } {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;
  const innerWidth = width - padding.left - padding.right;
  const innerHeight = height - padding.top - padding.bottom;

  const points = data.map((value, index) => ({
    x: padding.left + (index / (data.length - 1)) * innerWidth,
    y: padding.top + (1 - (value - min) / range) * innerHeight,
  }));

  const line = points
    .map((point, index) => `${index === 0 ? "M" : "L"} ${point.x} ${point.y}`)
    .join(" ");
  const area = `${line} L ${points[points.length - 1].x} ${height - padding.bottom} L ${points[0].x} ${height - padding.bottom} Z`;

  return { line, area, points };
}

export function BrowserMockupChart({
  data,
  compact = false,
  className,
}: BrowserMockupChartProps) {
  const chartId = useId().replace(/:/g, "");
  const prefersReducedMotion = useReducedMotion();
  const width = compact ? 280 : 520;
  const height = compact ? 72 : 96;
  const padding = compact
    ? { top: 8, right: 8, bottom: 16, left: 8 }
    : { top: 10, right: 12, bottom: 20, left: 12 };

  const { line, area, points } = buildAreaPath(data, width, height, padding);
  const lastPoint = points[points.length - 1];
  const gridLines = [0.25, 0.5, 0.75].map((ratio) => height * ratio);

  const areaGradientId = `area-${chartId}`;
  const lineGradientId = `line-${chartId}`;
  const glowFilterId = `glow-${chartId}`;

  return (
    <div
      className={cn(
        "rounded-lg border border-accent/20 bg-gradient-to-b from-accent/8 via-background to-background",
        compact ? "p-2 shadow-[0_2px_12px_rgba(234,171,29,0.10)]" : "p-4 shadow-[0_4px_20px_rgba(234,171,29,0.14)]",
        className,
      )}
      role="img"
      aria-label="Revenue trend line chart"
    >
      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="w-full"
        preserveAspectRatio="none"
        aria-hidden="true"
      >
        <defs>
          <linearGradient id={areaGradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--color-accent)" stopOpacity="0.28" />
            <stop offset="55%" stopColor="var(--color-brandCyan)" stopOpacity="0.12" />
            <stop offset="100%" stopColor="var(--color-primary)" stopOpacity="0.04" />
          </linearGradient>
          <linearGradient id={lineGradientId} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="var(--color-primary)" />
            <stop offset="70%" stopColor="var(--color-primary)" />
            <stop offset="100%" stopColor="var(--color-accent)" />
          </linearGradient>
          <filter id={glowFilterId} x="-20%" y="-20%" width="140%" height="140%">
            <feDropShadow
              dx="0"
              dy="2"
              stdDeviation={compact ? 2.5 : 3.5}
              floodColor="var(--color-accent)"
              floodOpacity="0.45"
            />
            <feDropShadow
              dx="0"
              dy="0"
              stdDeviation={compact ? 1 : 1.5}
              floodColor="var(--color-brandCyan)"
              floodOpacity="0.2"
            />
          </filter>
        </defs>

        {gridLines.map((y) => (
          <line
            key={y}
            x1={padding.left}
            y1={y}
            x2={width - padding.right}
            y2={y}
            stroke="var(--color-accent)"
            strokeWidth="0.5"
            strokeDasharray="3 4"
            opacity="0.15"
          />
        ))}

        <motion.path
          d={area}
          fill={`url(#${areaGradientId})`}
          initial={prefersReducedMotion ? false : { opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.4 }}
        />

        <motion.path
          d={line}
          fill="none"
          stroke={`url(#${lineGradientId})`}
          strokeWidth={compact ? 1.75 : 2.25}
          strokeLinecap="round"
          strokeLinejoin="round"
          filter={`url(#${glowFilterId})`}
          initial={prefersReducedMotion ? false : { pathLength: 0, opacity: 0 }}
          animate={{ pathLength: 1, opacity: 1 }}
          transition={{ duration: 0.6, ease: "easeOut" }}
        />

        <motion.circle
          cx={lastPoint.x}
          cy={lastPoint.y}
          r={compact ? 3.5 : 4.5}
          fill="var(--color-accent)"
          stroke="var(--color-background)"
          strokeWidth="1.5"
          filter={`url(#${glowFilterId})`}
          initial={prefersReducedMotion ? false : { scale: 0 }}
          animate={{ scale: 1 }}
          transition={{ delay: 0.45, duration: 0.2 }}
        />
      </svg>

      <div
        className={cn(
          "flex justify-between font-medium text-accent/80",
          compact ? "mt-1 px-1 text-[9px]" : "mt-2 px-1 text-[10px]",
        )}
      >
        <span>30d ago</span>
        <span className="text-accent">Today</span>
      </div>
    </div>
  );
}

