"use client";

import { useCallback, useId, useRef, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { cn } from "@/lib/utils";
import type { ChartPoint } from "./browser-mockup-data";

interface BrowserMockupChartProps {
  data: number[];
  points: ChartPoint[];
  chartLabel: string;
  compact?: boolean;
  className?: string;
}

function buildAreaPath(
  data: number[],
  width: number,
  height: number,
  padding: { top: number; right: number; bottom: number; left: number },
): { line: string; area: string; coords: { x: number; y: number }[] } {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;
  const innerWidth = width - padding.left - padding.right;
  const innerHeight = height - padding.top - padding.bottom;

  const coords = data.map((value, index) => ({
    x: padding.left + (index / (data.length - 1)) * innerWidth,
    y: padding.top + (1 - (value - min) / range) * innerHeight,
  }));

  const line = coords
    .map((point, index) => `${index === 0 ? "M" : "L"} ${point.x} ${point.y}`)
    .join(" ");
  const area = `${line} L ${coords[coords.length - 1].x} ${height - padding.bottom} L ${coords[0].x} ${height - padding.bottom} Z`;

  return { line, area, coords };
}

export function BrowserMockupChart({
  data,
  points,
  chartLabel,
  compact = false,
  className,
}: BrowserMockupChartProps) {
  const chartId = useId().replace(/:/g, "");
  const containerRef = useRef<HTMLDivElement>(null);
  const prefersReducedMotion = useReducedMotion();
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);

  const width = compact ? 280 : 520;
  const height = compact ? 80 : 104;
  const padding = compact
    ? { top: 12, right: 8, bottom: 18, left: 8 }
    : { top: 14, right: 12, bottom: 22, left: 12 };

  const { line, area, coords } = buildAreaPath(data, width, height, padding);
  const lastPoint = coords[coords.length - 1];
  const gridLines = [0.25, 0.5, 0.75].map((ratio) => height * ratio);
  const activeIndex = hoveredIndex ?? data.length - 1;
  const activePoint = points[activeIndex];
  const activeCoord = coords[activeIndex];

  const areaGradientId = `area-${chartId}`;
  const lineGradientId = `line-${chartId}`;
  const glowFilterId = `glow-${chartId}`;

  const handlePointer = useCallback(
    (clientX: number) => {
      const rect = containerRef.current?.getBoundingClientRect();
      if (!rect) return;

      const relativeX = ((clientX - rect.left) / rect.width) * width;
      let nearest = 0;
      let nearestDistance = Infinity;

      coords.forEach((coord, index) => {
        const distance = Math.abs(coord.x - relativeX);
        if (distance < nearestDistance) {
          nearestDistance = distance;
          nearest = index;
        }
      });

      setHoveredIndex(nearest);
    },
    [coords, width],
  );

  const tooltipLeft = (activeCoord.x / width) * 100;

  return (
    <div
      ref={containerRef}
      className={cn(
        "relative rounded-lg border border-accent/12 bg-gradient-to-b from-accent/5 via-background to-background",
        compact ? "p-2 shadow-[0_1px_4px_rgba(234,171,29,0.06)]" : "p-4 shadow-[0_2px_8px_rgba(234,171,29,0.07)]",
        className,
      )}
      onMouseMove={(event) => handlePointer(event.clientX)}
      onMouseLeave={() => setHoveredIndex(null)}
      onTouchStart={(event) => {
        const touch = event.touches[0];
        if (touch) handlePointer(touch.clientX);
      }}
      onTouchMove={(event) => {
        const touch = event.touches[0];
        if (touch) handlePointer(touch.clientX);
      }}
      role="img"
      aria-label={`${chartLabel} chart. Hover or tap to inspect values.`}
    >
      <div className="mb-2 flex items-center justify-between gap-2">
        <p className={cn("font-medium text-text-primary", compact ? "text-[10px]" : "text-xs")}>
          {chartLabel}
        </p>
        <div
          className={cn(
            "rounded-md border border-accent/15 bg-white/90 px-2 py-1 text-right shadow-sm backdrop-blur-sm",
            compact ? "text-[9px]" : "text-[10px]",
          )}
          aria-live="polite"
        >
          <span className="font-semibold text-text-primary">{activePoint.value}</span>
          <span className="mx-1 text-text-secondary">·</span>
          <span className="text-text-secondary">{activePoint.label}</span>
        </div>
      </div>

      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="w-full touch-none"
        preserveAspectRatio="none"
        aria-hidden="true"
      >
        <defs>
          <linearGradient id={areaGradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--color-accent)" stopOpacity="0.18" />
            <stop offset="55%" stopColor="var(--color-brandCyan)" stopOpacity="0.07" />
            <stop offset="100%" stopColor="var(--color-primary)" stopOpacity="0.03" />
          </linearGradient>
          <linearGradient id={lineGradientId} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="var(--color-primary)" />
            <stop offset="70%" stopColor="var(--color-primary)" />
            <stop offset="100%" stopColor="var(--color-accent)" />
          </linearGradient>
          <filter id={glowFilterId} x="-10%" y="-10%" width="120%" height="120%">
            <feDropShadow
              dx="0"
              dy="1"
              stdDeviation={compact ? 0.8 : 1.2}
              floodColor="var(--color-accent)"
              floodOpacity="0.22"
            />
          </filter>
        </defs>

        {gridLines.map((y) => (
          <line
            key={y}
            x1={padding.left}
            y1={y}
            x2={width - padding.right}
            y2={y}
            stroke="var(--color-accent)"
            strokeWidth="0.5"
            strokeDasharray="3 4"
            opacity="0.1"
          />
        ))}

        {hoveredIndex !== null && (
          <line
            x1={activeCoord.x}
            y1={padding.top}
            x2={activeCoord.x}
            y2={height - padding.bottom}
            stroke="var(--color-accent)"
            strokeWidth="1"
            strokeDasharray="2 3"
            opacity="0.45"
          />
        )}

        <motion.path
          d={area}
          fill={`url(#${areaGradientId})`}
          initial={prefersReducedMotion ? false : { opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.4 }}
        />

        <motion.path
          d={line}
          fill="none"
          stroke={`url(#${lineGradientId})`}
          strokeWidth={compact ? 1.75 : 2.25}
          strokeLinecap="round"
          strokeLinejoin="round"
          filter={`url(#${glowFilterId})`}
          initial={prefersReducedMotion ? false : { pathLength: 0, opacity: 0 }}
          animate={{ pathLength: 1, opacity: 1 }}
          transition={{ duration: 0.6, ease: "easeOut" }}
        />

        {coords.map((coord, index) => (
          <circle
            key={`hit-${index}`}
            cx={coord.x}
            cy={coord.y}
            r={compact ? 10 : 12}
            fill="transparent"
            className="cursor-crosshair"
            onMouseEnter={() => setHoveredIndex(index)}
          />
        ))}

        <circle
          cx={activeCoord.x}
          cy={activeCoord.y}
          r={compact ? 3.5 : 4}
          fill="var(--color-accent)"
          stroke="var(--color-background)"
          strokeWidth="1.5"
        />

        <circle
          cx={lastPoint.x}
          cy={lastPoint.y}
          r={compact ? 2 : 2.5}
          fill="var(--color-primary)"
          opacity={hoveredIndex === null ? 0.35 : 0}
        />
      </svg>

      <div
        className={cn(
          "pointer-events-none absolute bottom-2 -translate-x-1/2 rounded-md border border-accent/20 bg-white px-2 py-1 shadow-sm transition-opacity",
          compact ? "text-[9px]" : "text-[10px]",
          hoveredIndex !== null ? "opacity-100" : "opacity-0",
        )}
        style={{ left: `${tooltipLeft}%` }}
      >
        <span className="font-semibold text-text-primary">{activePoint.value}</span>
      </div>

      <div
        className={cn(
          "flex justify-between text-text-secondary",
          compact ? "mt-1 px-1 text-[9px]" : "mt-2 px-1 text-[10px]",
        )}
      >
        <span>{points[0]?.label}</span>
        <span className="text-accent/80">{points[points.length - 1]?.label}</span>
      </div>
    </div>
  );
}

