"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";

const STORAGE_KEY = "ecom-gliders-theme-preview";

export function DarkModePreviewToggle() {
  const [enabled, setEnabled] = useState(false);

  useEffect(() => {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    const isEnabled = stored === "dark";
    setEnabled(isEnabled);
    document.documentElement.classList.toggle("preview-dark", isEnabled);
  }, []);

  const toggle = () => {
    const next = !enabled;
    setEnabled(next);
    document.documentElement.classList.toggle("preview-dark", next);
    window.localStorage.setItem(STORAGE_KEY, next ? "dark" : "light");
  };

  return (
    <div className="mt-6 rounded-lg border border-dashed border-border bg-surface p-6">
      <p className="text-h4 mb-2">Dark mode — how to test</p>
      <p className="text-small mb-4 text-text-secondary">
        Full dark theme ships in Phase 1. Use this preview toggle to test contrast on
        the design system page only. Production pages stay light until approved.
      </p>
      <div className="flex flex-wrap items-center gap-3">
        <Button type="button" variant="secondary" onClick={toggle}>
          {enabled ? "Switch to light preview" : "Switch to dark preview"}
        </Button>
        <span className="text-small text-text-secondary">
          Status: {enabled ? "Dark preview on" : "Light (default)"}
        </span>
      </div>
