"use client";

import { useEffect, useState } from "react";
import { Moon, Sun } from "lucide-react";
import { cn } from "@/lib/utils";

const STORAGE_KEY = "ecom-gliders-theme-preview";

export function DarkModePreviewToggle() {
  const [enabled, setEnabled] = useState(false);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    const isEnabled = stored === "dark";
    setEnabled(isEnabled);
    document.documentElement.classList.toggle("preview-dark", isEnabled);
    setMounted(true);
  }, []);

  const toggle = () => {
    const next = !enabled;
    setEnabled(next);
    document.documentElement.classList.toggle("preview-dark", next);
    window.localStorage.setItem(STORAGE_KEY, next ? "dark" : "light");
  };

  if (!mounted) {
    return (
      <div
        className="h-11 w-[108px] shrink-0 rounded-sm border border-border bg-surface"
        aria-hidden="true"
      />
    );
  }

  return (
    <button
      type="button"
      onClick={toggle}
      aria-pressed={enabled}
      aria-label={
        enabled
          ? "Dark preview on. Switch to light mode preview."
          : "Light mode. Switch to dark mode preview."
      }
      title="Preview dark mode (Phase 0 — design system only)"
      className={cn(
        "inline-flex h-11 shrink-0 items-center gap-2 rounded-sm border px-3 text-sm font-medium transition-colors",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
        enabled
          ? "border-accent/30 bg-primary text-text-on-dark hover:bg-primary-dark"
          : "border-border bg-surface text-text-primary hover:bg-surface-muted",
      )}
    >
      {enabled ? (
        <Sun className="h-4 w-4 shrink-0" aria-hidden="true" />
      ) : (
        <Moon className="h-4 w-4 shrink-0" aria-hidden="true" />
      )}
      <span className="hidden sm:inline">{enabled ? "Light" : "Dark"}</span>
      <span className="sm:hidden">{enabled ? "On" : "Off"}</span>
    </button>
  );
}

