import { buildCssVariables } from "@/lib/design-tokens";

const PREVIEW_DARK_OVERRIDES: Record<string, string> = {
  "--color-background": "#0a0f1a",
  "--color-surface": "#121a28",
  "--color-surfaceMuted": "#1a2436",
  "--color-textPrimary": "#eef1f5",
  "--color-textSecondary": "#9aa3b0",
  "--color-border": "#2a3548",
  "--color-borderStrong": "#3d4a60",
  "--color-link": "#eef1f5",
  "--color-linkHover": "#eaab1d",
  "--shadow-sm": "0 1px 2px rgba(0, 0, 0, 0.3)",
  "--shadow-md": "0 2px 8px rgba(0, 0, 0, 0.35)",
  "--shadow-lg": "0 4px 16px rgba(0, 0, 0, 0.4)",
  "--shadow-header": "0 1px 0 rgba(255, 255, 255, 0.06)",
};

export function applyThemePreview(mode: "light" | "dark") {
  const root = document.documentElement;
  const lightVars = buildCssVariables();
  const vars =
    mode === "dark" ? { ...lightVars, ...PREVIEW_DARK_OVERRIDES } : lightVars;

  for (const [key, value] of Object.entries(vars)) {
    root.style.setProperty(key, value);
  }

  root.classList.toggle("preview-dark", mode === "dark");
}

