"use client";

import { useEffect, useState } from "react";
import { CheckCircle2, Circle } from "lucide-react";

const STORAGE_KEY = "ecom-gliders-review-checklist";

const checklistItems = [
  {
    id: "dark-mode",
    label: "Dark mode preview",
    hint: "Header → Moon/Sun button. Background should turn navy-dark.",
  },
  {
    id: "skip-link",
    label: "Skip to main content",
    hint: "Reload page → press Tab once → Skip link appears.",
  },
  {
    id: "keyboard-tabs",
    label: "Browser mockup keyboard tabs",
    hint: "Section 13 → focus a tab → Arrow Left/Right switches views.",
  },
  {
    id: "chart-hover",
    label: "Chart data on hover",
    hint: "Section 13 → hover chart line → value and date update.",
  },
  {
    id: "responsive",
    label: "Responsive layout",
    hint: "Ctrl+Shift+M → test 375px, 768px, 1280px — no horizontal overflow.",
  },
  {
    id: "buttons",
    label: "Button hierarchy",
    hint: "Section 6 → Primary CTA + underline text secondary (no gray box).",
  },
];

export function OnPageReviewPanel() {
  const [checked, setChecked] = useState<Record<string, boolean>>({});

  useEffect(() => {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    if (stored) {
      try {
        setChecked(JSON.parse(stored) as Record<string, boolean>);
      } catch {
        setChecked({});
      }
    }
  }, []);

  const toggle = (id: string) => {
    setChecked((prev) => {
      const next = { ...prev, [id]: !prev[id] };
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      return next;
    });
  };

  const doneCount = checklistItems.filter((item) => checked[item.id]).length;

  return (
    <section
      aria-labelledby="on-page-review-heading"
      className="mb-8 rounded-lg border border-accent/20 bg-surface p-5 sm:p-6"
    >
      <div className="mb-4 flex flex-wrap items-start justify-between gap-3">
        <div>
          <p className="text-small font-medium text-accent">On-page review</p>
          <h2 id="on-page-review-heading" className="text-h4 mt-1">
            Phase 0 checklist — test here before approval
          </h2>
          <p className="text-small mt-1 text-text-secondary">
            Tick each item as you verify it on this page. Progress saves in your browser.
          </p>
        </div>
        <p className="text-small shrink-0 font-medium text-text-primary">
          {doneCount}/{checklistItems.length} done
        </p>
      </div>

      <ul className="space-y-3">
        {checklistItems.map((item) => {
          const isChecked = Boolean(checked[item.id]);
          return (
            <li key={item.id}>
              <button
                type="button"
                onClick={() => toggle(item.id)}
                className="flex w-full items-start gap-3 rounded-md border border-border bg-background p-3 text-left transition-colors hover:border-accent/30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
                aria-pressed={isChecked}
              >
                {isChecked ? (
                  <CheckCircle2 className="mt-0.5 h-5 w-5 shrink-0 text-success" aria-hidden="true" />
                ) : (
                  <Circle className="mt-0.5 h-5 w-5 shrink-0 text-border-strong" aria-hidden="true" />
                )}
                <span>
                  <span className="text-small block font-medium text-text-primary">
                    {item.label}
                  </span>
                  <span className="text-small mt-0.5 block text-text-secondary">
                    {item.hint}
                  </span>
                </span>
              </button>
            </li>
          );
        })}
      </ul>
    </section>
  );
}

