  const textSize = compact ? "text-[11px]" : "text-small";
  const statSize = compact ? "text-base" : "text-stat";

  const accentBars = [
    "from-accent to-accent/60",
    "from-brand-cyan to-brand-cyan/50",
    "from-primary to-primary/70",
  ];
  const accentBorders = [
    "border-t-accent",
    "border-t-brand-cyan",
    "border-t-primary",
  ];

  return (
    <div>
      <BrowserMockupChart
        data={current.chart}
        points={current.chartPoints}
        chartLabel={current.chartLabel}
        compact={compact}
        className="mb-4"
      />

      <div className="grid grid-cols-3 gap-2 sm:gap-4">
        {current.stats.map((stat, i) => (
          <div
            key={stat.label}
            className={cn(
              "rounded-xl border border-accent/10 border-t-2 bg-gradient-to-b from-accent/4 to-background p-3 sm:p-4",
              accentBorders[i % accentBorders.length],
            )}
          >
            <p className={cn(statSize, "font-semibold text-text-primary")}>{stat.value}</p>
            <p
              className={cn(
                "mt-0.5 text-text-secondary",
                compact ? "text-[10px]" : "text-small",
              )}
            >
              {stat.label}
            </p>
            <div className="mt-2 h-1 overflow-hidden rounded-full bg-border/80">
              <div
                className={cn(
                  "h-full rounded-full bg-gradient-to-r",
                  accentBars[i % accentBars.length],
                )}
                style={{ width: `${stat.progress}%` }}
              />
            </div>
          </div>
        ))}
      </div>

      <div className="mt-4 overflow-hidden rounded-xl border border-accent/10 sm:mt-6">
        <table className={cn("w-full text-left", textSize)}>
          <thead>
            <tr className="border-b border-accent/12 bg-gradient-to-r from-accent/5 via-transparent to-transparent">
              <th className="px-3 py-2 font-medium text-text-secondary sm:px-4 sm:py-3" scope="col">
                Metric
              </th>
              <th className="px-3 py-2 font-medium text-text-secondary sm:px-4 sm:py-3" scope="col">
                Value
              </th>
              <th className="px-3 py-2 text-right font-medium text-text-secondary sm:px-4 sm:py-3" scope="col">
                Change
              </th>
            </tr>
          </thead>
          <tbody>
            {current.table.map((row) => (
              <tr key={row.label} className="border-b border-border/80 last:border-0">
                <td className="px-3 py-2.5 text-text-primary sm:px-4 sm:py-3">{row.label}</td>
                <td className="px-3 py-2.5 font-medium text-text-primary sm:px-4 sm:py-3">
                  {row.value}
                </td>
                <td
                  className={cn(
                    "px-3 py-2.5 text-right font-medium sm:px-4 sm:py-3",
                    row.positive ? "text-success" : "text-error",
                  )}
                >
                  {row.change}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { useId } from "react";
import { cn } from "@/lib/utils";
import type { ChartPoint } from "./browser-mockup-data";

interface BrowserMockupChartProps {
  data: number[];
  points: ChartPoint[];
  chartLabel: string;
  compact?: boolean;
  className?: string;
}

function buildAreaPath(
  data: number[],
  width: number,
  height: number,
  padding: { top: number; right: number; bottom: number; left: number },
): { line: string; coords: { x: number; y: number }[] } {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;
  const innerWidth = width - padding.left - padding.right;
  const innerHeight = height - padding.top - padding.bottom;

  const coords = data.map((value, index) => ({
    x: padding.left + (index / (data.length - 1)) * innerWidth,
    y: padding.top + (1 - (value - min) / range) * innerHeight,
  }));

  const line = coords
    .map((point, index) => `${index === 0 ? "M" : "L"} ${point.x} ${point.y}`)
    .join(" ");

  return { line, coords };
}

export function BrowserMockupChart({
  data,
  points,
  chartLabel,
  compact = false,
  className,
}: BrowserMockupChartProps) {
  const chartId = useId().replace(/:/g, "");
  const width = compact ? 280 : 520;
  const height = compact ? 80 : 104;
  const padding = compact
    ? { top: 12, right: 8, bottom: 18, left: 8 }
    : { top: 14, right: 12, bottom: 22, left: 12 };

  const { line, coords } = buildAreaPath(data, width, height, padding);
  const lastPoint = coords[coords.length - 1];
  const lastDataPoint = points[points.length - 1];
  const gridLines = [0.25, 0.5, 0.75].map((ratio) => height * ratio);

  const areaGradientId = `area-${chartId}`;
  const lineGradientId = `line-${chartId}`;
  const glowFilterId = `glow-${chartId}`;

  return (
    <div
      className={cn(
        "rounded-lg border border-accent/12 bg-gradient-to-b from-accent/5 via-background to-background",
        compact ? "p-2 shadow-[0_1px_4px_rgba(255,153,0,0.06)]" : "p-4 shadow-[0_2px_8px_rgba(255,153,0,0.07)]",
        className,
      )}
      role="img"
      aria-label={`${chartLabel} chart showing ${lastDataPoint.value}`}
    >
      <div className="mb-2 flex items-center justify-between gap-2">
        <p className={cn("font-medium text-text-primary", compact ? "text-[10px]" : "text-xs")}>
          {chartLabel}
        </p>
        <p
          className={cn(
            "rounded-md border border-accent/15 bg-background px-2 py-1 text-text-primary",
            compact ? "text-[9px]" : "text-[10px]",
          )}
        >
          <span className="font-semibold">{lastDataPoint.value}</span>
          <span className="text-text-secondary"> · {lastDataPoint.label}</span>
        </p>
      </div>

      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="w-full"
        preserveAspectRatio="none"
        aria-hidden="true"
      >
        <defs>
          <linearGradient id={areaGradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--color-accent)" stopOpacity="0.18" />
            <stop offset="55%" stopColor="var(--color-brandCyan)" stopOpacity="0.07" />
            <stop offset="100%" stopColor="var(--color-primary)" stopOpacity="0.03" />
          </linearGradient>
          <linearGradient id={lineGradientId} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="var(--color-primary)" />
            <stop offset="70%" stopColor="var(--color-primary)" />
            <stop offset="100%" stopColor="var(--color-accent)" />
          </linearGradient>
          <filter id={glowFilterId} x="-10%" y="-10%" width="120%" height="120%">
            <feDropShadow
              dx="0"
              dy="1"
              stdDeviation={compact ? 0.8 : 1.2}
              floodColor="var(--color-accent)"
              floodOpacity="0.22"
            />
          </filter>
        </defs>

        {gridLines.map((y) => (
          <line
            key={y}
            x1={padding.left}
            y1={y}
            x2={width - padding.right}
            y2={y}
            stroke="var(--color-accent)"
            strokeWidth="0.5"
            strokeDasharray="3 4"
            opacity="0.1"
          />
        ))}

        <path d={`${line} L ${coords[coords.length - 1].x} ${height - padding.bottom} L ${coords[0].x} ${height - padding.bottom} Z`} fill={`url(#${areaGradientId})`} />

        <path
          d={line}
          fill="none"
          stroke={`url(#${lineGradientId})`}
          strokeWidth={compact ? 1.75 : 2.25}
          strokeLinecap="round"
          strokeLinejoin="round"
          filter={`url(#${glowFilterId})`}
        />

        <circle
          cx={lastPoint.x}
          cy={lastPoint.y}
          r={compact ? 3.5 : 4}
          fill="var(--color-accent)"
          stroke="var(--color-background)"
          strokeWidth="1.5"
        />
      </svg>

      <div
        className={cn(
          "flex justify-between text-text-secondary",
          compact ? "mt-1 px-1 text-[9px]" : "mt-2 px-1 text-[10px]",
        )}
      >
        <span>{points[0]?.label}</span>
        <span className="text-accent/80">{points[points.length - 1]?.label}</span>
      </div>
    </div>
  );
}

