  Search,
  Shield,
  Star,
  TrendingUp,
} as const satisfies Record<string, LucideIcon>;

export type IconName = keyof typeof iconRegistry;

export function getIcon(name: string): LucideIcon | undefined {
  return iconRegistry[name as IconName];
}

