"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import { Slot } from "@radix-ui/react-slot";
import { designSystem } from "@/lib/design-tokens";
import { cn } from "@/lib/utils";

export interface PrimaryButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  asChild?: boolean;
}

const primaryButtonMotion = designSystem.motion.primaryButton as {
  lift: number;
  duration: number;
  ease: string;
};

/**
 * Custom minimal motion — sleek lift + soft shadow + Amazon orange fill.
 * Values from content/config/design-system.json → motion.primaryButton
 */
const PrimaryButton = React.forwardRef<HTMLButtonElement, PrimaryButtonProps>(
  ({ className, children, asChild = false, ...props }, ref) => {
    const prefersReducedMotion = useReducedMotion();
    const durationSeconds = primaryButtonMotion.duration / 1000;

    const sharedClassName = cn(
      "relative inline-flex h-11 items-center justify-center rounded-sm px-6 text-sm font-medium text-text-on-dark",
      "bg-primary shadow-sm transition-colors duration-300 ease-out hover:bg-accent",
      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
      "disabled:pointer-events-none disabled:opacity-50",
      className,
    );

    if (asChild) {
      return (
        <Slot className={sharedClassName} ref={ref} {...props}>
          {children}
        </Slot>
      );
    }

    return (
      <motion.button
        ref={ref}
        type={props.type ?? "button"}
        disabled={props.disabled}
        onClick={props.onClick}
        className={sharedClassName}
        whileHover={
          prefersReducedMotion
            ? undefined
            : {
                y: primaryButtonMotion.lift,
                boxShadow: "0 6px 20px rgba(11, 27, 58, 0.15)",
              }
        }
        whileTap={prefersReducedMotion ? undefined : { y: 0, scale: 0.99 }}
        transition={{ duration: durationSeconds, ease: primaryButtonMotion.ease }}
      >
        {children}
      </motion.button>
    );
  },
);
PrimaryButton.displayName = "PrimaryButton";

export { PrimaryButton };

"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import { designSystem } from "@/lib/design-tokens";
import { cn } from "@/lib/utils";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "./card";

interface ElegantCardProps {
  className?: string;
  title?: string;
  description?: string;
  children?: React.ReactNode;
}

const cardMotion = designSystem.motion.card as {
  lift: number;
  duration: number;
  ease: string;
};

/**
 * Minimal card hover — lift, soft shadow, subtle border brighten.
 * Values from content/config/design-system.json → motion.card
 */
export function ElegantCard({
  className,
  title,
  description,
  children,
}: ElegantCardProps) {
  const prefersReducedMotion = useReducedMotion();
  const durationSeconds = cardMotion.duration / 1000;

  return (
    <motion.div
      whileHover={
        prefersReducedMotion
          ? undefined
          : {
              y: cardMotion.lift,
              boxShadow: "0 8px 24px rgba(11, 27, 58, 0.08)",
            }
      }
      transition={{ duration: durationSeconds, ease: cardMotion.ease }}
      className={cn(
        "rounded-md border border-border transition-colors duration-300 hover:border-primary/15",
        className,
      )}
    >
      <Card className="border-0 shadow-none">
        {(title || description) && (
          <CardHeader>
            {title && <CardTitle>{title}</CardTitle>}
            {description && <CardDescription>{description}</CardDescription>}
          </CardHeader>
        )}
        {children && <CardContent>{children}</CardContent>}
      </Card>
    </motion.div>
  );
}

