import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";

interface SiteHeaderShellProps {
  navigation: NavigationConfig;
  site: SiteConfig;
}

export function SiteHeaderShell({ navigation, site }: SiteHeaderShellProps) {
  const [scrolled, setScrolled] = useState(false);
  const { header } = navigation;

  useEffect(() => {
    const onScroll = () => {
      setScrolled(window.scrollY > 4);
    };

    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <header
      className={cn(
        "z-50 w-full border-b border-border bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/90",
        header.sticky && "sticky top-0",
        scrolled ? "shadow-header" : "shadow-none",
      )}
    >
      <div
        className="container-page flex items-center justify-between gap-4"
        style={{ minHeight: header.height }}
      >
        <Link
          href={header.logoHref}
          className="flex shrink-0 items-center rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
          aria-label={`${site.name} home`}
        >
          <BrandLogo width={140} height={42} className="h-8 w-auto sm:h-9" />
        </Link>

        <div className="flex flex-1 items-center justify-end gap-4">
          <HeaderNav items={header.items} megaMenu={navigation.megaMenu} />

          <PrimaryButton asChild className="hidden min-h-11 sm:inline-flex">
            <Link href={header.cta.href}>{header.cta.label}</Link>
          </PrimaryButton>

          <PrimaryButton asChild className="inline-flex min-h-11 px-4 text-xs sm:hidden">
            <Link href={header.cta.href} aria-label={header.cta.label}>
              Audit
            </Link>
          </PrimaryButton>
        </div>
      </div>
    </header>
  );
}

import Link from "next/link";
import type { SiteConfig } from "@/domain/content/schemas";

interface AnnouncementBarProps {
  site: SiteConfig;
}

export function AnnouncementBar({ site }: AnnouncementBarProps) {
  const { announcementBar } = site;

  if (!announcementBar.enabled || announcementBar.items.length === 0) {
    return null;
  }

  return (
    <div
      className="border-b border-border bg-primary text-text-on-dark"
      role="region"
      aria-label="Site announcements"
    >
      <div className="container-page flex flex-wrap items-center justify-center gap-x-4 gap-y-1 py-2 text-center text-small">
        {announcementBar.items.map((item, index) => (
          <span key={item} className="inline-flex items-center gap-4">
            {index > 0 ? (
              <span className="hidden text-text-on-dark/50 sm:inline" aria-hidden="true">
                |
              </span>
            ) : null}
            <span>{item}</span>
          </span>
        ))}
        {announcementBar.link ? (
          <Link
            href={announcementBar.link.href}
            className="font-medium underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary"
          >
            {announcementBar.link.label}
          </Link>
        ) : null}
      </div>
    </div>
  );
}

import { AnnouncementBar } from "@/components/layout/announcement-bar";
import { SiteHeaderShell } from "@/components/layout/site-header-shell";
import { getContentRepository } from "@/infrastructure/content/get-content-repository";

export async function SiteHeader() {
  const repository = getContentRepository();
  const [navigation, site] = await Promise.all([
    repository.getNavigation(),
    repository.getSiteConfig(),
  ]);

  return (
    <>
      <AnnouncementBar site={site} />
      <SiteHeaderShell navigation={navigation} site={site} />
    </>
  );
}

