import { cn } from "@/lib/utils";

interface FooterLinkProps {
  link: NavLink;
  className?: string;
}

export function FooterLink({ link, className }: FooterLinkProps) {
  const sharedClassName = cn(
    "text-small text-text-secondary transition-colors hover:text-link-hover focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
    className,
  );

  if (link.external) {
    return (
      <a
        href={link.href}
        className={sharedClassName}
        target="_blank"
        rel="noopener noreferrer"
      >
        {link.label}
      </a>
    );
  }

  return (
    <Link href={link.href} className={sharedClassName}>
      {link.label}
    </Link>
  );
}

