interface FooterBrandColumnProps {
  title: string;
  site: SiteConfig;
}

const socialLabels: Record<string, string> = {
  linkedin: "LinkedIn",
  facebook: "Facebook",
  instagram: "Instagram",
};

export function FooterBrandColumn({ title, site }: FooterBrandColumnProps) {
  const partnerBadge = site.partnerBadges[0];
  const socialEntries = Object.entries(site.social).filter(
    ([, url]) => Boolean(url),
  );

  return (
    <div>
      <BrandLogo width={140} height={42} className="mb-4 h-8 w-auto" />
      <p className="text-small font-semibold text-text-primary">{title}</p>
      <p className="mt-2 text-small text-text-secondary">{site.tagline}</p>

      {partnerBadge ? (
        <div className="mt-4">
          {partnerBadge.image ? (
            <Image
              src={partnerBadge.image}
              alt={partnerBadge.label}
              width={120}
              height={40}
              className="h-10 w-auto"
            />
          ) : (
            <Badge variant="outline">{partnerBadge.label}</Badge>
          )}
        </div>
      ) : null}

      {socialEntries.length > 0 ? (
        <ul className="mt-4 space-y-2" aria-label="Social media links">
          {socialEntries.map(([network, url]) => (
            <li key={network}>
