"use client";

import * as React from "react";
import * as AccordionPrimitive from "@radix-ui/react-accordion";
import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";

const Accordion = AccordionPrimitive.Root;

const AccordionItem = React.forwardRef<
  React.ComponentRef<typeof AccordionPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Item>
>(({ className, ...props }, ref) => (
  <AccordionPrimitive.Item
    ref={ref}
    className={cn("border-b border-border", className)}
    {...props}
  />
));
AccordionItem.displayName = "AccordionItem";

const AccordionTrigger = React.forwardRef<
  React.ComponentRef<typeof AccordionPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Header className="flex">
    <AccordionPrimitive.Trigger
      ref={ref}
      className={cn(
        "flex min-h-11 flex-1 items-center justify-between py-3 text-sm font-medium text-text-primary transition-all hover:text-link-hover focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 [&[data-state=open]>svg]:rotate-180",
        className,
      )}
      {...props}
    >
      {children}
      <ChevronDown
        className="h-4 w-4 shrink-0 text-text-secondary transition-transform duration-200"
        aria-hidden="true"
      />
    </AccordionPrimitive.Trigger>
  </AccordionPrimitive.Header>
));
AccordionTrigger.displayName = AccordionPrimitive.Trigger.displayName;

const AccordionContent = React.forwardRef<
  React.ComponentRef<typeof AccordionPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Content>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Content
    ref={ref}
    className="overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down"
    {...props}
  >
    <div className={cn("pb-4 pt-0", className)}>{children}</div>
  </AccordionPrimitive.Content>
));
AccordionContent.displayName = AccordionPrimitive.Content.displayName;

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

"use client";

import * as React from "react";
import * as SheetPrimitive from "@radix-ui/react-dialog";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";

const Sheet = SheetPrimitive.Root;
const SheetTrigger = SheetPrimitive.Trigger;
const SheetClose = SheetPrimitive.Close;
const SheetPortal = SheetPrimitive.Portal;

const SheetOverlay = React.forwardRef<
  React.ComponentRef<typeof SheetPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Overlay
    ref={ref}
    className={cn(
      "fixed inset-0 z-50 bg-primary/40 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
      className,
    )}
    {...props}
  />
));
SheetOverlay.displayName = SheetPrimitive.Overlay.displayName;

const SheetContent = React.forwardRef<
  React.ComponentRef<typeof SheetPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Content> & {
    side?: "top" | "right" | "bottom" | "left";
  }
>(({ side = "right", className, children, ...props }, ref) => (
  <SheetPortal>
    <SheetOverlay />
    <SheetPrimitive.Content
      ref={ref}
      className={cn(
        "fixed z-50 flex flex-col gap-4 bg-background shadow-lg transition ease-in-out data-[state=closed]:duration-300 data-[state=open]:duration-300 data-[state=open]:animate-in data-[state=closed]:animate-out",
        side === "right" &&
          "inset-y-0 right-0 h-full w-full max-w-sm border-l border-border data-[state=closed]:slide-out-to-right data-[state=open]:slide-in-from-right",
        side === "left" &&
          "inset-y-0 left-0 h-full w-full max-w-sm border-r border-border data-[state=closed]:slide-out-to-left data-[state=open]:slide-in-from-left",
        className,
      )}
      {...props}
    >
      {children}
      <SheetPrimitive.Close
        className="absolute right-4 top-4 inline-flex min-h-11 min-w-11 items-center justify-center rounded-sm text-text-secondary transition-colors hover:text-text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
        aria-label="Close"
      >
        <X className="h-5 w-5" aria-hidden="true" />
      </SheetPrimitive.Close>
    </SheetPrimitive.Content>
  </SheetPortal>
));
SheetContent.displayName = SheetPrimitive.Content.displayName;

const SheetHeader = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn("flex flex-col space-y-2 pr-12 text-center sm:text-left", className)}
    {...props}
  />
);
SheetHeader.displayName = "SheetHeader";

const SheetTitle = React.forwardRef<
  React.ComponentRef<typeof SheetPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Title>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Title
    ref={ref}
    className={cn("text-h4 font-semibold text-text-primary", className)}
    {...props}
  />
));
SheetTitle.displayName = SheetPrimitive.Title.displayName;

const SheetDescription = React.forwardRef<
  React.ComponentRef<typeof SheetPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Description>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Description
    ref={ref}
    className={cn("text-small text-text-secondary", className)}
    {...props}
  />
));
SheetDescription.displayName = SheetPrimitive.Description.displayName;

export {
  Sheet,
  SheetPortal,
  SheetOverlay,
  SheetTrigger,
  SheetClose,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
};

"use client";

import { useState } from "react";
import Link from "next/link";
import { Menu } from "lucide-react";
import type { HeaderNavItem, NavigationConfig } from "@/domain/content/schemas";
import type { SiteConfig } from "@/domain/content/schemas";
import { FooterLink } from "@/components/layout/footer-link";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { PrimaryButton } from "@/components/ui/primary-button";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { cn } from "@/lib/utils";

interface MobileNavProps {
  navigation: NavigationConfig;
  site: SiteConfig;
  className?: string;
}

function MobileNavLink({
  href,
  label,
  external,
  onNavigate,
}: {
  href: string;
  label: string;
  external?: boolean;
  onNavigate: () => void;
}) {
  const className =
    "flex min-h-11 items-center rounded-sm px-2 text-sm font-medium text-text-primary transition-colors hover:bg-surface-muted hover:text-link-hover focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2";

  if (external) {
    return (
      <a
        href={href}
        className={className}
        target="_blank"
        rel="noopener noreferrer"
        onClick={onNavigate}
      >
        {label}
      </a>
    );
  }

  return (
    <Link href={href} className={className} onClick={onNavigate}>
      {label}
    </Link>
  );
}

export function MobileNav({ navigation, site, className }: MobileNavProps) {
  const [open, setOpen] = useState(false);
  const { header, megaMenu, mobile } = navigation;

  const servicesItem = header.items.find(
    (item): item is Extract<HeaderNavItem, { type: "megaMenu" }> =>
      item.type === "megaMenu" && item.id === megaMenu.triggerId,
  );
  const linkItems = header.items.filter(
    (item): item is Extract<HeaderNavItem, { type: "link" }> =>
      item.type === "link",
  );

  const closeMenu = () => setOpen(false);

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger
        className={cn(
          "inline-flex min-h-11 min-w-11 items-center justify-center rounded-sm text-text-primary transition-colors hover:bg-surface-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 lg:hidden",
          className,
        )}
        aria-label={mobile.menuLabel}
      >
        <Menu className="h-5 w-5" aria-hidden="true" />
      </SheetTrigger>

      <SheetContent side="right" aria-label={mobile.menuLabel}>
        <SheetHeader>
          <SheetTitle>{site.name}</SheetTitle>
        </SheetHeader>

        <nav className="flex flex-1 flex-col overflow-y-auto px-1" aria-label="Mobile">
          {servicesItem ? (
            <Accordion type="single" collapsible className="w-full">
              <AccordionItem value="services">
                <AccordionTrigger>{mobile.servicesExpandLabel}</AccordionTrigger>
                <AccordionContent>
                  <div className="space-y-6">
                    {megaMenu.columns.map((column) => (
                      <div key={column.id}>
                        <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-text-secondary">
                          {column.title}
                        </p>
                        <ul className="space-y-1">
                          {column.links.map((link) => (
                            <li key={`${column.id}-${link.href}`}>
                              <MobileNavLink
                                href={link.href}
                                label={link.label}
                                external={link.external}
                                onNavigate={closeMenu}
                              />
                            </li>
                          ))}
                        </ul>
                      </div>
                    ))}

                    <div className="rounded-sm bg-primary p-4 text-text-on-dark">
                      <p className="text-sm font-semibold">
                        {megaMenu.ctaPanel.title}
                      </p>
                      <p className="mt-1 text-small text-text-on-dark/90">
                        {megaMenu.ctaPanel.body}
                      </p>
                      <div className="mt-4 space-y-3">
                        <PrimaryButton
                          asChild
                          className="w-full bg-accent hover:bg-accent-alt"
                        >
                          <Link
                            href={megaMenu.ctaPanel.button.href}
                            onClick={closeMenu}
                          >
                            {megaMenu.ctaPanel.button.label}
                          </Link>
                        </PrimaryButton>
                        <a
                          href={`tel:${megaMenu.ctaPanel.phone.tel}`}
                          className="block min-h-11 text-small font-medium underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary"
                          onClick={closeMenu}
                        >
                          {megaMenu.ctaPanel.phone.display}
                        </a>
                      </div>
                    </div>
                  </div>
                </AccordionContent>
              </AccordionItem>
            </Accordion>
          ) : null}

          <ul className="space-y-1 border-t border-border pt-2">
            {linkItems.map((item) => (
              <li key={item.id}>
                <MobileNavLink
                  href={item.href}
                  label={item.label}
                  external={item.external}
                  onNavigate={closeMenu}
                />
              </li>
            ))}
          </ul>

          <div className="mt-6 space-y-4 border-t border-border pt-6">
            <PrimaryButton asChild className="w-full">
              <Link href={header.cta.href} onClick={closeMenu}>
                {header.cta.label}
              </Link>
            </PrimaryButton>
            <a
              href={`tel:${site.phone.tel}`}
              className="flex min-h-11 items-center justify-center text-sm font-medium text-text-primary underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
              onClick={closeMenu}
            >
              {site.phone.display}
            </a>
            <FooterLink
              link={{
                label: site.email,
                href: `mailto:${site.email}`,
              }}
              className="flex min-h-11 items-center justify-center"
            />
          </div>
        </nav>
      </SheetContent>
    </Sheet>
  );
}

