import type { BrowserTab, BrowserVariant } from "@/lib/content-config";

export type { BrowserTab, BrowserVariant };

export interface BrowserMockupProps {
  /** Additional Tailwind classes on the figure wrapper */
  className?: string;
  /** Browser chrome variant. Default from design-system.json */
  variant?: BrowserVariant;
  /** Optional figcaption above the frame */
  label?: string;
  /** Override the default tab for this variant (homepage.json, service pages) */
  tabId?: string;
}

export interface BrowserChromeProps {
  url: string;
  tabs: BrowserTab[];
  activeTabId: string;
  variant: BrowserVariant;
}

import { Lock, RotateCw, Share } from "lucide-react";
import { cn } from "@/lib/utils";
import type { BrowserChromeProps, BrowserTab, BrowserVariant } from "./browser-mockup.types";

function StaticTabBar({
  tabs,
  activeTabId,
  variant,
}: {
  tabs: BrowserTab[];
  activeTabId: string;
  variant: BrowserVariant;
}) {
  if (variant === "ios") {
    return (
      <div className="px-4 pb-4 pt-1" aria-hidden="true">
        <div className="flex rounded-lg bg-surface-muted p-0.5">
          {tabs.map((tab) => (
            <div
              key={tab.id}
              className={cn(
                "flex-1 rounded-md px-2 py-1.5 text-center text-[11px] font-medium",
                activeTabId === tab.id
                  ? "bg-background text-text-primary shadow-sm ring-1 ring-accent/15"
                  : "text-text-secondary",
              )}
            >
              <span className="hidden sm:inline">{tab.label}</span>
              <span className="sm:hidden">{tab.shortLabel}</span>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div
      className="flex h-full min-w-0 flex-1 items-center gap-1 overflow-x-auto pr-2"
      aria-hidden="true"
    >
      {tabs.map((tab) => (
        <div
          key={tab.id}
          className={cn(
            "flex h-7 max-w-[128px] shrink-0 items-center truncate rounded-md px-2.5 text-xs font-medium leading-none",
            activeTabId === tab.id
              ? "bg-background text-text-primary shadow-sm ring-1 ring-accent/20"
              : "text-text-secondary",
          )}
        >
          {tab.label}
        </div>
      ))}
    </div>
  );
}

export function MacChrome({ url, tabs, activeTabId, variant }: BrowserChromeProps) {
  return (
    <>
      <div className="flex h-9 items-center gap-1 bg-surface-muted">
        <div className="flex shrink-0 items-center gap-1.5 pl-3 pr-1" aria-hidden="true">
          <span className="h-3 w-3 rounded-full bg-[#FF5F57]" />
          <span className="h-3 w-3 rounded-full bg-[#FFBD2E]" />
          <span className="h-3 w-3 rounded-full bg-[#28C840]" />
        </div>
        <div className="h-4 w-px shrink-0 bg-border" aria-hidden="true" />
        <div className="flex shrink-0 items-center gap-0.5 text-text-secondary" aria-hidden="true">
          <span className="flex h-6 w-6 items-center justify-center">
            <span className="text-xs">{"<"}</span>
          </span>
          <span className="flex h-6 w-6 items-center justify-center">
            <span className="text-xs">{">"}</span>
          </span>
          <span className="flex h-6 w-6 items-center justify-center">
            <RotateCw className="h-3 w-3" />
          </span>
        </div>
        <div className="h-4 w-px shrink-0 bg-border" aria-hidden="true" />
        <StaticTabBar tabs={tabs} activeTabId={activeTabId} variant={variant} />
      </div>
      <div className="border-b border-border bg-background px-4 py-2">
        <div className="flex min-w-0 items-center gap-2 rounded-full border border-border bg-surface px-4 py-1.5">
          <Lock className="h-3.5 w-3.5 shrink-0 text-success" aria-hidden="true" />
          <span className="truncate text-xs text-text-primary">{url}</span>
        </div>
      </div>
    </>
  );
}

export function IosChrome({ url, tabs, activeTabId, variant }: BrowserChromeProps) {
  return (
    <>
      <div className="grid grid-cols-3 items-center px-5 pt-3 pb-2" aria-hidden="true">
        <span className="text-[11px] font-semibold tracking-tight text-text-primary">9:41</span>
        <div className="flex justify-center">
          <div className="h-[22px] w-[76px] rounded-full bg-primary" />
        </div>
        <div className="flex items-center justify-end gap-1.5">
          <div className="flex items-end gap-[2px]">
            {[3, 5, 7, 9].map((barHeight) => (
              <span
                key={barHeight}
                className="w-[2.5px] rounded-sm bg-text-primary"
                style={{ height: barHeight }}
              />
            ))}
          </div>
          <div className="relative ml-0.5 flex h-[10px] w-[22px] items-center rounded-[3px] border border-text-primary/75 p-[1px]">
            <div className="h-full w-[78%] rounded-[1.5px] bg-text-primary" />
          </div>
        </div>
      </div>
      <div className="flex items-center gap-2 px-4 pb-3" aria-hidden="true">
        <div className="flex h-8 w-8 items-center justify-center rounded-full bg-background/70 text-text-secondary">
          <span className="text-sm">{"<"}</span>
        </div>
        <div className="flex flex-1 items-center gap-2 rounded-full border border-border bg-background px-3 py-2 shadow-sm">
          <Lock className="h-3 w-3 shrink-0 text-text-secondary" aria-hidden="true" />
          <span className="truncate text-[11px] text-text-primary">{url}</span>
        </div>
        <div className="flex h-8 w-8 items-center justify-center rounded-full bg-background/70 text-text-secondary">
          <Share className="h-3.5 w-3.5" />
        </div>
      </div>
      <StaticTabBar tabs={tabs} activeTabId={activeTabId} variant={variant} />
    </>
  );
}

import { designSystem } from "@/lib/design-tokens";
import {
  getBrowserTabById,
  getBrowserTabs,
  getDefaultTabId,
} from "@/lib/content-config";
import { cn } from "@/lib/utils";
import { IosChrome, MacChrome } from "./browser-chrome";
import { BrowserMockupContent } from "./browser-mockup-content";
import type { BrowserMockupProps } from "./browser-mockup.types";

const browserMockupSpec = designSystem.components.browserMockup as {
  staticPreview?: boolean;
  defaultVariant?: string;
};

export function BrowserMockup({
  className,
  variant = (browserMockupSpec.defaultVariant as BrowserMockupProps["variant"]) ??
    "macos",
  label,
  tabId,
}: BrowserMockupProps) {
  const tabs = getBrowserTabs();
  const activeTabId = tabId ?? getDefaultTabId(variant);
  const current = getBrowserTabById(activeTabId) ?? tabs[0];

  const frameClass =
    variant === "ios"
      ? "overflow-hidden rounded-[2rem] border border-border bg-surface shadow-lg"
      : "overflow-hidden rounded-xl border border-border bg-surface-muted shadow-lg";

  const previewLabel = label ?? variant;

  return (
    <figure className={cn(variant === "ios" ? "mx-auto max-w-md" : "w-full", className)}>
      {label ? (
        <figcaption className="text-small mb-3 font-medium text-text-secondary">
          {label}
        </figcaption>
      ) : null}
      <div
        className={frameClass}
        role="img"
        aria-label={`${previewLabel} dashboard preview showing ${current.label}`}
      >
        {variant === "ios" ? (
          <IosChrome
            url={current.url}
            tabs={tabs}
            activeTabId={activeTabId}
            variant={variant}
          />
        ) : (
          <MacChrome
            url={current.url}
            tabs={tabs}
            activeTabId={activeTabId}
            variant={variant}
          />
        )}

        <div
          className={cn(
            "bg-background",
            variant === "ios" ? "px-4 pb-5 pt-3" : "p-5 sm:p-6",
          )}
        >
          <BrowserMockupContent current={current} compact={variant === "ios"} />
        </div>

        {variant === "ios" ? (
          <div className="flex justify-center pb-2 pt-1" aria-hidden="true">
            <div className="h-1 w-28 rounded-full bg-primary/20" />
          </div>
        ) : null}
      </div>
    </figure>
  );
}

export { BrowserMockup } from "./browser-mockup";
export { BrowserMockupContent } from "./browser-mockup-content";
export { BrowserMockupChart } from "./browser-mockup-chart";
export { MacChrome, IosChrome } from "./browser-chrome";
export type {
  BrowserMockupProps,
  BrowserChromeProps,
  BrowserTab,
  BrowserVariant,
} from "./browser-mockup.types";
export {
  browserMockupConfig,
  getBrowserTabs,
  getBrowserTabById,
  getDefaultTabId,
} from "./browser-mockup-data";

export type {
  BrowserTab,
  BrowserVariant,
  ChartPoint,
  TableRow,
} from "@/lib/content-config";

export {
  browserMockupConfig,
  getBrowserTabs,
  getBrowserTabById,
  getDefaultTabId,
} from "@/lib/content-config";

export type { BrowserMockupProps } from "./browser-mockup.types";

