export interface NavLinkData {
  label: string;
  href: string;
}

export function readString(value: unknown, fallback = ""): string {
  return typeof value === "string" ? value : fallback;
}

export function readNavLink(value: unknown): NavLinkData | null {
  if (!value || typeof value !== "object") {
    return null;
  }

  const record = value as Record<string, unknown>;
  if (typeof record.label !== "string" || typeof record.href !== "string") {
    return null;
  }

  return { label: record.label, href: record.href };
}

export function readRecordArray(value: unknown): Record<string, unknown>[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value.filter(
    (item): item is Record<string, unknown> =>
      Boolean(item) && typeof item === "object",
  );
}

export function readStringRecord(value: unknown): Record<string, string> {
  if (!value || typeof value !== "object") {
    return {};
  }

  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>).filter(
      (entry): entry is [string, string] => typeof entry[1] === "string",
    ),
  );
}

import { cn } from "@/lib/utils";

interface SectionShellProps {
  id: string;
  children: React.ReactNode;
  className?: string;
  tone?: "default" | "muted" | "primary";
  ariaLabelledBy?: string;
}

export function SectionShell({
  id,
  children,
  className,
  tone = "default",
  ariaLabelledBy,
}: SectionShellProps) {
  const toneClass =
    tone === "muted"
      ? "bg-surface"
      : tone === "primary"
        ? "bg-primary text-text-on-dark"
        : "";

  return (
    <section
      id={id}
      className={cn("scroll-mt-24 py-12 sm:py-16", toneClass, className)}
      {...(ariaLabelledBy ? { "aria-labelledby": ariaLabelledBy } : {})}
    >
      <div className="container-page">{children}</div>
    </section>
  );
}

import { cn } from "@/lib/utils";

interface SectionHeadingProps {
  heading: string;
  subheading?: string;
  headingId?: string;
  inverted?: boolean;
  className?: string;
}

export function SectionHeading({
  heading,
  subheading,
  headingId,
  inverted = false,
  className,
}: SectionHeadingProps) {
  return (
    <div className={cn("mb-8 max-w-2xl md:mb-10", className)}>
      <h2
        id={headingId}
        className={cn("text-h2", inverted && "text-text-on-dark")}
      >
        {heading}
      </h2>
      {subheading ? (
        <p
          className={cn(
            "mt-3 text-body",
            inverted ? "text-text-on-dark/90" : "text-text-secondary",
          )}
        >
          {subheading}
        </p>
      ) : null}
    </div>
  );
}

import {
  Briefcase,
  FileText,
  Image as ImageIcon,
  Layers,
  Search,
  Target,
  type LucideIcon,
} from "lucide-react";
import { cn } from "@/lib/utils";

const ICON_MAP: Record<string, LucideIcon> = {
  briefcase: Briefcase,
  target: Target,
  search: Search,
  "file-text": FileText,
  image: ImageIcon,
  layers: Layers,
};

interface SectionIconProps {
  name: string;
  className?: string;
}

export function SectionIcon({ name, className }: SectionIconProps) {
  const Icon = ICON_MAP[name] ?? Briefcase;

  return (
    <Icon
      className={cn("h-5 w-5 text-accent", className)}
      aria-hidden="true"
    />
  );
}

export function formatPublishedDate(isoDate: string): string {
  const date = new Date(isoDate);
  if (Number.isNaN(date.getTime())) {
    return isoDate;
  }

  return new Intl.DateTimeFormat("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
  }).format(date);
}

import Link from "next/link";
import { BrowserMockup } from "@/components/browser-mockup";
import { PrimaryButton } from "@/components/ui/primary-button";
import { Badge } from "@/components/ui/badge";
import { readNavLink, readString, readStringRecord } from "./section-data";
import { SectionShell } from "./section-shell";

interface HeroSectionProps {
  id: string;
  data: Record<string, unknown>;
}

export function HeroSection({ id, data }: HeroSectionProps) {
  const headline = readString(data.headline);
  const subheadline = readString(data.subheadline);
  const differentiation = readString(data.differentiation);
  const trustLine = readString(data.trustLine);
  const primaryCta = readNavLink(data.primaryCta);
  const visual = data.visual as Record<string, unknown> | undefined;
  const tabIds = readStringRecord(visual?.tabIds);
  const variants = Array.isArray(visual?.variants)
    ? visual.variants.filter((item): item is string => typeof item === "string")
    : ["macos"];

  return (
    <SectionShell id={id} ariaLabelledBy={`${id}-heading`}>
      <div className="grid items-center gap-10 lg:grid-cols-2 lg:gap-12">
        <div>
          <h1 id={`${id}-heading`} className="text-h1">
            {headline}
          </h1>
          {subheadline ? (
            <p className="mt-4 text-body text-text-secondary">{subheadline}</p>
          ) : null}
          {differentiation ? (
            <p className="mt-4 text-body text-text-primary">{differentiation}</p>
          ) : null}
          {primaryCta ? (
            <div className="mt-8">
              <PrimaryButton asChild>
                <Link href={primaryCta.href}>{primaryCta.label}</Link>
              </PrimaryButton>
            </div>
          ) : null}
          {trustLine ? (
            <p className="mt-6 text-small text-text-secondary">{trustLine}</p>
          ) : null}
        </div>

        <div className="space-y-6">
          {variants.includes("macos") ? (
            <BrowserMockup variant="macos" tabId={tabIds.macos} />
          ) : null}
          {variants.includes("ios") ? (
            <BrowserMockup variant="ios" tabId={tabIds.ios} />
          ) : null}
        </div>
      </div>
    </SectionShell>
  );
}

import Link from "next/link";
import { Badge } from "@/components/ui/badge";
import { readRecordArray, readString } from "./section-data";
import { SectionShell } from "./section-shell";

interface TrustBarSectionProps {
  id: string;
  data: Record<string, unknown>;
}

function TrustLogo({
  label,
  image,
  alt,
  href,
}: {
  label: string;
  image: string;
  alt: string;
  href?: string;
}) {
  const content = (
    <div className="flex h-16 min-w-[120px] items-center justify-center rounded-md border border-border bg-background px-4">
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={image}
        alt={alt || label}
        className="max-h-12 max-w-[140px] object-contain"
        loading="lazy"
        onError={(event) => {
          const target = event.currentTarget;
          target.style.display = "none";
          const fallback = target.nextElementSibling;
          if (fallback instanceof HTMLElement) {
            fallback.hidden = false;
          }
        }}
      />
      <Badge variant="outline" className="hidden whitespace-nowrap">
        {label}
      </Badge>
    </div>
  );

  if (href) {
    return (
      <Link
        href={href}
        className="transition-opacity hover:opacity-80"
        target="_blank"
        rel="noopener noreferrer"
      >
        {content}
      </Link>
    );
  }

  return content;
}

export function TrustBarSection({ id, data }: TrustBarSectionProps) {
  const statLine = readString(data.statLine);
  const badge = data.badge as Record<string, unknown> | undefined;
  const badgeLabel = readString(badge?.label);
  const logos = readRecordArray(data.logos);

  return (
    <SectionShell id={id} tone="muted" className="py-8 sm:py-10">
      <div className="flex flex-col items-center gap-6 text-center">
        {badgeLabel ? (
          <Badge variant="accent">{badgeLabel}</Badge>
        ) : null}
        {statLine ? (
          <p className="text-small font-medium text-text-primary">{statLine}</p>
        ) : null}
        {logos.length > 0 ? (
          <ul className="flex flex-wrap items-center justify-center gap-4">
            {logos.map((logo) => {
              const label = readString(logo.label);
              const image = readString(logo.image);
              if (!label && !image) {
                return null;
              }

              return (
                <li key={`${label}-${image}`}>
                  <TrustLogo
                    label={label}
                    image={image}
                    alt={readString(logo.alt, label)}
                    href={readString(logo.href) || undefined}
                  />
                </li>
              );
            })}
          </ul>
        ) : null}
      </div>
    </SectionShell>
  );
}

