() => {
  const canonical = document.querySelector('link[rel="canonical"]')?.getAttribute('href');
  const description = document.querySelector('meta[name="description"]')?.getAttribute('content');
  const ogTitle = document.querySelector('meta[property="og:title"]')?.getAttribute('content');
  const scripts = Array.from(document.querySelectorAll('script[type="application/ld+json"]'));
  const jsonLd = scripts.map(s => {
    try { return JSON.parse(s.textContent || ''); } catch { return null; }
  }).filter(Boolean);
  const graph = jsonLd.flatMap(j => j['@graph'] || [j]);
  const types = graph.map(n => n['@type']).flat();
  const faqCount = graph.find(n => n['@type'] === 'FAQPage')?.mainEntity?.length ?? 0;
  return { title: document.title, description, canonical, ogTitle, jsonLdScriptCount: scripts.length, schemaTypes: types, faqQuestionCount: faqCount };
}

