import * as cheerio from "cheerio";

const CONTENT_WIDGET_TYPES = new Set([
  "text-editor.default",
  "heading.default",
  "image.default",
  "html.default",
]);

const STOP_WIDGET_TYPES = new Set([
  "share-buttons.default",
  "wpr-grid.default",
  "elementskit-blog-posts.default",
  "wpr-taxonomy-list.default",
  "wpr-post-info.default",
  "post-info.default",
  "wpr-promo-box.default",
]);

export function extractPostBodyHtml(elementorHtml: string): string {
  const $ = cheerio.load(elementorHtml, { decodeEntities: false });
  const fragments: string[] = [];

  $(".elementor-widget").each((_, element) => {
    const widgetType = $(element).attr("data-widget_type") ?? "";

    if (STOP_WIDGET_TYPES.has(widgetType)) {
      return false;
    }

    if (!CONTENT_WIDGET_TYPES.has(widgetType)) {
      return;
    }

    const container = $(element).find(".elementor-widget-container").first();
    if (!container.length) {
      return;
    }

    const html = container.html()?.trim();
    if (!html) {
      return;
    }

    if (isSocialShareBlock(html)) {
      return;
    }

    fragments.push(html);
  });

  return fragments.join("\n\n");
}

function isSocialShareBlock(html: string): boolean {
  const normalized = html.toLowerCase();
  return (
    normalized.includes("contact us") &&
    (normalized.includes("facebook") ||
      normalized.includes("linkedin") ||
      normalized.includes("whatsapp"))
  );
}

export function stripHtml(html: string): string {
  return cheerio.load(html).root().text().replace(/\s+/g, " ").trim();
}

import TurndownService from "turndown";

const turndown = new TurndownService({
  headingStyle: "atx",
  codeBlockStyle: "fenced",
  emDelimiter: "*",
});

turndown.addRule("preserveImages", {
  filter: "img",
  replacement: (_content, node) => {
    const element = node as HTMLImageElement;
    const alt = element.getAttribute("alt") ?? "";
    const src = element.getAttribute("src") ?? "";
    if (!src) {
      return "";
    }
    return `![${alt}](${src})`;
  },
});

export function htmlToMarkdown(html: string): string {
  if (!html.trim()) {
    return "";
  }

  return turndown
    .turndown(html)
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

import type { BlogPostFrontmatter } from "../../../src/domain/content/schemas/blog-post.schema";
import { stripHtml } from "./extract-post-html";

interface WordPressPost {
  slug: string;
  title: { rendered: string };
  excerpt: { rendered: string };
  date: string;
  modified: string;
  author: number;
  categories: number[];
  tags: number[];
  featured_media: number;
  yoast_head_json?: {
    title?: string;
    description?: string;
    canonical?: string;
    og_description?: string;
    og_image?: Array<{ url: string }>;
    author?: string;
    robots?: {
      index?: string;
      follow?: string;
    };
    twitter_misc?: Record<string, string>;
  };
}

interface LookupMaps {
  authors: Map<number, string>;
  categories: Map<number, string>;
  tags: Map<number, string>;
  media: Map<number, string>;
}

export function buildFrontmatter(
  post: WordPressPost,
  maps: LookupMaps,
  markdownBody: string,
): BlogPostFrontmatter {
  const yoast = post.yoast_head_json ?? {};
  const excerpt = buildExcerpt(post.excerpt.rendered, markdownBody);
  const metaDescription = buildMetaDescription(
    yoast.description,
    yoast.og_description,
    excerpt,
  );

  const featuredImage =
    yoast.og_image?.[0]?.url ??
    maps.media.get(post.featured_media) ??
    "";

  const readingTimeMinutes = parseReadingTime(yoast.twitter_misc);

  const frontmatter: BlogPostFrontmatter = {
    slug: post.slug,
    title: stripHtml(post.title.rendered),
    excerpt,
    publishedAt: normalizeDate(post.date),
    updatedAt: normalizeDate(post.modified),
    author: yoast.author ?? maps.authors.get(post.author) ?? "eCom Gliders",
    categories: post.categories
      .map((id) => maps.categories.get(id))
      .filter((name): name is string => Boolean(name)),
    tags: post.tags
      .map((id) => maps.tags.get(id))
      .filter((name): name is string => Boolean(name)),
    featuredImage,
    seo: {
      metaTitle: yoast.title ?? stripHtml(post.title.rendered),
      metaDescription,
      canonical: yoast.canonical ?? `https://ecomgliders.com/${post.slug}/`,
      ogImage: featuredImage || undefined,
      robots: {
        index: yoast.robots?.index !== "noindex",
        follow: yoast.robots?.follow !== "nofollow",
      },
      schema: "Article",
    },
  };

  if (readingTimeMinutes) {
    frontmatter.readingTimeMinutes = readingTimeMinutes;
  }

  return frontmatter;
}

function normalizeDate(value: string): string {
  return new Date(value).toISOString();
}

function buildExcerpt(excerptHtml: string, markdownBody: string): string {
  const fromExcerpt = stripHtml(excerptHtml);
  if (fromExcerpt.length >= 40) {
    return truncateText(fromExcerpt, 320);
  }

  const firstParagraph = markdownBody
    .split("\n\n")
    .find((block) => block.trim() && !block.startsWith("#") && !block.startsWith("!["));
  return truncateText(firstParagraph?.replace(/\[(.+?)\]\(.+?\)/g, "$1") ?? fromExcerpt, 320);
}

function buildMetaDescription(
  description: string | undefined,
  ogDescription: string | undefined,
  excerpt: string,
): string {
  if (description?.trim()) {
    return truncateText(description.trim(), 160);
  }

  if (ogDescription?.trim() && ogDescription.length <= 200) {
    return truncateText(ogDescription.trim(), 160);
  }

  return truncateText(excerpt, 160);
}

function truncateText(value: string, maxLength: number): string {
  if (value.length <= maxLength) {
    return value;
  }
  return `${value.slice(0, maxLength - 1).trimEnd()}…`;
}

function parseReadingTime(
  twitterMisc: Record<string, string> | undefined,
): number | undefined {
  const raw = twitterMisc?.["Est. reading time"];
  if (!raw) {
    return undefined;
  }

  const match = raw.match(/(\d+)/);
  return match ? Number.parseInt(match[1], 10) : undefined;
}

import fs from "node:fs/promises";
import path from "node:path";
import matter from "gray-matter";
import { blogPostFrontmatterSchema } from "../../src/domain/content/schemas/blog-post.schema";
import { buildFrontmatter } from "./lib/build-frontmatter";
import { extractPostBodyHtml } from "./lib/extract-post-html";
import { htmlToMarkdown } from "./lib/html-to-markdown";

const ROOT = path.resolve(import.meta.dirname, "../..");
const POSTS_PATH = path.join(ROOT, "backup/metadata/api/posts-all.json");
const INVENTORY_PATH = path.join(ROOT, "backup/metadata/blog-inventory.json");
const CATEGORIES_PATH = path.join(ROOT, "backup/metadata/api/categories-all.json");
const TAGS_PATH = path.join(ROOT, "backup/metadata/api/tags-all.json");
const USERS_PATH = path.join(ROOT, "backup/metadata/api/users-all.json");
const MEDIA_PATH = path.join(ROOT, "backup/metadata/api/media-all.json");
const OUTPUT_DIR = path.join(ROOT, "content/blog");
const REPORT_PATH = path.join(ROOT, "docs/qa/blog-migration-report.json");

interface WordPressEntity {
  id: number;
  name: string;
}

interface WordPressMedia {
  id: number;
  source_url: string;
}

interface WordPressPost {
  slug: string;
  title: { rendered: string };
  content: { rendered: string };
  excerpt: { rendered: string };
  date: string;
  modified: string;
  author: number;
  categories: number[];
  tags: number[];
  featured_media: number;
  yoast_head_json?: Record<string, unknown>;
}

interface InventoryEntry {
  slug: string;
}

interface MigrationFailure {
  slug: string;
  reason: string;
}

interface MigrationReport {
  generatedAt: string;
  source: string;
  expectedCount: number;
  writtenCount: number;
  skippedCount: number;
  failures: MigrationFailure[];
}

async function readJson<T>(filePath: string): Promise<T> {
  const raw = await fs.readFile(filePath, "utf8");
  return JSON.parse(raw) as T;
}

function buildNameMap(items: WordPressEntity[]): Map<number, string> {
  return new Map(items.map((item) => [item.id, item.name]));
}

function buildMediaMap(items: WordPressMedia[]): Map<number, string> {
  return new Map(items.map((item) => [item.id, item.source_url]));
}

async function main(): Promise<void> {
  const [posts, inventory, categories, tags, users, media] = await Promise.all([
    readJson<WordPressPost[]>(POSTS_PATH),
    readJson<InventoryEntry[]>(INVENTORY_PATH),
    readJson<WordPressEntity[]>(CATEGORIES_PATH),
    readJson<WordPressEntity[]>(TAGS_PATH),
    readJson<WordPressEntity[]>(USERS_PATH),
    readJson<WordPressMedia[]>(MEDIA_PATH),
  ]);

  const postsBySlug = new Map(posts.map((post) => [post.slug, post]));
  const expectedSlugs = inventory.map((entry) => entry.slug);
  const maps = {
    authors: buildNameMap(users),
    categories: buildNameMap(categories),
    tags: buildNameMap(tags),
    media: buildMediaMap(media),
  };

  await fs.mkdir(OUTPUT_DIR, { recursive: true });

  const failures: MigrationFailure[] = [];
  let writtenCount = 0;

  for (const slug of expectedSlugs) {
    const post = postsBySlug.get(slug);
    if (!post) {
      failures.push({ slug, reason: "Post not found in posts-all.json" });
      continue;
    }

    const bodyHtml = extractPostBodyHtml(post.content.rendered);
    if (!bodyHtml.trim()) {
      failures.push({ slug, reason: "No article body extracted from Elementor content" });
      continue;
    }

    const markdownBody = htmlToMarkdown(bodyHtml);
    if (!markdownBody.trim()) {
      failures.push({ slug, reason: "HTML-to-Markdown conversion produced empty body" });
      continue;
    }

    const frontmatter = buildFrontmatter(post, maps, markdownBody);
    const parsed = blogPostFrontmatterSchema.safeParse(frontmatter);
    if (!parsed.success) {
      failures.push({
        slug,
        reason: `Frontmatter validation failed: ${parsed.error.message}`,
      });
      continue;
    }

    const fileContents = matter.stringify(markdownBody, parsed.data);
    const outputPath = path.join(OUTPUT_DIR, `${slug}.mdx`);
    await fs.writeFile(outputPath, fileContents, "utf8");
    writtenCount += 1;
  }

  const report: MigrationReport = {
    generatedAt: new Date().toISOString(),
    source: "backup/metadata/api/posts-all.json",
    expectedCount: expectedSlugs.length,
    writtenCount,
    skippedCount: failures.length,
    failures,
  };

  await fs.mkdir(path.dirname(REPORT_PATH), { recursive: true });
  await fs.writeFile(REPORT_PATH, `${JSON.stringify(report, null, 2)}\n`, "utf8");

  console.log(`Migration complete: ${writtenCount}/${expectedSlugs.length} MDX files written`);
  if (failures.length > 0) {
    console.log(`Failures: ${failures.length}`);
    for (const failure of failures.slice(0, 10)) {
      console.log(`  - ${failure.slug}: ${failure.reason}`);
    }
    if (failures.length > 10) {
      console.log(`  ... and ${failures.length - 10} more (see ${REPORT_PATH})`);
    }
    process.exitCode = 1;
  }
}

main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});

