function formatPostDate(isoDate: string): string {
  return new Intl.DateTimeFormat("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
    timeZone: "UTC",
  }).format(new Date(isoDate));
}

interface BlogPostArticleProps {
  post: BlogPost;
}

export function BlogPostArticle({ post }: BlogPostArticleProps) {
  const metaParts = [
    formatPostDate(post.publishedAt),
    post.readingTimeMinutes ? `${post.readingTimeMinutes} min read` : null,
    post.author,
  ].filter(Boolean);

  return (
    <article className="container-page py-10 md:py-14">
      <div className="mx-auto max-w-3xl">
        <header className="mb-8 border-b border-border pb-8">
          <h1 className="text-h1 mb-4">{post.title}</h1>
          <p className="text-small text-text-secondary">{metaParts.join(" · ")}</p>
          {post.featuredImage ? (
            <div className="relative mt-6 aspect-video overflow-hidden rounded-lg border border-border bg-surface-muted">
              <Image
                src={post.featuredImage}
                alt=""
                fill
                priority
                className="object-cover"
                sizes="(max-width: 768px) 100vw, 768px"
              />
            </div>
          ) : null}
        </header>

        <BlogMarkdown content={post.content} />
      </div>
    </article>
  );
}

import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { BlogPostArticle } from "@/components/blog/blog-post-article";
import { getContentRepository } from "@/infrastructure/content/get-content-repository";
import { buildBlogPostJsonLd } from "@/lib/seo/blog-post-json-ld";
import { JsonLdScript } from "@/lib/seo/json-ld-script";
import { pageSeoToMetadata } from "@/lib/seo/page-metadata";

export const dynamicParams = false;

interface BlogPostPageProps {
  params: Promise<{ slug: string }>;
}

export async function generateStaticParams() {
  const repository = getContentRepository();
  const slugs = await repository.getAllBlogSlugs();

  return slugs.map((slug) => ({ slug }));
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { slug } = await params;
  const repository = getContentRepository();
  const post = await repository.getBlogPost(slug);

  if (!post) {
    return {
      title: "Post not found | eCom Gliders",
      robots: { index: false, follow: false },
    };
  }

  return pageSeoToMetadata(post.seo, { openGraphType: "article" });
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { slug } = await params;
  const repository = getContentRepository();
  const [post, site] = await Promise.all([
    repository.getBlogPost(slug),
    repository.getSiteConfig(),
  ]);

  if (!post) {
    notFound();
  }

  const jsonLd = buildBlogPostJsonLd({ post, site });

  return (
    <>
      <JsonLdScript data={jsonLd} />
      <main id="main-content">
        <BlogPostArticle post={post} />
      </main>
    </>
  );
}

