export function slugifyHeading(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
}

export function createHeadingId(text: string, usedIds: Map<string, number>): string {
  const baseId = slugifyHeading(text) || "section";
  const count = usedIds.get(baseId) ?? 0;

  if (count === 0) {
    usedIds.set(baseId, 1);
    return baseId;
  }

  const nextId = `${baseId}-${count + 1}`;
  usedIds.set(baseId, count + 1);
  return nextId;
}

import { createHeadingId } from "./slugify-heading";

export interface TocItem {
  id: string;
  text: string;
  level: 2 | 3 | 4 | 5;
}

const SKIP_HEADINGS = /^recent posts$|^conclusion:?$/i;

export function extractTableOfContents(markdown: string): TocItem[] {
  const items: TocItem[] = [];
  const usedIds = new Map<string, number>();

  for (const line of markdown.split("\n")) {
    const match = line.match(/^(#{2,5})\s+(.+)$/);
    if (!match) {
      continue;
    }

    const level = match[1].length as 2 | 3 | 4 | 5;
    const text = match[2].replace(/\*\*/g, "").trim();

    if (text.length < 3 || SKIP_HEADINGS.test(text)) {
      continue;
    }

    items.push({
      id: createHeadingId(text, usedIds),
      text,
      level,
    });
  }

  return items;
}

import type { FaqItem } from "@/domain/content/schemas";

const FAQ_SECTION_HEADING = /^#{2,6}\s+.*\bFAQ/i;
const QUESTION_HEADING = /^#{4,6}\s+(.+\?)\s*$/;
const BOLD_QUESTION = /\*\*([^*]+\?)\*\*/;

function cleanMarkdownText(value: string): string {
  return value
    .replace(/\*\*/g, "")
    .replace(/\[(.+?)\]\(.+?\)/g, "$1")
    .replace(/\s+/g, " ")
    .trim();
}

function collectAnswerLines(lines: string[], startIndex: number): string {
  const parts: string[] = [];

  for (let index = startIndex; index < lines.length; index += 1) {
    const line = lines[index];

    if (/^#{1,6}\s/.test(line) || BOLD_QUESTION.test(line)) {
      break;
    }

    if (/^recent posts$/i.test(line.trim())) {
      break;
    }

    const trimmed = line.trim();
    if (trimmed) {
      parts.push(trimmed);
    }
  }

  return cleanMarkdownText(parts.join(" "));
}

function findFaqSectionStart(lines: string[]): number {
  return lines.findIndex((line) => FAQ_SECTION_HEADING.test(line));
}

export function splitBlogContent(markdown: string): {
  mainContent: string;
  faqItems: FaqItem[];
} {
  const lines = markdown.split("\n");
  const faqItems = extractFaqItems(markdown);

  if (faqItems.length === 0) {
    return { mainContent: markdown, faqItems: [] };
  }

  const faqSectionStart = findFaqSectionStart(lines);
  if (faqSectionStart === -1) {
    return { mainContent: markdown, faqItems };
  }

  let faqSectionEnd = lines.length;
  for (let index = faqSectionStart + 1; index < lines.length; index += 1) {
    if (/^##\s/.test(lines[index]) && !FAQ_SECTION_HEADING.test(lines[index])) {
      faqSectionEnd = index;
      break;
    }
    if (/^recent posts$/i.test(lines[index].replace(/^#+\s*/, "").trim())) {
      faqSectionEnd = index;
      break;
    }
  }

  const mainContent = [
    ...lines.slice(0, faqSectionStart),
    ...lines.slice(faqSectionEnd),
  ]
    .join("\n")
    .trim();

  return { mainContent, faqItems };
}

export function extractFaqItems(markdown: string): FaqItem[] {
  const items: FaqItem[] = [];
  const lines = markdown.split("\n");
  const seen = new Set<string>();

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const headingMatch = line.match(QUESTION_HEADING);

    if (headingMatch) {
      const question = cleanMarkdownText(headingMatch[1]);
      const answer = collectAnswerLines(lines, index + 1);
      if (question && answer.length >= 20) {
        addFaqItem(items, seen, question, answer);
      }
      continue;
    }

    const boldMatch = line.match(BOLD_QUESTION);
    if (boldMatch) {
      const question = cleanMarkdownText(boldMatch[1]);
      const answer = collectAnswerLines(lines, index + 1);
      if (question && answer.length >= 20) {
        addFaqItem(items, seen, question, answer);
      }
    }
  }

  return items.slice(0, 10);
}

function addFaqItem(
  items: FaqItem[],
  seen: Set<string>,
  question: string,
  answer: string,
): void {
  const key = question.toLowerCase();
  if (seen.has(key)) {
    return;
  }

  seen.add(key);
  items.push({ question, answer });
}

import type { BlogPost, BlogPostFrontmatter } from "@/domain/content/schemas";

export function selectRelatedPostSlugs(
  current: BlogPostFrontmatter,
  candidates: BlogPostFrontmatter[],
  limit = 3,
): string[] {
  const others = candidates.filter((post) => post.slug !== current.slug);

  const sameCategory = others.filter((post) =>
    post.categories.some((category) => current.categories.includes(category)),
  );

  const sameTag = others.filter((post) =>
    post.tags.some((tag) => current.tags.includes(tag)),
  );

  const pool =
    sameCategory.length >= limit
      ? sameCategory
      : sameTag.length >= limit
        ? sameTag
        : others;

  return pool
    .sort(
      (left, right) =>
        new Date(right.publishedAt).getTime() -
        new Date(left.publishedAt).getTime(),
    )
    .slice(0, limit)
    .map((post) => post.slug);
}

export function toRelatedPostCards(posts: BlogPost[]) {
  return posts.map((post) => ({
    slug: post.slug,
    title: post.title,
    excerpt: post.excerpt,
    publishedAt: post.publishedAt,
    href: `/${post.slug}/`,
  }));
}

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { z } from "zod";

const blogAuthorSchema = z.object({
  name: z.string(),
  title: z.string(),
  bio: z.string(),
});

const blogAuthorsConfigSchema = z.record(z.string(), blogAuthorSchema);

export type BlogAuthorProfile = z.infer<typeof blogAuthorSchema>;

let cachedAuthors: Record<string, BlogAuthorProfile> | null = null;

function loadBlogAuthors(): Record<string, BlogAuthorProfile> {
  if (cachedAuthors) {
    return cachedAuthors;
  }

  const filePath = join(process.cwd(), "content/config/blog-authors.json");
  const raw = readFileSync(filePath, "utf-8");
  cachedAuthors = blogAuthorsConfigSchema.parse(JSON.parse(raw));
  return cachedAuthors;
}

export function getBlogAuthor(name: string): BlogAuthorProfile {
  const authors = loadBlogAuthors();
  return (
    authors[name] ?? {
      name,
      title: "Contributor",
      bio: `${name} contributes Amazon marketplace insights for eCom Gliders readers.`,
    }
  );
}

