import type { BlogPost, FaqItem, SiteConfig } from "@/domain/content/schemas";
import { absoluteUrl, getSiteUrl } from "./site-url";

interface BuildBlogPostJsonLdInput {
  post: BlogPost;
  site: SiteConfig;
  faqItems?: FaqItem[];
}

export function buildBlogPostJsonLd({
  post,
  site,
  faqItems = [],
}: BuildBlogPostJsonLdInput): Record<string, unknown> {
  const pageUrl = absoluteUrl(post.seo.canonical);

  const blogPosting = {
    "@type": "BlogPosting",
    headline: post.title,
    description: post.excerpt,
    datePublished: post.publishedAt,
    dateModified: post.updatedAt,
    author: {
      "@type": "Person",
      name: post.author,
    },
    publisher: {
      "@type": "Organization",
      name: site.name,
      url: getSiteUrl(),
    },
    image: post.featuredImage ? absoluteUrl(post.featuredImage) : undefined,
    mainEntityOfPage: {
      "@type": "WebPage",
      "@id": pageUrl,
    },
    url: pageUrl,
  };

  const graph: Record<string, unknown>[] = [blogPosting];

  if (faqItems.length > 0) {
    graph.push({
      "@type": "FAQPage",
      mainEntity: faqItems.map((item) => ({
        "@type": "Question",
        name: item.question,
        acceptedAnswer: {
          "@type": "Answer",
          text: item.answer,
        },
      })),
    });
  }

  return {
    "@context": "https://schema.org",
    "@graph": graph,
  };
}

import type { Metadata } from "next";
import { notFound } from "next/navigation";
import {
  BlogPostArticle,
  getBlogPostFaqItems,
} from "@/components/blog/blog-post-article";
import { getContentRepository } from "@/infrastructure/content/get-content-repository";
import { buildBlogPostJsonLd } from "@/lib/seo/blog-post-json-ld";
import { JsonLdScript } from "@/lib/seo/json-ld-script";
import { pageSeoToMetadata } from "@/lib/seo/page-metadata";

export const dynamicParams = false;

interface BlogPostPageProps {
  params: Promise<{ slug: string }>;
}

export async function generateStaticParams() {
  const repository = getContentRepository();
  const slugs = await repository.getAllBlogSlugs();

  return slugs.map((slug) => ({ slug }));
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { slug } = await params;
  const repository = getContentRepository();
  const post = await repository.getBlogPost(slug);

  if (!post) {
    return {
      title: "Post not found | eCom Gliders",
      robots: { index: false, follow: false },
    };
  }

  return pageSeoToMetadata(post.seo, { openGraphType: "article" });
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { slug } = await params;
  const repository = getContentRepository();
  const [post, site, relatedPosts] = await Promise.all([
    repository.getBlogPost(slug),
    repository.getSiteConfig(),
    repository.getRelatedBlogPosts(slug, 3),
  ]);

  if (!post) {
    notFound();
  }

  const faqItems = getBlogPostFaqItems(post.content);
  const jsonLd = buildBlogPostJsonLd({ post, site, faqItems });

  return (
    <>
      <JsonLdScript data={jsonLd} />
      <main id="main-content">
        <BlogPostArticle post={post} relatedPosts={relatedPosts} site={site} />
      </main>
    </>
  );
}

