import type { ServicePageConfig, SiteConfig } from "@/domain/content/schemas";
import { absoluteUrl, getSiteUrl } from "./site-url";

interface BuildServicePageJsonLdInput {
  service: ServicePageConfig;
  site: SiteConfig;
}

export function buildServicePageJsonLd({
  service,
  site,
}: BuildServicePageJsonLdInput): Record<string, unknown> {
  const pageUrl = absoluteUrl(service.seo.canonical);
  const organizationId = `${getSiteUrl()}/#organization`;

  const serviceNode: Record<string, unknown> = {
    "@type": "Service",
    name: service.hero.title,
    description: service.hero.subtitle,
    url: pageUrl,
    provider: {
      "@type": "Organization",
      "@id": organizationId,
      name: site.name,
      url: getSiteUrl(),
    },
    areaServed: {
      "@type": "Country",
      name: "United States",
    },
    serviceType: service.breadcrumbLabel,
  };

  const graph: Record<string, unknown>[] = [serviceNode];

  if (service.faq.length > 0) {
    graph.push({
      "@type": "FAQPage",
      "@id": `${pageUrl}#faq`,
      url: pageUrl,
      mainEntity: service.faq.map((item) => ({
        "@type": "Question",
        name: item.question,
        acceptedAnswer: {
          "@type": "Answer",
          text: item.answer,
        },
      })),
    });
  }

  return {
    "@context": "https://schema.org",
    "@graph": graph,
  };
}

import type { Metadata } from "next";
import { notFound } from "next/navigation";
import {
  BlogPostArticle,
  getBlogPostFaqItems,
} from "@/components/blog/blog-post-article";
import { ServicePageTemplate } from "@/components/services/service-page-template";
import { getContentRepository } from "@/infrastructure/content/get-content-repository";
import { buildBlogPostJsonLd } from "@/lib/seo/blog-post-json-ld";
import { JsonLdScript } from "@/lib/seo/json-ld-script";
import { pageSeoToMetadata } from "@/lib/seo/page-metadata";
import { buildServicePageJsonLd } from "@/lib/seo/service-page-json-ld";

export const dynamicParams = false;

interface SlugPageProps {
  params: Promise<{ slug: string }>;
}

export async function generateStaticParams() {
  const repository = getContentRepository();
  const [blogSlugs, serviceSlugs] = await Promise.all([
    repository.getAllBlogSlugs(),
    repository.getAllServiceSlugs(),
  ]);

  const allSlugs = [...new Set([...blogSlugs, ...serviceSlugs])];
  return allSlugs.map((slug) => ({ slug }));
}

export async function generateMetadata({
  params,
}: SlugPageProps): Promise<Metadata> {
  const { slug } = await params;
  const repository = getContentRepository();
  const service = await repository.getService(slug);

  if (service) {
    return pageSeoToMetadata(service.seo);
  }

  const post = await repository.getBlogPost(slug);

  if (!post) {
    return {
      title: "Page not found | eCom Gliders",
      robots: { index: false, follow: false },
    };
  }

  return pageSeoToMetadata(post.seo, { openGraphType: "article" });
}

export default async function SlugPage({ params }: SlugPageProps) {
  const { slug } = await params;
  const repository = getContentRepository();
  const site = await repository.getSiteConfig();
  const service = await repository.getService(slug);

  if (service) {
    const jsonLd = buildServicePageJsonLd({ service, site });

    return (
      <>
        <JsonLdScript data={jsonLd} />
        <main id="main-content">
          <ServicePageTemplate service={service} site={site} />
        </main>
      </>
    );
  }

  const [post, relatedPosts] = await Promise.all([
    repository.getBlogPost(slug),
    repository.getRelatedBlogPosts(slug, 3),
  ]);

  if (!post) {
    notFound();
  }

  const faqItems = getBlogPostFaqItems(post.content);
  const jsonLd = buildBlogPostJsonLd({ post, site, faqItems });

  return (
    <>
      <JsonLdScript data={jsonLd} />
      <main id="main-content">
        <BlogPostArticle post={post} relatedPosts={relatedPosts} site={site} />
      </main>
    </>
  );
}

