import { z } from "zod";
import { pageSeoSchema } from "./page-seo.schema";

const formFieldSchema = z.object({
  name: z.string(),
  label: z.string(),
  type: z.enum(["text", "email", "tel", "url", "textarea", "select"]),
  required: z.boolean(),
  placeholder: z.string().optional(),
  options: z
    .array(
      z.object({
        value: z.string(),
        label: z.string(),
      }),
    )
    .optional(),
});

const formConfigSchema = z.object({
  heading: z.string(),
  submitLabel: z.string(),
  successMessage: z.string(),
  errorMessage: z.string(),
  consentLabel: z.string(),
  fields: z.array(formFieldSchema),
});

export const contactPageConfigSchema = z.object({
  hero: z.object({
    title: z.string(),
    subtitle: z.string(),
  }),
  form: formConfigSchema,
  contactDetails: z.object({
    heading: z.string(),
    phoneLabel: z.string(),
    emailLabel: z.string(),
    addressLabel: z.string(),
  }),
  seo: pageSeoSchema,
});

export const freeAuditPageConfigSchema = z.object({
  hero: z.object({
    title: z.string(),
    subtitle: z.string(),
  }),
  benefits: z.object({
    heading: z.string(),
    items: z.array(z.string()),
  }),
  form: formConfigSchema,
  trustSignals: z.object({
    heading: z.string(),
    stats: z.array(
      z.object({
        value: z.string(),
        label: z.string(),
      }),
    ),
    testimonial: z
      .object({
        quote: z.string(),
        author: z.string(),
        role: z.string(),
      })
      .optional(),
  }),
  fallbackContact: z.object({
    heading: z.string(),
    phoneLabel: z.string(),
    emailLabel: z.string(),
  }),
  faq: z.array(
    z.object({
      question: z.string(),
      answer: z.string(),
    }),
  ),
  seo: pageSeoSchema,
});

export type ContactPageConfig = z.infer<typeof contactPageConfigSchema>;
export type FreeAuditPageConfig = z.infer<typeof freeAuditPageConfigSchema>;

const requestCounts = new Map<string, { count: number; resetAt: number }>();

const WINDOW_MS = 15 * 60 * 1000;
const MAX_REQUESTS = 5;

export function isRateLimited(key: string): boolean {
  const now = Date.now();
  const entry = requestCounts.get(key);

  if (!entry || now > entry.resetAt) {
    requestCounts.set(key, { count: 1, resetAt: now + WINDOW_MS });
    return false;
  }

  if (entry.count >= MAX_REQUESTS) {
    return true;
  }

  entry.count += 1;
  return false;
}

export function getRateLimitKey(headers: Headers, formType: string): string {
  const forwarded = headers.get("x-forwarded-for");
  const ip = forwarded?.split(",")[0]?.trim() ?? headers.get("x-real-ip") ?? "unknown";
  return `${formType}:${ip}`;
}

export function isHoneypotTriggered(value: FormDataEntryValue | null): boolean {
  if (typeof value !== "string") {
    return false;
  }

  return value.trim().length > 0;
}

interface FormNotificationPayload {
  formType: "contact" | "audit";
  subject: string;
  fields: Record<string, string>;
}

function sanitizeForLog(fields: Record<string, string>): Record<string, string> {
  return Object.fromEntries(
    Object.entries(fields).map(([key, value]) => [
      key,
      value.length > 120 ? `${value.slice(0, 120)}…` : value,
    ]),
  );
}

export async function notifyFormSubmission(
  payload: FormNotificationPayload,
): Promise<{ delivered: boolean; mode: "email" | "logged" }> {
  const apiKey = process.env.RESEND_API_KEY;
  const to = process.env.FORM_NOTIFICATION_EMAIL ?? process.env.CONTACT_FORM_TO;
  const from = process.env.FORM_FROM_EMAIL ?? "eCom Gliders Website <onboarding@resend.dev>";

  const bodyLines = Object.entries(payload.fields)
    .filter(([, value]) => value.length > 0)
    .map(([key, value]) => `${key}: ${value}`);

  const textBody = [`Form: ${payload.formType}`, "", ...bodyLines].join("\n");

  if (!apiKey || !to) {
    console.info("[form-submission]", {
      formType: payload.formType,
      fields: sanitizeForLog(payload.fields),
    });
    return { delivered: true, mode: "logged" };
  }

  const response = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from,
      to: [to],
      subject: payload.subject,
      text: textBody,
    }),
  });

  if (!response.ok) {
    console.error("[form-submission] email delivery failed", response.status);
    return { delivered: false, mode: "email" };
  }

  return { delivered: true, mode: "email" };
}

