export type FormActionState = {
  success: boolean;
  message: string;
  fieldErrors?: Record<string, string[]>;
};

export const initialFormActionState: FormActionState = {
  success: false,
  message: "",
};

export function formDataToRecord(formData: FormData): Record<string, string> {
  const record: Record<string, string> = {};

  for (const [key, value] of formData.entries()) {
    if (typeof value === "string") {
      record[key] = value;
    }
  }

  return record;
}

export function getFormString(formData: FormData, key: string): string | undefined {
  const value = formData.get(key);

  if (typeof value !== "string") {
    return undefined;
  }

  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

"use client";

import { useActionState } from "react";
import Link from "next/link";
import type { FormActionState } from "@/domain/forms/form-action-state";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { PrimaryButton } from "@/components/ui/primary-button";
import { cn } from "@/lib/utils";

interface FormFieldOption {
  value: string;
  label: string;
}

interface FormFieldConfig {
  name: string;
  label: string;
  type: "text" | "email" | "tel" | "url" | "textarea" | "select";
  required: boolean;
  placeholder?: string;
  options?: FormFieldOption[];
}

interface ConfigurableFormProps {
  formId: string;
  fields: FormFieldConfig[];
  submitLabel: string;
  consentLabel: string;
  action: (
    state: FormActionState,
    formData: FormData,
  ) => FormActionState | Promise<FormActionState>;
  initialState: FormActionState;
}

const selectClassName =
  "flex h-11 w-full rounded-sm border border-border bg-background px-3 py-2 text-sm text-text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent disabled:cursor-not-allowed disabled:opacity-50";

export function ConfigurableForm({
  formId,
  fields,
  submitLabel,
  consentLabel,
  action,
  initialState,
}: ConfigurableFormProps) {
  const [state, formAction, pending] = useActionState(action, initialState);

  return (
    <form action={formAction} noValidate className="space-y-6" aria-describedby={`${formId}-status`}>
      <div className="hidden" aria-hidden="true">
        <label htmlFor={`${formId}-website`}>Website</label>
        <input
          id={`${formId}-website`}
          name="website"
          type="text"
          tabIndex={-1}
          autoComplete="off"
        />
      </div>

      {fields.map((field) => {
        const fieldId = `${formId}-${field.name}`;
        const error = state.fieldErrors?.[field.name]?.[0];
        const errorId = error ? `${fieldId}-error` : undefined;

        return (
          <div key={field.name} className="space-y-2">
            <Label htmlFor={fieldId}>
              {field.label}
              {field.required ? (
                <span className="text-error" aria-hidden="true">
                  {" "}
                  *
                </span>
              ) : null}
            </Label>

            {field.type === "textarea" ? (
              <Textarea
                id={fieldId}
                name={field.name}
                required={field.required}
                placeholder={field.placeholder}
                aria-invalid={Boolean(error)}
                aria-describedby={errorId}
                rows={5}
              />
            ) : field.type === "select" ? (
              <select
                id={fieldId}
                name={field.name}
                required={field.required}
                aria-invalid={Boolean(error)}
                aria-describedby={errorId}
                className={cn(selectClassName, error && "border-error")}
                defaultValue=""
              >
                {field.options?.map((option) => (
                  <option key={`${field.name}-${option.value}`} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            ) : (
              <Input
                id={fieldId}
                name={field.name}
                type={field.type}
                required={field.required}
                placeholder={field.placeholder}
                aria-invalid={Boolean(error)}
                aria-describedby={errorId}
                className={error ? "border-error" : undefined}
              />
            )}

            {error ? (
              <p id={errorId} className="text-small text-error" role="alert">
                {error}
              </p>
            ) : null}
          </div>
        );
      })}

      <div className="space-y-2">
        <div className="flex items-start gap-3">
          <input
            id={`${formId}-consent`}
            name="consent"
            type="checkbox"
            value="true"
            required
            className="mt-1 h-4 w-4 rounded border-border text-accent focus-visible:ring-2 focus-visible:ring-accent"
            aria-invalid={Boolean(state.fieldErrors?.consent)}
            aria-describedby={
              state.fieldErrors?.consent ? `${formId}-consent-error` : `${formId}-consent-label`
            }
          />
          <Label id={`${formId}-consent-label`} htmlFor={`${formId}-consent`} className="font-normal">
            {consentLabel}{" "}
            <Link href="/privacy-policy-2/" className="text-link hover:text-link-hover hover:underline">
              Privacy policy
            </Link>
          </Label>
        </div>
        {state.fieldErrors?.consent ? (
          <p id={`${formId}-consent-error`} className="text-small text-error" role="alert">
            {state.fieldErrors.consent[0]}
          </p>
        ) : null}
      </div>

      <div id={`${formId}-status`} aria-live="polite">
        {state.message ? (
          <p
            className={cn(
              "rounded-sm border px-4 py-3 text-small",
              state.success
                ? "border-success/30 bg-success/10 text-text-primary"
                : "border-error/30 bg-error/10 text-text-primary",
            )}
            role={state.success ? "status" : "alert"}
          >
            {state.message}
          </p>
        ) : null}
      </div>

      <PrimaryButton type="submit" disabled={pending}>
        {pending ? "Submitting..." : submitLabel}
      </PrimaryButton>
    </form>
  );
}

"use server";

import { headers } from "next/headers";
import { contactFormSchema } from "@/domain/forms/contact-form.schema";
import {
  type FormActionState,
  getFormString,
  initialFormActionState,
} from "@/domain/forms/form-action-state";
import { notifyFormSubmission } from "@/infrastructure/forms/form-notifier";
import { isHoneypotTriggered } from "@/lib/security/honeypot";
import { getRateLimitKey, isRateLimited } from "@/lib/security/rate-limit";

export async function submitContactForm(
  _prevState: FormActionState,
  formData: FormData,
): Promise<FormActionState> {
  const requestHeaders = await headers();
  const rateLimitKey = getRateLimitKey(requestHeaders, "contact");

  if (isRateLimited(rateLimitKey)) {
    return {
      success: false,
      message: "Too many submissions. Please wait before trying again.",
    };
  }

  if (isHoneypotTriggered(formData.get("website"))) {
    return {
      success: true,
      message: "Your message was received. We will respond within one business day.",
    };
  }

  const parsed = contactFormSchema.safeParse({
    name: getFormString(formData, "name"),
    email: getFormString(formData, "email"),
    phone: getFormString(formData, "phone"),
    serviceInterest: getFormString(formData, "serviceInterest"),
    message: getFormString(formData, "message"),
    consent: formData.get("consent") === "true" ? "true" : undefined,
    website: getFormString(formData, "website") ?? "",
  });

  if (!parsed.success) {
    const fieldErrors = parsed.error.flatten().fieldErrors;

    return {
      success: false,
      message: "We could not submit the form. Review the fields below and try again.",
      fieldErrors,
    };
  }

  const { website: _honeypot, consent: _consent, ...fields } = parsed.data;

  const delivery = await notifyFormSubmission({
    formType: "contact",
    subject: `Contact form: ${fields.name}`,
    fields: {
      Name: fields.name,
      Email: fields.email,
      Phone: fields.phone,
      "Service interest": fields.serviceInterest ?? "",
      Message: fields.message,
    },
  });

  if (!delivery.delivered) {
    return {
      success: false,
      message: "We could not deliver your message. Please call us directly or try again later.",
    };
  }

  return {
    success: true,
    message: "Your message was received. We will respond within one business day.",
  };
}

