import type { MetadataRoute } from "next";

function escapeXml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

function formatLastModified(value: Date | string | undefined): string | null {
  if (!value) {
    return null;
  }

  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date.toISOString();
}

export function buildSitemapXml(entries: MetadataRoute.Sitemap): string {
  const urlNodes = entries
    .map((entry) => {
      const parts = [`    <loc>${escapeXml(entry.url)}</loc>`];
      const lastModified = formatLastModified(entry.lastModified);

      if (lastModified) {
        parts.push(`    <lastmod>${lastModified}</lastmod>`);
      }

      if (entry.changeFrequency) {
        parts.push(`    <changefreq>${entry.changeFrequency}</changefreq>`);
      }

      if (entry.priority !== undefined) {
        parts.push(`    <priority>${entry.priority.toFixed(1)}</priority>`);
      }

      return `  <url>\n${parts.join("\n")}\n  </url>`;
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urlNodes}\n</urlset>\n`;
}

import { getContentRepository } from "@/infrastructure/content/get-content-repository";
import { buildSitemapEntries } from "@/lib/seo/build-sitemap-entries";
import { buildSitemapXml } from "@/lib/seo/build-sitemap-xml";

export async function GET() {
  const repository = getContentRepository();
  const entries = await buildSitemapEntries(repository);
  const body = buildSitemapXml(entries);

  return new Response(body, {
    headers: {
      "Content-Type": "application/xml; charset=utf-8",
      "Cache-Control": "public, max-age=3600, s-maxage=3600",
    },
  });
}

import { getSiteUrl } from "@/lib/seo/site-url";

export function GET() {
  const siteUrl = getSiteUrl();
  const body = [
    "User-agent: *",
    "Allow: /",
    "Disallow: /api/",
    "Disallow: /design-system",
    "",
    `Sitemap: ${siteUrl}/sitemap.xml`,
    "",
  ].join("\n");

  return new Response(body, {
    headers: {
      "Content-Type": "text/plain; charset=utf-8",
      "Cache-Control": "public, max-age=3600, s-maxage=3600",
    },
  });
}

import { spawnSync } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

interface AuditTarget {
  id: string;
  path: string;
}

const DEFAULT_BASE_URL = "http://localhost:3002";

const TARGETS: AuditTarget[] = [
  { id: "home", path: "/" },
  { id: "service", path: "/amazon-ppc-management-agency/" },
  {
    id: "blog",
    path: "/when-should-you-use-sponsored-display-ads/",
  },
];

function runLighthouse(url: string, outputPath: string): number {
  const result = spawnSync(
    "npx",
    [
      "lighthouse",
      url,
      "--output=json",
      `--output-path=${outputPath}`,
      "--quiet",
      "--chrome-flags=--headless --no-sandbox --disable-gpu",
      "--only-categories=performance,accessibility,best-practices,seo",
    ],
    {
      encoding: "utf8",
      shell: true,
      stdio: ["ignore", "pipe", "pipe"],
    },
  );

  if (result.status !== 0) {
    console.error(result.stderr || result.stdout);
    return result.status ?? 1;
  }

  return 0;
}

function readScores(outputPath: string): Record<string, number | null> {
  const report = JSON.parse(
    require("node:fs").readFileSync(outputPath, "utf8"),
  ) as {
    categories?: Record<string, { score?: number | null }>;
    runtimeError?: { message?: string };
  };

  if (report.runtimeError?.message) {
    console.error(`Runtime error: ${report.runtimeError.message}`);
  }

  const categories = report.categories ?? {};

  return {
    performance: categories.performance?.score ?? null,
    accessibility: categories.accessibility?.score ?? null,
    bestPractices: categories["best-practices"]?.score ?? null,
    seo: categories.seo?.score ?? null,
  };
}

function main() {
  const baseUrl = process.argv[2] ?? DEFAULT_BASE_URL;
  const outputDir = join(process.cwd(), "docs/qa");
  mkdirSync(outputDir, { recursive: true });

  const summary: Array<{
    id: string;
    url: string;
    scores: Record<string, number | null>;
    reportPath: string;
  }> = [];

  let failed = false;

  for (const target of TARGETS) {
    const url = new URL(target.path, baseUrl).toString();
    const reportPath = join(outputDir, `lighthouse-${target.id}.json`);

    console.log(`Auditing ${url}`);
    const exitCode = runLighthouse(url, reportPath);

    if (exitCode !== 0) {
      failed = true;
      continue;
    }

    const scores = readScores(reportPath);
    summary.push({ id: target.id, url, scores, reportPath });

    for (const [category, score] of Object.entries(scores)) {
      const formatted = score === null ? "n/a" : Math.round(score * 100);
      console.log(`  ${category}: ${formatted}`);
    }
  }

  const summaryPath = join(outputDir, "lighthouse-summary.json");
  writeFileSync(summaryPath, `${JSON.stringify(summary, null, 2)}\n`);

  const belowTarget = summary.flatMap((entry) =>
    Object.entries(entry.scores)
      .filter(([, score]) => score !== null && score < 0.9)
      .map(([category, score]) => ({
        id: entry.id,
        category,
        score: Math.round((score ?? 0) * 100),
      })),
  );

  if (belowTarget.length > 0) {
    console.error("Scores below 90:");
    console.error(JSON.stringify(belowTarget, null, 2));
    process.exit(1);
  }

  if (failed) {
    process.exit(1);
  }

  console.log(`Summary written to ${summaryPath}`);
}

main();

