import { writeFileSync } from "node:fs";
import { join } from "node:path";

interface ReadinessCheck {
  id: string;
  status: "pass" | "fail";
  detail: string;
}

const DEFAULT_BASE_URL = "https://ecom-gliders.vercel.app";

async function fetchStatus(url: string): Promise<number> {
  const response = await fetch(url, { redirect: "follow" });
  return response.status;
}

async function fetchText(url: string): Promise<string> {
  const response = await fetch(url, { redirect: "follow" });
  if (!response.ok) {
    throw new Error(`HTTP ${response.status} for ${url}`);
  }
  return response.text();
}

function countSitemapUrls(xml: string): number {
  return (xml.match(/<loc>/g) ?? []).length;
}

async function main() {
  const baseUrl = (process.argv[2] ?? DEFAULT_BASE_URL).replace(/\/$/, "");
  const checks: ReadinessCheck[] = [];

  const robotsUrl = `${baseUrl}/robots.txt`;
  const sitemapUrl = `${baseUrl}/sitemap.xml`;
  const homepageUrl = `${baseUrl}/`;

  const [robotsStatus, sitemapStatus, homepageStatus] = await Promise.all([
    fetchStatus(robotsUrl),
    fetchStatus(sitemapUrl),
    fetchStatus(homepageUrl),
  ]);

  checks.push({
    id: "robots-http-200",
    status: robotsStatus === 200 ? "pass" : "fail",
    detail: `${robotsUrl} → HTTP ${robotsStatus}`,
  });

  checks.push({
    id: "sitemap-http-200",
    status: sitemapStatus === 200 ? "pass" : "fail",
    detail: `${sitemapUrl} → HTTP ${sitemapStatus}`,
  });

  checks.push({
    id: "homepage-http-200",
    status: homepageStatus === 200 ? "pass" : "fail",
    detail: `${homepageUrl} → HTTP ${homepageStatus}`,
  });

  const robots = await fetchText(robotsUrl);
  const sitemapReference = robots.includes("Sitemap:") && robots.includes("/sitemap.xml");
  checks.push({
    id: "robots-references-sitemap",
    status: sitemapReference ? "pass" : "fail",
    detail: sitemapReference
      ? "robots.txt includes Sitemap directive"
      : "robots.txt missing Sitemap directive",
  });

  const sitemapXml = await fetchText(sitemapUrl);
  const urlCount = countSitemapUrls(sitemapXml);
  const validXml =
    sitemapXml.includes('xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"') &&
    urlCount >= 340;

  checks.push({
    id: "sitemap-xml-valid",
    status: validXml ? "pass" : "fail",
    detail: `urlset namespace present; ${urlCount} <loc> entries`,
  });

  checks.push({
    id: "sitemap-blog-count",
    status: urlCount >= 340 ? "pass" : "fail",
    detail: `Expected at least 340 URLs (328 blog + static); found ${urlCount}`,
  });

  const sitemapUsesBaseUrl = sitemapXml.includes(`<loc>${baseUrl}/`);
  checks.push({
    id: "sitemap-canonical-host",
    status: sitemapUsesBaseUrl ? "pass" : "fail",
    detail: sitemapUsesBaseUrl
      ? `Sitemap loc URLs use ${baseUrl}`
      : `Sitemap loc URLs do not match ${baseUrl}`,
  });

  const failed = checks.filter((check) => check.status === "fail");

  const report = {
    generatedAt: new Date().toISOString(),
    baseUrl,
    sitemapSubmitUrl: sitemapUrl,
    robotsUrl,
    urlCount,
    checks,
    readyForSearchConsole: failed.length === 0,
    submissionNote:
      "Submit sitemapSubmitUrl in Google Search Console → Sitemaps after property verification.",
  };

  const reportPath = join(process.cwd(), "docs/qa/search-console-readiness.json");
  writeFileSync(reportPath, `${JSON.stringify(report, null, 2)}\n`);
  console.log(JSON.stringify(report, null, 2));

  if (failed.length > 0) {
    process.exit(1);
  }
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

interface SubmissionRecord {
  submittedAt: string;
  property: string;
  sitemapUrl: string;
  searchConsoleStatus: string;
  discoveredUrls?: number;
  submittedBy?: string;
}

interface VerificationCheck {
  id: string;
  status: "pass" | "fail" | "skip";
  detail: string;
}

const SUBMISSION_PATH = join(process.cwd(), "docs/qa/search-console-submission.json");
const TEMPLATE_PATH = join(process.cwd(), "docs/qa/search-console-submission.template.json");

function isValidIsoDate(value: string): boolean {
  const parsed = Date.parse(value);
  return Number.isFinite(parsed);
}

function isValidHttpUrl(value: string): boolean {
  try {
    const url = new URL(value);
    return url.protocol === "https:" || url.protocol === "http:";
  } catch {
    return false;
  }
}

async function fetchSitemapUrlCount(sitemapUrl: string): Promise<number | null> {
  try {
    const response = await fetch(sitemapUrl, { redirect: "follow" });
    if (!response.ok) {
      return null;
    }
    const xml = await response.text();
    return (xml.match(/<loc>/g) ?? []).length;
  } catch {
    return null;
  }
}

async function main() {
  const checks: VerificationCheck[] = [];

  if (!existsSync(SUBMISSION_PATH)) {
    checks.push({
      id: "submission-file-exists",
      status: "fail",
      detail: `Missing ${SUBMISSION_PATH}. Copy ${TEMPLATE_PATH}, submit sitemap in Search Console, then save confirmation.`,
    });

    const report = {
      generatedAt: new Date().toISOString(),
      submissionVerified: false,
      checks,
      nextStep: "Submit sitemap in Google Search Console per docs/seo/SEARCH-CONSOLE-SUBMIT.md",
    };

    console.log(JSON.stringify(report, null, 2));
    process.exit(1);
  }

  checks.push({
    id: "submission-file-exists",
    status: "pass",
    detail: SUBMISSION_PATH,
  });

  let record: SubmissionRecord;
  try {
    record = JSON.parse(readFileSync(SUBMISSION_PATH, "utf8")) as SubmissionRecord;
  } catch (error) {
    checks.push({
      id: "submission-json-valid",
      status: "fail",
      detail: `Invalid JSON: ${error instanceof Error ? error.message : String(error)}`,
    });
    process.exit(1);
  }

  checks.push({
    id: "submission-json-valid",
    status: "pass",
    detail: "JSON parsed successfully",
  });

  const requiredFields: Array<keyof SubmissionRecord> = [
    "submittedAt",
    "property",
    "sitemapUrl",
    "searchConsoleStatus",
  ];

  for (const field of requiredFields) {
    const value = record[field];
    if (typeof value !== "string" || value.trim().length === 0) {
      checks.push({
        id: `field-${field}`,
        status: "fail",
        detail: `Missing or empty required field: ${field}`,
      });
    } else {
      checks.push({
        id: `field-${field}`,
        status: "pass",
        detail: `${field} present`,
      });
    }
  }

  if (record.submittedAt && !isValidIsoDate(record.submittedAt)) {
    checks.push({
      id: "submitted-at-iso",
      status: "fail",
      detail: "submittedAt must be ISO-8601",
    });
  } else if (record.submittedAt) {
    checks.push({
      id: "submitted-at-iso",
      status: "pass",
      detail: record.submittedAt,
    });
  }

  if (record.property && !isValidHttpUrl(record.property)) {
    checks.push({
      id: "property-url",
      status: "fail",
      detail: "property must be a valid URL",
    });
  } else if (record.property) {
    checks.push({
      id: "property-url",
      status: "pass",
      detail: record.property,
    });
  }

  if (record.sitemapUrl && !isValidHttpUrl(record.sitemapUrl)) {
    checks.push({
      id: "sitemap-url",
      status: "fail",
      detail: "sitemapUrl must be a valid URL",
    });
  } else if (record.sitemapUrl) {
    checks.push({
      id: "sitemap-url",
      status: "pass",
      detail: record.sitemapUrl,
    });
  }

  const statusNormalized = record.searchConsoleStatus?.trim().toLowerCase() ?? "";
  if (statusNormalized === "success" || statusNormalized === "submitted") {
    checks.push({
      id: "search-console-status",
      status: "pass",
      detail: record.searchConsoleStatus,
    });
  } else {
    checks.push({
      id: "search-console-status",
      status: "fail",
      detail: `Expected searchConsoleStatus "Success" or "Submitted"; got "${record.searchConsoleStatus ?? ""}"`,
    });
  }

  if (record.sitemapUrl && record.property) {
    try {
      const sitemapHost = new URL(record.sitemapUrl).origin;
      const propertyOrigin = new URL(record.property).origin;
      if (sitemapHost === propertyOrigin || record.property.includes(sitemapHost.replace("https://", ""))) {
        checks.push({
          id: "property-sitemap-host-match",
          status: "pass",
          detail: "Sitemap host matches property",
        });
      } else {
        checks.push({
          id: "property-sitemap-host-match",
          status: "fail",
          detail: `Property ${propertyOrigin} does not match sitemap host ${sitemapHost}`,
        });
      }
    } catch {
      checks.push({
        id: "property-sitemap-host-match",
        status: "skip",
        detail: "Could not compare property and sitemap hosts",
      });
    }
  }

  if (record.sitemapUrl) {
    const liveCount = await fetchSitemapUrlCount(record.sitemapUrl);
    if (liveCount === null) {
      checks.push({
        id: "sitemap-live-fetch",
        status: "fail",
        detail: `Could not fetch live sitemap at ${record.sitemapUrl}`,
      });
    } else {
      checks.push({
        id: "sitemap-live-fetch",
        status: "pass",
        detail: `Live sitemap has ${liveCount} URLs`,
      });

      if (typeof record.discoveredUrls === "number") {
        const delta = Math.abs(record.discoveredUrls - liveCount);
        if (delta <= 5) {
          checks.push({
            id: "discovered-url-count",
            status: "pass",
            detail: `Reported ${record.discoveredUrls} vs live ${liveCount}`,
          });
        } else {
          checks.push({
            id: "discovered-url-count",
            status: "fail",
            detail: `Reported ${record.discoveredUrls} differs from live ${liveCount} by more than 5`,
          });
        }
      }
    }
  }

  const failed = checks.filter((check) => check.status === "fail");
  const submissionVerified = failed.length === 0;

  const reportPath = join(process.cwd(), "docs/qa/search-console-submission-verification.json");
  const report = {
    generatedAt: new Date().toISOString(),
    submissionVerified,
    record: {
      submittedAt: record.submittedAt,
      property: record.property,
      sitemapUrl: record.sitemapUrl,
      searchConsoleStatus: record.searchConsoleStatus,
      discoveredUrls: record.discoveredUrls,
      submittedBy: record.submittedBy,
    },
    checks,
  };

  writeFileSync(reportPath, `${JSON.stringify(report, null, 2)}\n`, "utf8");
  console.log(JSON.stringify(report, null, 2));
  process.exit(submissionVerified ? 0 : 1);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

