export const navLinkSchema = z.object({
  label: z.string().min(1),
  href: z.string().min(1),
  description: z.string().optional(),
  external: z.boolean().optional(),
  featured: z.boolean().optional(),
  icon: z.string().optional(),
});

export const phoneSchema = z.object({
  display: z.string().min(1),
  tel: z.string().min(1),
});

export type NavLink = z.infer<typeof navLinkSchema>;
export type Phone = z.infer<typeof phoneSchema>;

import { z } from "zod";
import { navLinkSchema, phoneSchema } from "./nav-link.schema";

const headerLinkSchema = z.discriminatedUnion("type", [
  z.object({
    id: z.string(),
    label: z.string(),
    type: z.literal("megaMenu"),
  }),
  z.object({
    id: z.string(),
    label: z.string(),
    type: z.literal("link"),
    href: z.string(),
    external: z.boolean().optional(),
  }),
]);

const megaMenuColumnSchema = z.object({
  id: z.string(),
  title: z.string(),
  links: z.array(navLinkSchema),
});

const footerLinkColumnSchema = z.object({
  id: z.string(),
  title: z.string(),
  type: z.literal("brand").or(z.literal("contact")).optional(),
  links: z.array(navLinkSchema).optional(),
});

export const navigationConfigSchema = z.object({
  header: z.object({
    height: z.string(),
    sticky: z.boolean(),
    logoHref: z.string(),
    items: z.array(headerLinkSchema),
    cta: navLinkSchema,
  }),
  megaMenu: z.object({
    triggerId: z.string(),
