  }),
  mobile: z.object({
    menuLabel: z.string(),
    closeLabel: z.string(),
    servicesExpandLabel: z.string(),
  }),
});

export type NavigationConfig = z.infer<typeof navigationConfigSchema>;
export type HeaderNavItem = z.infer<typeof headerLinkSchema>;
