interface NavLinkItemProps {
  link: NavLink;
  className?: string;
  showDescription?: boolean;
  showIcon?: boolean;
}

export function NavLinkItem({
  link,
  className,
  showDescription = false,
  showIcon = false,
}: NavLinkItemProps) {
  const Icon = showIcon ? getNavIcon(link.icon) : null;
  const isFeatured = Boolean(link.featured);

  const content = (
    <>
      {Icon ? (
        <span
          className={cn(
            "mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-sm",
            isFeatured
              ? "bg-accent/15 text-accent"
              : "bg-surface-muted text-text-secondary group-hover:text-primary",
          )}
          aria-hidden="true"
        >
          <Icon className="h-4 w-4" strokeWidth={1.75} />
        </span>
      ) : null}
      <span className="min-w-0 flex-1">
        <span className="flex flex-wrap items-center gap-2">
          <span
            className={cn(
              "font-medium text-text-primary group-hover:text-link-hover",
              isFeatured && "text-primary",
            )}
          >
            {link.label}
          </span>
          {isFeatured ? (
            <span className="rounded-sm bg-surface-muted px-1.5 py-0.5 text-[0.65rem] font-semibold uppercase tracking-wide text-text-secondary">
              Flagship
            </span>
          ) : null}
        </span>
        {showDescription && link.description ? (
          <span className="mt-0.5 block text-small text-text-secondary">
            {link.description}
          </span>
        ) : null}
      </span>
    </>
  );

  const sharedClassName = cn(
    "group flex gap-3 rounded-sm p-2 transition-colors hover:bg-surface-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
    isFeatured &&
      "border border-border bg-surface hover:border-accent/40 hover:bg-surface",
    !isFeatured && "border-l-2 border-transparent hover:border-l-accent",
    className,
  );

  if (link.external) {
    return (
      <a
        href={link.href}
        className={sharedClassName}
        target="_blank"
        rel="noopener noreferrer"
      >
        {content}
      </a>
    );
  }

  return (
    <Link href={link.href} className={sharedClassName}>
      {content}
    </Link>
  );
}

