import { cn } from "@/lib/utils";

interface MegaMenuPanelProps {
  megaMenu: MegaMenuPanelConfig;
  className?: string;
}

export function MegaMenuPanel({ megaMenu, className }: MegaMenuPanelProps) {
  const { columns, ctaPanel, footerLink, compact = true } = megaMenu;
  const columnCount = columns.length;
  const hasCta = Boolean(ctaPanel);

  return (
    <div className={cn("w-full border-t border-border bg-background", className)}>
      <div className="mx-auto w-full max-w-6xl px-4 sm:px-6 lg:px-8">
        <div
          className={cn(
            "grid gap-8",
            compact ? "py-5" : "py-6",
            hasCta
              ? "lg:grid-cols-[minmax(0,1fr)_minmax(200px,240px)] lg:gap-10"
              : null,
          )}
        >
          <div
            className={cn(
              "grid gap-8",
              columnCount >= 4 && "sm:grid-cols-2 lg:grid-cols-4",
              columnCount === 3 && "sm:grid-cols-3",
              columnCount === 2 && "sm:grid-cols-2",
              columnCount === 1 && "grid-cols-1",
            )}
          >
            {columns.map((column) => (
              <div key={column.id}>
                <h3 className="mb-2 text-xs font-semibold uppercase tracking-wide text-text-secondary">
                  {column.title}
                </h3>
                <ul className={cn(compact ? "space-y-0.5" : "space-y-1")}>
                  {column.links.map((link) => (
                    <li key={`${column.id}-${link.href}-${link.label}`}>
                      <NavLinkItem
                        link={link}
                        showDescription
                        compact={compact}
                      />
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>

          {ctaPanel ? (
            <aside className="border-t border-border pt-5 lg:border-l lg:border-t-0 lg:pl-8 lg:pt-0">
              {ctaPanel.eyebrow ? (
                <p className="text-xs font-medium uppercase tracking-wide text-text-secondary">
                  {ctaPanel.eyebrow}
                </p>
              ) : null}
              {ctaPanel.metric ? (
                <p className="mt-1 text-sm font-semibold text-accent">
                  {ctaPanel.metric}
                </p>
              ) : null}
              <h3 className="mt-3 text-sm font-semibold text-text-primary">
                {ctaPanel.title}
              </h3>
              <p className="mt-1 text-xs leading-relaxed text-text-secondary">
                {ctaPanel.body}
              </p>
              <div className="mt-4 space-y-3">
                <PrimaryButton asChild className="h-10 w-full text-sm">
                  <Link href={ctaPanel.button.href}>{ctaPanel.button.label}</Link>
                </PrimaryButton>
                <a
                  href={`tel:${ctaPanel.phone.tel}`}
                  className="block text-xs font-medium text-text-primary underline-offset-4 hover:text-link-hover hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                >
                  {ctaPanel.phone.display}
                </a>
              </div>
            </aside>
          ) : null}
        </div>

        {footerLink ? (
          <div className="border-t border-border py-3">
            <Link
              href={footerLink.href}
              className="text-xs font-medium text-text-primary underline-offset-4 hover:text-link-hover hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
            >
              {footerLink.label}
            </Link>
          </div>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import type { HeaderNavItem, NavigationConfig } from "@/domain/content/schemas";
import { MegaMenuPanel } from "@/components/layout/mega-menu-panel";
import {
  NavigationMenu,
  NavigationMenuContent,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
  NavigationMenuTrigger,
  navigationMenuTriggerStyle,
} from "@/components/ui/navigation-menu";

interface HeaderNavProps {
  items: HeaderNavItem[];
  megaMenus: NavigationConfig["megaMenus"];
}

function HeaderNavLink({
  item,
}: {
  item: Extract<HeaderNavItem, { type: "link" }>;
}) {
  if (item.external) {
    return (
      <NavigationMenuItem>
        <NavigationMenuLink
          href={item.href}
          className={navigationMenuTriggerStyle()}
          target="_blank"
          rel="noopener noreferrer"
        >
          {item.label}
        </NavigationMenuLink>
      </NavigationMenuItem>
    );
  }

  return (
    <NavigationMenuItem>
      <NavigationMenuLink asChild>
        <Link href={item.href} className={navigationMenuTriggerStyle()}>
          {item.label}
        </Link>
      </NavigationMenuLink>
    </NavigationMenuItem>
  );
}

export function HeaderNav({ items, megaMenus }: HeaderNavProps) {
  return (
    <div className="hidden lg:block">
      <NavigationMenu delayDuration={200} className="static max-w-none">
        <NavigationMenuList className="gap-1">
          {items.map((item) => {
            if (item.type === "link") {
              return <HeaderNavLink key={item.id} item={item} />;
            }

            const panel = megaMenus[item.id];
            if (!panel) {
              return null;
            }

            return (
              <NavigationMenuItem key={item.id} value={item.id}>
                <NavigationMenuTrigger aria-label={`${item.label} menu`}>
                  {item.label}
                </NavigationMenuTrigger>
                <NavigationMenuContent className="left-0 top-0 w-screen max-w-none rounded-none border-x-0 p-0">
                  <MegaMenuPanel megaMenu={panel} />
                </NavigationMenuContent>
              </NavigationMenuItem>
            );
          })}
        </NavigationMenuList>
      </NavigationMenu>
    </div>
  );
}

