"use client";

import { useState } from "react";
import Link from "next/link";
import { Menu } from "lucide-react";
import type { HeaderNavItem, NavigationConfig } from "@/domain/content/schemas";
import type { SiteConfig } from "@/domain/content/schemas";
import { FooterLink } from "@/components/layout/footer-link";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { PrimaryButton } from "@/components/ui/primary-button";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { cn } from "@/lib/utils";

interface MobileNavProps {
  navigation: NavigationConfig;
  site: SiteConfig;
  className?: string;
}

function MobileNavLink({
  href,
  label,
  description,
  featured,
  external,
  onNavigate,
}: {
  href: string;
  label: string;
  description?: string;
  featured?: boolean;
  external?: boolean;
  onNavigate: () => void;
}) {
  const className = cn(
    "flex min-h-10 flex-col justify-center rounded-sm px-1 py-1.5 text-sm font-medium text-text-primary transition-colors hover:text-link-hover focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
  );

  const content = (
    <>
      <span className="flex flex-wrap items-baseline gap-x-2">
        <span>{label}</span>
        {featured ? (
          <span className="text-[0.65rem] font-medium uppercase tracking-wide text-accent">
            Featured
          </span>
        ) : null}
      </span>
      {description ? (
        <span className="mt-0.5 text-xs font-normal text-text-secondary">
          {description}
        </span>
      ) : null}
    </>
  );

  if (external) {
    return (
      <a
        href={href}
        className={className}
        target="_blank"
        rel="noopener noreferrer"
        onClick={onNavigate}
      >
        {content}
      </a>
    );
  }

  return (
    <Link href={href} className={className} onClick={onNavigate}>
      {content}
    </Link>
  );
}

export function MobileNav({ navigation, site, className }: MobileNavProps) {
  const [open, setOpen] = useState(false);
  const { header, megaMenus, mobile } = navigation;

  const megaItems = header.items.filter(
    (item): item is Extract<HeaderNavItem, { type: "megaMenu" }> =>
      item.type === "megaMenu" && Boolean(megaMenus[item.id]),
  );
