"use client";

import Link from "next/link";
import type { HeaderNavItem, NavigationConfig } from "@/domain/content/schemas";
import { MegaMenuPanel } from "@/components/layout/mega-menu-panel";
import {
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
  NavigationMenuTrigger,
  navigationMenuTriggerStyle,
} from "@/components/ui/navigation-menu";

interface HeaderNavProps {
  items: HeaderNavItem[];
  megaMenus: NavigationConfig["megaMenus"];
}

function HeaderNavLink({
  item,
}: {
  item: Extract<HeaderNavItem, { type: "link" }>;
}) {
  if (item.external) {
    return (
      <NavigationMenuItem>
        <NavigationMenuLink
          href={item.href}
          className={navigationMenuTriggerStyle()}
          target="_blank"
          rel="noopener noreferrer"
        >
          {item.label}
        </NavigationMenuLink>
      </NavigationMenuItem>
    );
  }

  return (
    <NavigationMenuItem>
      <NavigationMenuLink asChild>
        <Link href={item.href} className={navigationMenuTriggerStyle()}>
          {item.label}
        </Link>
      </NavigationMenuLink>
    </NavigationMenuItem>
  );
}

/** Nav list only — parent must wrap with full-width NavigationMenu for aligned megas. */
export function HeaderNav({ items, megaMenus }: HeaderNavProps) {
  return (
    <NavigationMenuList className="hidden gap-1 lg:flex">
      {items.map((item) => {
        if (item.type === "link") {
          return <HeaderNavLink key={item.id} item={item} />;
        }

        const panel = megaMenus[item.id];
        if (!panel) {
          return null;
        }

        return (
          <NavigationMenuItem key={item.id} value={item.id}>
            <NavigationMenuTrigger aria-label={`${item.label} menu`}>
              {item.label}
            </NavigationMenuTrigger>
            <div className="absolute left-0 top-0 w-full">
              {/* Content is rendered via Radix Content below */}
            </div>
            <NavigationMenuContentWrapper panel={panel} />
          </NavigationMenuItem>
        );
      })}
    </NavigationMenuList>
  );
}

function NavigationMenuContentWrapper({
  panel,
}: {
  panel: NavigationConfig["megaMenus"][string];
}) {
  const { NavigationMenuContent } = require("@/components/ui/navigation-menu") as typeof import("@/components/ui/navigation-menu");

  return (
    <NavigationMenuContent className="left-0 top-0 w-full max-w-none rounded-none border-x-0 p-0 data-[motion]:!transform-none">
      <MegaMenuPanel megaMenu={panel} />
    </NavigationMenuContent>
  );
}

