async (page) => {
  const sites = [
    'https://olifantdigital.com/',
    'https://sequencecommerce.com/',
    'https://canopymanagement.com/',
    'https://myamazonguy.com/',
    'https://amzdudes.com/',
    'https://salesduo.com/',
  ];
  const results = [];
  for (const url of sites) {
    try {
      await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 25000 });
      await page.waitForTimeout(2000);
      const data = await page.evaluate(() => {
        const text = (el) => (el?.textContent || '').replace(/\s+/g, ' ').trim();
        const header = document.querySelector('header') || document.querySelector('[role=banner]');
        const nav = document.querySelector('nav') || header;
        const links = Array.from((nav || document).querySelectorAll('a, button'))
          .map(a => text(a))
          .filter(t => t && t.length < 40 && t.length > 1)
          .slice(0, 40);
        const topBar = document.querySelector('[class*=announce], [class*=top-bar], [class*=topbar], [class*=promo], [class*=banner]')
          || document.body.firstElementChild;
        const firstStrip = text(document.body).slice(0, 280);
        const ctas = Array.from(document.querySelectorAll('a, button'))
          .map(a => text(a))
          .filter(t => /audit|talk|consult|free|plan|get started|book|call|contact/i.test(t))
          .slice(0, 12);
        return {
          title: document.title,
          linksUnique: [...new Set(links)].slice(0, 25),
          ctas: [...new Set(ctas)],
          firstStrip,
        };
      });
      results.push({ url, ok: true, ...data });
    } catch (e) {
      results.push({ url, ok: false, error: String(e).slice(0, 120) });
    }
  }
  return results;
}

async (page) => {
  await page.screenshot({ path: 'E:/Desktop/Projects/ecomGliders/docs/qa/competitor-olifant-header.png', clip: { x: 0, y: 0, width: 1440, height: 120 } });
  return await page.evaluate(() => {
    const bar = document.body.innerText.split('\n').slice(0, 8);
    const cta = Array.from(document.querySelectorAll('a')).find(a => /marketing plan|free/i.test(a.textContent || ''));
    const cs = cta ? getComputedStyle(cta) : null;
    return {
      lines: bar,
      ctaText: cta?.textContent?.trim().slice(0, 60),
      ctaBg: cs?.backgroundColor,
      ctaColor: cs?.color,
      ctaRadius: cs?.borderRadius,
      ctaPad: cs?.padding,
    };
  });
}

