"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { designSystem } from "@/lib/design-tokens";
import { cn } from "@/lib/utils";

export interface PrimaryButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof primaryButtonVariants> {
  asChild?: boolean;
}

const primaryButtonMotion = designSystem.motion.primaryButton as {
  lift: number;
  duration: number;
  ease: [number, number, number, number];
};

const primaryButtonVariants = cva(
  [
    "relative inline-flex h-11 items-center justify-center gap-2 rounded-sm px-5 text-sm font-medium",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2",
    "disabled:pointer-events-none disabled:opacity-50",
  ].join(" "),
  {
    variants: {
      variant: {
        /** Brand navy — forms, secondary bands */
        primary:
          "bg-primary text-text-on-dark shadow-sm transition-colors duration-300 ease-out hover:bg-accent-alt",
        /**
         * Accent conversion CTA — header Free Audit.
         * Pattern: Tier C agencies (AMZ Dudes, SalesDuo) use high-contrast fill
         * distinct from navy chrome so the action stands out.
         */
        accent:
          "bg-accent text-text-on-dark shadow-sm transition-colors duration-300 ease-out hover:bg-accent-alt",
      },
    },
    defaultVariants: {
      variant: "primary",
    },
  },
);

/**
 * Custom minimal motion — sleek lift + soft shadow.
 * Values from content/config/design-system.json → motion.primaryButton
 */
const PrimaryButton = React.forwardRef<HTMLButtonElement, PrimaryButtonProps>(
  ({ className, children, asChild = false, variant, ...props }, ref) => {
    const prefersReducedMotion = useReducedMotion();
    const durationSeconds = primaryButtonMotion.duration / 1000;
    const sharedClassName = cn(primaryButtonVariants({ variant }), className);

    if (asChild) {
      return (
        <Slot className={sharedClassName} ref={ref} {...props}>
          {children}
        </Slot>
      );
    }

    return (
      <motion.button
        ref={ref}
        type={props.type ?? "button"}
        disabled={props.disabled}
        onClick={props.onClick}
        className={sharedClassName}
        whileHover={
          prefersReducedMotion
            ? undefined
            : {
                y: primaryButtonMotion.lift,
                boxShadow:
                  variant === "accent"
                    ? "0 6px 20px rgba(228, 121, 17, 0.28)"
                    : "0 6px 20px rgba(11, 27, 58, 0.15)",
              }
        }
        whileTap={prefersReducedMotion ? undefined : { y: 0, scale: 0.99 }}
        transition={{
          duration: durationSeconds,
          ease: primaryButtonMotion.ease,
        }}
      >
        {children}
      </motion.button>
    );
  },
);
PrimaryButton.displayName = "PrimaryButton";

export { PrimaryButton, primaryButtonVariants };

