import Link from "next/link";
import { ArrowRight, BadgeCheck } from "lucide-react";
import type { SiteConfig } from "@/domain/content/schemas";

interface AnnouncementBarProps {
  site: SiteConfig;
}

export function AnnouncementBar({ site }: AnnouncementBarProps) {
  const { announcementBar } = site;

  if (!announcementBar.enabled || announcementBar.items.length === 0) {
    return null;
  }

  return (
    <div
      className="border-b border-border bg-primary text-text-on-dark"
      role="region"
      aria-label="Site announcements"
    >
      <div className="container-page flex flex-wrap items-center justify-center gap-x-3 gap-y-1 py-2 text-center text-small">
        <BadgeCheck
          className="hidden h-3.5 w-3.5 shrink-0 text-accent sm:inline"
          aria-hidden="true"
        />
        {announcementBar.items.map((item, index) => (
          <span key={item} className="inline-flex items-center gap-3">
            {index > 0 ? (
              <span
                className="hidden text-text-on-dark/40 sm:inline"
                aria-hidden="true"
              >
                ·
              </span>
            ) : null}
            <span>{item}</span>
          </span>
        ))}
        {announcementBar.link ? (
          <Link
            href={announcementBar.link.href}
            className="inline-flex items-center gap-1 font-medium underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-primary"
          >
            {announcementBar.link.label}
            <ArrowRight className="h-3.5 w-3.5" aria-hidden="true" />
          </Link>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { ArrowRight, Phone } from "lucide-react";
import type { NavigationConfig } from "@/domain/content/schemas";
import type { SiteConfig } from "@/domain/content/schemas";
import { BrandLogo } from "@/components/design-system/brand-logo";
import { HeaderNav } from "@/components/layout/header-nav";
import { MobileNav } from "@/components/layout/mobile-nav";
import { PrimaryButton } from "@/components/ui/primary-button";
import { NavigationMenu } from "@/components/ui/navigation-menu";
import { cn } from "@/lib/utils";

interface SiteHeaderShellProps {
  navigation: NavigationConfig;
  site: SiteConfig;
}

export function SiteHeaderShell({ navigation, site }: SiteHeaderShellProps) {
  const [scrolled, setScrolled] = useState(false);
  const { header } = navigation;

  useEffect(() => {
    const onScroll = () => {
      setScrolled(window.scrollY > 4);
    };

    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <header
      className={cn(
        "z-50 w-full border-b border-border bg-background/95 backdrop-blur supports-backdrop-filter:bg-background/90",
        header.sticky && "sticky top-0",
        scrolled ? "shadow-header" : "shadow-none",
      )}
    >
      {/* Full-width NavigationMenu root so mega panels center to the page, not the nav cluster */}
      <NavigationMenu
        delayDuration={200}
        className="relative flex w-full max-w-none flex-none flex-col items-stretch justify-start"
      >
        <div
          className="container-page flex items-center justify-between gap-4"
          style={{ minHeight: header.height }}
        >
          <div className="flex min-w-0 items-center gap-2 sm:gap-3">
            <MobileNav navigation={navigation} site={site} />
            <Link
              href={header.logoHref}
              className="flex shrink-0 items-center rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
