async (page) => {
  const sites = [
    { id: 'mag', url: 'https://myamazonguy.com/', file: 'E:/Desktop/Projects/ecomGliders/docs/qa/competitors/hero-myamazonguy.png' },
    { id: 'amzdudes', url: 'https://amzdudes.com/amazon-account-management-services/', file: 'E:/Desktop/Projects/ecomGliders/docs/qa/competitors/hero-amzdudes-account-mgmt.png' },
    { id: 'canopy', url: 'https://canopymanagement.com/', file: 'E:/Desktop/Projects/ecomGliders/docs/qa/competitors/hero-canopy.png' },
    { id: 'amzonestep', url: 'https://www.amzonestep.com/', file: 'E:/Desktop/Projects/ecomGliders/docs/qa/competitors/hero-amzonestep.png' },
  ];
  const fs = await import('fs');
  try { fs.mkdirSync('E:/Desktop/Projects/ecomGliders/docs/qa/competitors', { recursive: true }); } catch {}
  const results = [];
  await page.setViewportSize({ width: 1440, height: 900 });
  for (const site of sites) {
    try {
      await page.goto(site.url, { waitUntil: 'domcontentloaded', timeout: 35000 });
      await page.waitForTimeout(2500);
      // dismiss common cookie/modals lightly
      for (const label of ['Accept', 'Accept All', 'Got it', 'Close', 'Agree']) {
        const btn = page.getByRole('button', { name: new RegExp('^' + label + '$', 'i') });
        if (await btn.count()) { await btn.first().click({ timeout: 1000 }).catch(() => {}); }
      }
      await page.waitForTimeout(800);
      await page.screenshot({ path: site.file, clip: { x: 0, y: 0, width: 1440, height: 900 } });
      const data = await page.evaluate(() => {
        const t = (el) => (el?.textContent || '').replace(/\s+/g, ' ').trim();
        const h1 = document.querySelector('h1');
        const header = document.querySelector('header');
        const buttons = Array.from(document.querySelectorAll('a, button'))
          .map(a => t(a))
          .filter(x => x && x.length < 48 && /audit|talk|consult|free|get|book|call|start|contact|demo/i.test(x))
          .slice(0, 10);
        const imgs = Array.from(document.querySelectorAll('header img, main img, section img, [class*=hero] img'))
          .slice(0, 8)
          .map(img => ({ alt: img.getAttribute('alt') || '', w: img.naturalWidth || img.width, h: img.naturalHeight || img.height, src: (img.getAttribute('src')||'').slice(0, 80) }));
        const videos = document.querySelectorAll('video').length;
        const bg = getComputedStyle(document.body).backgroundColor;
        // rough hero section: first large section
        const section = document.querySelector('section') || document.querySelector('main') || document.body;
        const sectionBg = section ? getComputedStyle(section).backgroundColor : null;
        return {
          title: document.title,
          h1: t(h1),
          h1FontSize: h1 ? getComputedStyle(h1).fontSize : null,
          h1FontWeight: h1 ? getComputedStyle(h1).fontWeight : null,
          h1Color: h1 ? getComputedStyle(h1).color : null,
          ctas: [...new Set(buttons)],
          imgCountNearTop: imgs.length,
          imgs,
          videos,
          bodyBg: bg,
          sectionBg,
          hasDarkHero: (() => {
            const c = sectionBg || bg;
            const m = c && c.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
            if (!m) return null;
            const r=+m[1],g=+m[2],b=+m[3];
            return (r+g+b)/3 < 80;
          })(),
          firstWords: t(document.body).slice(0, 350),
        };
      });
      results.push({ id: site.id, url: site.url, ok: true, screenshot: site.file, ...data });
    } catch (e) {
      results.push({ id: site.id, url: site.url, ok: false, error: String(e).slice(0, 200) });
    }
  }
  return results;
}

async (page) => {
  const sites = [
