    { id: 'amzonestep', url: 'https://www.amzonestep.com/', file: 'E:/Desktop/Projects/ecomGliders/docs/qa/competitors/hero-amzonestep.png' },
  ];
  const results = [];
  await page.setViewportSize({ width: 1440, height: 900 });
  for (const site of sites) {
    try {
      await page.goto(site.url, { waitUntil: 'domcontentloaded', timeout: 40000 });
      await page.waitForTimeout(3000);
      for (const label of ['Accept All', 'Accept', 'Got it', 'Agree', 'Close']) {
        const btn = page.getByRole('button', { name: new RegExp(label, 'i') });
        if (await btn.count()) { await btn.first().click({ timeout: 800 }).catch(() => {}); }
      }
      await page.waitForTimeout(500);
      await page.screenshot({ path: site.file, clip: { x: 0, y: 0, width: 1440, height: 900 } });
      const data = await page.evaluate(() => {
        const t = (el) => (el?.textContent || '').replace(/\s+/g, ' ').trim();
        const h1 = document.querySelector('h1');
        const buttons = Array.from(document.querySelectorAll('a, button'))
          .map(a => t(a))
          .filter(x => x && x.length > 1 && x.length < 50 && /audit|talk|consult|free|get|book|call|start|contact|demo|apply|schedule/i.test(x))
          .slice(0, 12);
        const imgs = Array.from(document.querySelectorAll('img')).slice(0, 12).map(img => ({
          alt: (img.getAttribute('alt') || '').slice(0, 60),
          w: img.naturalWidth || img.width,
          h: img.naturalHeight || img.height
        }));
        const section = document.querySelector('[class*=hero], section, main') || document.body;
        const sectionBg = getComputedStyle(section).backgroundColor;
        const m = sectionBg && sectionBg.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
        let dark = null;
        if (m) { const avg = (+m[1]+ +m[2]+ +m[3]) / 3; dark = avg < 90; }
        return {
          title: document.title,
          h1: t(h1).slice(0, 160),
          h1FontSize: h1 ? getComputedStyle(h1).fontSize : null,
          h1FontWeight: h1 ? getComputedStyle(h1).fontWeight : null,
          ctas: [...new Set(buttons)].slice(0, 8),
          videos: document.querySelectorAll('video').length,
          sectionBg,
          darkHeroGuess: dark,
          topImgs: imgs.filter(i => i.w > 100 || i.h > 100).slice(0, 6),
          firstWords: t(document.body).slice(0, 400),
        };
      });
      results.push({ id: site.id, url: site.url, ok: true, screenshot: site.file, ...data });
    } catch (e) {
      results.push({ id: site.id, url: site.url, ok: false, error: String(e).slice(0, 220) });
    }
  }
  return results;
}

