import Image from "next/image";
import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { BrowserMockup } from "@/components/browser-mockup";
import { PrimaryButton } from "@/components/ui/primary-button";
import {
  readNavLink,
  readRecordArray,
  readString,
  readStringRecord,
} from "./section-data";
import { SectionShell } from "./section-shell";

interface HeroSectionProps {
  id: string;
  data: Record<string, unknown>;
}

export function HeroSection({ id, data }: HeroSectionProps) {
  const eyebrow = readString(data.eyebrow);
  const headline = readString(data.headline);
  const subheadline = readString(data.subheadline);
  const supportLine = readString(data.supportLine);
  const trustLine = readString(data.trustLine);
  const primaryCta = readNavLink(data.primaryCta);
  const secondaryCta = readNavLink(data.secondaryCta);
  const partnerBadge =
    data.partnerBadge && typeof data.partnerBadge === "object"
      ? (data.partnerBadge as Record<string, unknown>)
      : null;
  const partnerBadgeLabel = readString(partnerBadge?.label);
  const partnerBadgeImage = readString(partnerBadge?.image);
  const partnerBadgeHref = readString(partnerBadge?.href);
  const metricOverlays = readRecordArray(data.metricOverlays)
    .map((item) => ({
      value: readString(item.value),
      label: readString(item.label),
    }))
    .filter((item) => item.value && item.label)
    .slice(0, 2);

  const visual = data.visual as Record<string, unknown> | undefined;
  const tabIds = readStringRecord(visual?.tabIds);
  const desktopVariant =
    readString(visual?.desktopVariant, "macos") === "ios" ? "ios" : "macos";
  const mobileVariant =
    readString(visual?.mobileVariant, "ios") === "macos" ? "macos" : "ios";

  return (
    <SectionShell
      id={id}
      ariaLabelledBy={`${id}-heading`}
      className="relative overflow-hidden py-14 sm:py-16 lg:py-20"
    >
      <div
        className="pointer-events-none absolute inset-y-0 right-0 hidden w-1/2 bg-[radial-gradient(ellipse_at_70%_40%,rgba(11,27,58,0.06),transparent_65%)] lg:block"
        aria-hidden="true"
      />

      <div className="relative grid items-center gap-12 lg:grid-cols-[minmax(0,1.05fr)_minmax(0,0.95fr)] lg:gap-14">
        <div className="max-w-xl">
          {eyebrow ? (
            <p className="text-xs font-semibold uppercase tracking-wide text-text-secondary">
              {eyebrow}
            </p>
          ) : null}

          <h1
            id={`${id}-heading`}
            className="mt-3 text-hero text-text-primary text-balance"
          >
            {headline}
          </h1>

          {subheadline ? (
            <p className="mt-5 text-body text-text-secondary text-pretty">
              {subheadline}
            </p>
          ) : null}

          {primaryCta || secondaryCta ? (
            <div className="mt-8 flex flex-wrap items-center gap-x-6 gap-y-3">
              {primaryCta ? (
                <PrimaryButton asChild variant="accent">
                  <Link href={primaryCta.href}>
                    {primaryCta.label}
                    <ArrowRight className="h-4 w-4" aria-hidden="true" />
                  </Link>
                </PrimaryButton>
              ) : null}
              {secondaryCta ? (
                <Link
                  href={secondaryCta.href}
                  className="inline-flex min-h-11 items-center text-sm font-medium text-text-primary underline-offset-4 transition-colors hover:text-link-hover hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                >
                  {secondaryCta.label}
                </Link>
              ) : null}
            </div>
          ) : null}

          {supportLine ? (
            <p className="mt-5 text-small text-text-secondary">{supportLine}</p>
          ) : null}

          {partnerBadgeImage || trustLine ? (
            <div className="mt-6 flex flex-wrap items-center gap-3">
              {partnerBadgeImage ? (
                partnerBadgeHref ? (
                  <a
                    href={partnerBadgeHref}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2"
                  >
                    <Image
                      src={partnerBadgeImage}
                      alt={partnerBadgeLabel || "Partner badge"}
                      width={140}
                      height={40}
                      className="h-8 w-auto"
                    />
                  </a>
                ) : (
                  <Image
                    src={partnerBadgeImage}
                    alt={partnerBadgeLabel || "Partner badge"}
                    width={140}
                    height={40}
                    className="h-8 w-auto"
                  />
                )
              ) : null}
              {partnerBadgeImage && trustLine ? (
                <span
                  className="hidden h-4 w-px bg-border sm:inline-block"
                  aria-hidden="true"
                />
              ) : null}
              {trustLine ? (
                <p className="text-small text-text-secondary">{trustLine}</p>
              ) : null}
            </div>
          ) : null}
        </div>

        <div className="relative mx-auto w-full max-w-lg lg:mx-0 lg:max-w-none">
          <div
            className="absolute -inset-6 rounded-[2rem] bg-[radial-gradient(circle_at_50%_40%,rgba(228,121,17,0.08),transparent_60%)] sm:-inset-8"
            aria-hidden="true"
          />

          <div className="relative">
            <div className="hidden lg:block">
              <BrowserMockup
                variant={desktopVariant}
                tabId={tabIds[desktopVariant]}
              />
            </div>
            <div className="lg:hidden">
              <BrowserMockup
                variant={mobileVariant}
                tabId={tabIds[mobileVariant]}
              />
            </div>

            {metricOverlays.length > 0 ? (
              <div className="pointer-events-none absolute inset-x-3 bottom-3 flex flex-col gap-2 sm:inset-x-auto sm:bottom-6 sm:-left-3 sm:right-auto lg:-left-6">
                {metricOverlays.map((metric, index) => (
                  <div
                    key={`${metric.value}-${metric.label}`}
                    className={
                      index === 0
                        ? "rounded-md border border-border bg-background/95 px-3 py-2 shadow-md backdrop-blur-sm sm:min-w-[9.5rem]"
                        : "hidden rounded-md border border-border bg-background/95 px-3 py-2 shadow-md backdrop-blur-sm sm:block sm:min-w-[9.5rem] sm:translate-x-4"
                    }
                  >
                    <p className="text-sm font-semibold text-accent">
                      {metric.value}
                    </p>
                    <p className="text-xs text-text-secondary">{metric.label}</p>
                  </div>
                ))}
              </div>
            ) : null}
          </div>
        </div>
      </div>
    </SectionShell>
  );
}

