import { cn } from "@/lib/utils";
import { BrowserMockupChart } from "./browser-mockup-chart";
import type { BrowserTab } from "./browser-mockup.types";

interface BrowserMockupContentProps {
  current: BrowserTab;
  compact?: boolean;
}

export function BrowserMockupContent({
