            <p
              className={cn(
                "mt-0.5 text-text-secondary",
                compact ? "text-[10px]" : "text-xs",
              )}
            >
              {stat.label}
            </p>
            <div className="mt-2 h-0.5 overflow-hidden rounded-full bg-border">
              <div
                className="h-full rounded-full bg-accent"
                style={{ width: `${stat.progress}%` }}
              />
            </div>
          </div>
        ))}
      </div>

      <div className="mt-3 overflow-hidden rounded-md border border-border">
        <table className={cn("w-full text-left", textSize)}>
          <thead>
            <tr className="border-b border-border bg-surface">
              <th
                className="px-2.5 py-2 font-medium text-text-secondary sm:px-3"
                scope="col"
              >
                Campaign
              </th>
              <th
                className="px-2.5 py-2 font-medium text-text-secondary sm:px-3"
                scope="col"
              >
                Spend
              </th>
              <th
                className="px-2.5 py-2 text-right font-medium text-text-secondary sm:px-3"
                scope="col"
              >
                Change
              </th>
            </tr>
          </thead>
          <tbody>
            {tableRows.map((row) => (
              <tr key={row.label} className="border-b border-border last:border-0">
                <td className="px-2.5 py-2 text-text-primary sm:px-3">{row.label}</td>
                <td className="px-2.5 py-2 font-medium text-text-primary sm:px-3">
                  {row.value}
                </td>
                <td
                  className={cn(
                    "px-2.5 py-2 text-right font-medium sm:px-3",
                    row.positive ? "text-success" : "text-text-secondary",
                  )}
                >
                  {row.change}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

