async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(800);
  const chrome = await page.evaluate(() => {
    const figs = Array.from(document.querySelectorAll('#hero figure'));
    const visible = figs.find(f => getComputedStyle(f.parentElement || f).display !== 'none' && (f.parentElement ? getComputedStyle(f.parentElement).display !== 'none' : true));
    // find figure whose parent is not display none
    const desktopFig = figs.find(f => {
      let el = f.parentElement;
      while (el) {
        const d = getComputedStyle(el).display;
        if (d === 'none') return false;
        el = el.parentElement;
        if (el && el.id === 'hero') break;
      }
      return f.className.includes('w-full');
    });
    const fig = desktopFig || figs[0];
    const topBar = fig?.querySelector('.bg-surface-muted');
    return {
      topBarText: topBar?.textContent?.replace(/\s+/g,' ').trim(),
      rotateCw: Boolean(fig?.querySelector('.lucide-rotate-cw')),
      share: Boolean(fig?.querySelector('.lucide-share')),
      htmlSnippet: topBar?.innerHTML?.slice(0, 500),
      tabLabels: topBar?.textContent,
    };
  });
  const loc = page.locator('#hero .hidden.lg\\:block figure, #hero div.hidden.lg\\:block figure').first();
  const box = await page.locator('#hero').locator('div.hidden.lg\\:block').locator('figure').boundingBox().catch(() => null);
  const alt = await page.evaluate(() => {
    const wrap = document.querySelector('#hero .hidden.lg\\:block') || document.querySelector('#hero [class*="lg:block"]');
    // fallback: query by class list
    const all = Array.from(document.querySelectorAll('#hero div'));
    const w = all.find(d => d.className.includes('hidden') && d.className.includes('lg:block'));
    const fig = w?.querySelector('figure');
    const r = fig?.getBoundingClientRect();
    return r ? { x: r.x, y: r.y, width: r.width, height: Math.min(r.height, 400) } : null;
  });
  if (alt) {
    await page.screenshot({
      path: 'E:/Desktop/Projects/ecomGliders/docs/qa/hero-browser-chrome-closeup.png',
      clip: { x: Math.max(0, alt.x), y: Math.max(0, alt.y), width: alt.width, height: alt.height },
    });
  }
  return { chrome, alt, box };
}

