() => { const canvas = document.createElement('canvas'); const w = 1440, h = 900; canvas.width = w; canvas.height = h; const ctx = canvas.getContext('2d'); // can't draw CSS ::before easily; sample from a temp div with same bg
 const probe = document.createElement('div'); probe.style.cssText = 'position:fixed;inset:0;z-index:-2;pointer-events:none;background-image:' + getComputedStyle(document.documentElement).getPropertyValue('--brand-page-atmosphere'); document.body.appendChild(probe); // use getComputedStyle of probe and approximate via elementFromPoint under transparent areas
 const samples = [[40,80],[720,80],[1400,80],[40,450],[720,450],[1400,800]].map(([x,y]) => { const el = document.elementFromPoint(x,y); const bg = el ? getComputedStyle(el).backgroundColor : null; return {x,y, tag: el?.tagName, class: (el?.className||'').toString().slice(0,50), bg}; }); probe.remove(); return { atmosphereLen: getComputedStyle(document.documentElement).getPropertyValue('--brand-page-atmosphere').length, samples }; }

