() => { // draw atmosphere onto canvas via CSS paint approx by creating offscreen element and reading via foreignObject is hard; instead check pixels by temporarily covering page
 const overlay = document.createElement('div');
 overlay.id = 'atm-probe';
 overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;pointer-events:none;background-image:' + getComputedStyle(document.documentElement).backgroundImage + ';background-size:cover;background-attachment:fixed';
 document.body.appendChild(overlay);
 // Use html2canvas-less: sample via getImageData not available. Return corners style from computed.
 const cs = getComputedStyle(overlay);
 const out = { image: cs.backgroundImage.includes('radial-gradient'), layers: (cs.backgroundImage.match(/radial-gradient/g)||[]).length + (cs.backgroundImage.match(/linear-gradient/g)||[]).length };
 overlay.remove();
 return out;
}

